/* 知识百科数据库 - 成语故事 + 十万个为什么 + 百科知识 */
const KNOWLEDGE_DATA = {
  // ===== 成语故事 =====
  idiomStories: [
    { title: '画蛇添足', idiom: '画蛇添足', story: '楚国人祭祀后赏给门客一壶酒，大家比赛画蛇，先画完者饮酒。一人先画完，得意地给蛇添脚。另一人画完夺过酒壶说：蛇本无脚，你为何添？那人最终失了酒。', meaning: '比喻做了多余的事，反而把事情弄糟。' },
    { title: '刻舟求剑', idiom: '刻舟求剑', story: '楚国人渡江时剑掉入水中，他在船舷刻下记号说：剑从这里掉下。船到岸后，他从刻记号处下水找剑。船已走远，剑不会随船走，哪里找得到？', meaning: '比喻办事刻板，不知随客观情况变化而改变方法。' },
    { title: '亡羊补牢', idiom: '亡羊补牢', story: '农夫羊圈破了，狼叼走一只羊。邻居劝他修补，他不听。第二天又丢一只，他赶忙修好羊圈，此后羊再没丢过。', meaning: '比喻出了问题后想办法补救，可防止继续受损。' },
    { title: '掩耳盗铃', idiom: '掩耳盗铃', story: '小偷想偷门前的铃铛，怕铃响被人发现，便捂住自己耳朵去摘。他以为听不见铃声别人也听不见，结果一碰铃就被抓住了。', meaning: '比喻自己欺骗自己，明明掩盖不住偏要想法子掩盖。' },
    { title: '拔苗助长', idiom: '拔苗助长', story: '宋国农夫嫌禾苗长得慢，把每棵禾苗都往上拔高一点，累得筋疲力尽回家炫耀。儿子跑去一看，禾苗全枯死了。', meaning: '比喻违反事物发展规律，急于求成，反而把事情弄糟。' },
    { title: '守株待兔', idiom: '守株待兔', story: '农夫见一只兔子撞死在田边树桩上，从此丢下农具整天守在树桩旁等兔子。再没等到兔子，田里却长满荒草。', meaning: '比喻死守狭隘经验，或抱着侥幸心理妄想不劳而获。' },
    { title: '南辕北辙', idiom: '南辕北辙', story: '有人要去南方的楚国却驾车往北走。朋友劝他，他说马快、钱多、车夫技术好。方向错了，条件越好离楚国越远。', meaning: '比喻行动和目的相反，方向错了离目标越远。' },
    { title: '买椟还珠', idiom: '买椟还珠', story: '楚国人用名贵木兰木做装珍珠的盒子，雕花镶金熏香。郑人爱不释手，买下盒子却把珍珠还给楚人。', meaning: '比喻没有眼光，取舍不当，只重外表忽略价值。' },
    { title: '滥竽充数', idiom: '滥竽充数', story: '齐宣王听三百人齐吹竽，不会吹竽的南郭先生混在其中装样子拿赏赐。齐湣王继位后要一个一个独奏，南郭先生只好逃跑。', meaning: '比喻没有真才实学的人混在行家里面充数。' },
    { title: '狐假虎威', idiom: '狐假虎威', story: '老虎抓住狐狸，狐狸说天帝派它做百兽之王，让老虎跟在后面看百兽怕不怕。野兽见老虎跟来纷纷逃走，老虎以为它们怕狐狸。', meaning: '比喻倚仗别人的势力来欺压或吓唬人。' },
    { title: '鹬蚌相争', idiom: '鹬蚌相争', story: '河蚌晒太阳，鹬啄它肉被夹住嘴。鹬说今日不雨明日不雨就有死蚌，蚌说今日不松明日不松就有死鹬。渔夫走来把它们都抓走。', meaning: '比喻双方相持不下，两败俱伤，让第三者得利。' },
    { title: '井底之蛙', idiom: '井底之蛙', story: '井里青蛙对海龟夸口井中自在。海龟讲大海辽阔无边，青蛙才知自己见识短浅，吃惊地张大嘴巴。', meaning: '比喻见识短浅的人。' },
    { title: '杞人忧天', idiom: '杞人忧天', story: '杞人担心天会塌地会陷，寝食难安。朋友说天是气体到处都有，地是土块填满四方，他才放心。', meaning: '比喻不必要的、没有根据的忧虑和担心。' },
    { title: '塞翁失马', idiom: '塞翁失马', story: '边塞老人丢马后得骏马，儿子骑马摔断腿，却因跛脚免征兵保全性命。祸福相依，事情好坏相互转化。', meaning: '比喻坏事在一定条件下可变为好事，祸福相依。' },
    { title: '自相矛盾', idiom: '自相矛盾', story: '楚人卖矛和盾，先夸盾什么刺不破，又夸矛什么都能刺穿。有人问用你的矛刺你的盾会怎样，他哑口无言。', meaning: '比喻自己的言行前后互相抵触，不能自圆其说。' },
    { title: '叶公好龙', idiom: '叶公好龙', story: '叶公到处画龙刻龙，自夸爱龙。真龙听说下凡探望，头探进窗户。叶公一见真龙，吓得面如土色，掉头就跑。', meaning: '比喻表面上爱好某事物，实际上并不真爱甚至惧怕。' },
    { title: '黔驴技穷', idiom: '黔驴技穷', story: '贵州的驴被老虎试探，驴只会尥蹶子踢腿。老虎知其本领不过如此，猛扑上去咬断驴喉咙吃了它。', meaning: '比喻有限的一点本领已经用完，再无别的办法。' },
    { title: '画龙点睛', idiom: '画龙点睛', story: '张僧繇在安乐寺画四条龙不点睛，说点了会飞走。众人不信，他给两条龙点上眼睛，顿时雷电大作，两龙破壁飞去。', meaning: '比喻在关键处用一两句话点明要旨，使内容更生动有力。' },
    { title: '望洋兴叹', idiom: '望洋兴叹', story: '河伯见黄河宽阔自得意，顺流到北海见白浪无边无际，才叹自己渺小，仰头对海神叹息。', meaning: '比喻看见别人伟大而自愧不如，或力量不够无可奈何。' },
    { title: '邯郸学步', idiom: '邯郸学步', story: '燕国少年羡慕邯郸人走路美，专门去学。学来学去没学会，反而忘了自己原来的走法，只好爬着回了燕国。', meaning: '比喻一味模仿别人，不但学不到本事，反丢了自己本色。' },
    { title: '东施效颦', idiom: '东施效颦', story: '丑女东施学美女西施皱眉捂胸的样子在村里走，结果更加难看，乡邻紧闭大门或赶紧躲开。', meaning: '比喻盲目模仿别人，效果适得其反，更加难看。' },
    { title: '庖丁解牛', idiom: '庖丁解牛', story: '庖丁宰牛顺着牛的肌理下刀，刀在骨节空隙游走，十九年刀如新。他说已掌握牛的规律，所以游刃有余。', meaning: '比喻经过反复实践掌握事物客观规律，做事得心应手。' },
    { title: '朝三暮四', idiom: '朝三暮四', story: '狙公给猴子橡子，说早三晚四，猴子怒；改说早四晚三，猴子喜。其实总数一样，只是玩弄手法。', meaning: '原指玩弄手法欺骗人，后比喻常常变卦，反复无常。' },
    { title: '螳螂捕蝉', idiom: '螳螂捕蝉', story: '蝉饮露不知螳螂在后，螳螂不知黄雀在后，黄雀不知少年持弹在下。各只顾眼前利益不顾身后祸患。', meaning: '比喻只顾眼前利益，而不顾身后隐藏的祸患。' },
    { title: '鹏程万里', idiom: '鹏程万里', story: '鹏鸟展翅击水三千里，扶摇直上九万里飞往南海。蝉雀讥笑它飞那么高远做什么，哪知鹏鸟的志向。', meaning: '比喻前程远大，前途无量。' },
    { title: '游刃有余', idiom: '游刃有余', story: '庖丁以薄刃入牛骨节空隙，运转自如，十九年刀如新磨，因他已掌握牛的结构规律。', meaning: '比喻技术熟练，经验丰富，解决问题毫不费力。' },
    { title: '班门弄斧', idiom: '班门弄斧', story: '梅之涣诗云：鲁班门前弄大斧。在祖师爷鲁班面前卖弄斧头技术，实在可笑不自量力。', meaning: '比喻在行家面前卖弄本领，不自量力。' },
    { title: '对牛弹琴', idiom: '对牛弹琴', story: '公明仪对牛弹高雅曲子，牛不理会。他改弹蚊蝇嗡嗡和小牛叫声，牛才停下吃草仔细听。', meaning: '比喻对不懂道理的人讲道理，也讥笑说话不看对象。' },
    { title: '杯弓蛇影', idiom: '杯弓蛇影', story: '朋友饮酒见杯中似有蛇，勉强喝下后病倒。乐广查明是墙上弓的倒影，取下弓蛇影消失，朋友病愈。', meaning: '比喻因疑神疑鬼而引起恐惧，自己吓唬自己。' },
    { title: '杯水车薪', idiom: '杯水车薪', story: '一车柴草着火，有人端一杯水去浇，嗤一声蒸发殆尽，火反而烧得更旺，根本无济于事。', meaning: '比喻力量太小，解决不了问题。' },
    { title: '抱薪救火', idiom: '抱薪救火', story: '魏国被秦打败后割地求和。苏代劝魏王：割地求和就像抱柴救火，柴不尽火不灭，越割秦越强。魏王不听，终被秦灭。', meaning: '比喻用错误的方法去消除灾祸，结果反而使灾祸扩大。' },
    { title: '防微杜渐', idiom: '防微杜渐', story: '丁鸿见外戚势力渐大，劝汉和帝坏事刚露头就制止，如修堤补洞、治病早医，不能让它发展。', meaning: '比喻在坏事情刚露头时就加以防止，不让它发展。' },
    { title: '未雨绸缪', idiom: '未雨绸缪', story: '诗经写道：趁天还没下雨，用桑皮把鸟巢空隙缠紧加固。聪明的鸟天晴就修窝，下雨就不怕淋了。', meaning: '比喻事先做好准备，防患于未然。' },
    { title: '临渴掘井', idiom: '临渴掘井', story: '晏子说：渴了才挖井，淹了才造船，使尽全力也来不及。劝人不要事到临头才想办法。', meaning: '比喻事到临头才想办法，为时已晚。' },
    { title: '弄巧成拙', idiom: '弄巧成拙', story: '弟子给孙知微画中童子手里加水晶瓶，本想添彩，反显多余笨拙，破坏了整幅画。', meaning: '本想耍弄聪明做得好些，结果反而做了蠢事。' },
    { title: '狗尾续貂', idiom: '狗尾续貂', story: '司马伦大封党羽，貂尾官帽不够用，用狗尾巴代替。百姓讥讽：貂不足，狗尾续。', meaning: '比喻拿不好的东西接在好的东西后面，好坏不相称。' },
    { title: '画饼充饥', idiom: '画饼充饥', story: '魏明帝说名声就像地上画的饼，能看不能吃。卢毓说名声也能发现一般人才。', meaning: '比喻用空想来安慰自己，不能解决实际问题。' },
    { title: '望梅止渴', idiom: '望梅止渴', story: '曹操行军缺水，指着前方说：前面有大片梅林，梅子又酸又甜。士兵想起酸梅流口水，不觉渴了，振作前进。', meaning: '比喻用空想安慰自己或他人，以解决眼前困难。' },
    { title: '螳臂当车', idiom: '螳臂当车', story: '螳螂举起前腿要挡齐庄公的车轮。庄公说它若是人定是勇士，绕道而行。', meaning: '比喻不估计自己的力量而去做做不到的事，必然失败。' },
    { title: '蚍蜉撼树', idiom: '蚍蜉撼树', story: '韩愈诗云：蚍蜉撼大树，可笑不自量。蚂蚁想摇动大树，实在不自量力。', meaning: '比喻自不量力。' },
    { title: '曲高和寡', idiom: '曲高和寡', story: '宋玉说有人在城里唱高雅的《阳春白雪》，跟着唱的只有几十人；唱通俗的歌，跟着唱的有数千人。', meaning: '比喻言论或作品高雅深奥，能懂的人很少。' },
    { title: '渔翁得利', idiom: '渔翁得利', story: '鹬啄蚌肉被夹住嘴，互不相让。渔夫走来毫不费力地把它们一起抓走了。', meaning: '比喻双方相争，第三者从中得利。' },
    { title: '画虎类犬', idiom: '画虎类犬', story: '马援告诫侄子：刻鹄不成尚类鹜，画虎不成反类犬。好高骛远反而弄巧成拙更难看。', meaning: '比喻好高骛远，反而弄巧成拙，成笑柄。' },
    { title: '刻鹄类鹜', idiom: '刻鹄类鹜', story: '马援说刻天鹅即使没刻好还像鸭子，比画虎不成像狗要好，仿效虽不到家还不失大概。', meaning: '比喻仿效虽不成功，但还相似，比好高骛远好。' },
    { title: '狼狈为奸', idiom: '狼狈为奸', story: '传说狼和狈合伙干坏事，狼靠狈出主意，狈靠狼行动，相互勾结做坏事。', meaning: '比喻互相勾结干坏事。' },
    { title: '卧薪尝胆', idiom: '卧薪尝胆', story: '越王勾践被吴打败后到吴为奴三年。回国后他睡柴草、每天尝苦胆，不忘屈辱，与百姓同甘共苦，十年后终灭吴雪耻。', meaning: '形容人刻苦自励，发愤图强。' },
    { title: '破釜沉舟', idiom: '破釜沉舟', story: '项羽率军渡漳水后，命士兵凿沉船只、砸碎锅碗、烧毁营帐，只带三天干粮，置之死地而后生，大败秦军。', meaning: '比喻下定决心，不顾一切干到底。' },
    { title: '完璧归赵', idiom: '完璧归赵', story: '蔺相如带和氏璧入秦，见秦王无意偿城，以璧有瑕疵取回宝玉，靠柱怒喝威胁撞碎。秦王怕璧碎，相如趁机派人连夜送璧回赵。', meaning: '比喻把原物完好无损地归还原主。' },
    { title: '负荆请罪', idiom: '负荆请罪', story: '廉颇不服蔺相如位高，相如以国为重处处忍让。廉颇知后惭愧，脱上衣背荆条到相如门前请罪，二人结为生死之交。', meaning: '表示向人认错赔罪，诚恳道歉。' },
    { title: '纸上谈兵', idiom: '纸上谈兵', story: '赵括熟读兵书却无实战经验，长平之战照书本主动出击，被秦军包围，四十万赵军全军覆没。', meaning: '比喻空谈理论，不能解决实际问题。' },
    { title: '四面楚歌', idiom: '四面楚歌', story: '项羽被围垓下，夜里闻四面汉营唱楚歌，以为楚地尽失，军心涣散。与虞姬诀别后突围至乌江自刎。', meaning: '比喻陷入四面受敌、孤立无援的困境。' },
    { title: '指鹿为马', idiom: '指鹿为马', story: '赵高为试探群臣，牵鹿上殿对秦二世说这是马。群臣有的附和，有的说鹿，事后说真话的大臣都被害死。', meaning: '比喻故意颠倒黑白，混淆是非。' },
    { title: '三顾茅庐', idiom: '三顾茅庐', story: '刘备为请诸葛亮出山，三次到隆中茅屋拜访。第三次冒雪在门外恭候直到诸葛亮醒来，诚意打动他出山相助。', meaning: '比喻真心诚意，一再邀请拜访贤人。' },
    { title: '闻鸡起舞', idiom: '闻鸡起舞', story: '祖逖和刘琨半夜听到鸡叫，就起床练剑，从不间断。后来祖逖率军北伐收复大片失地，建功立业。', meaning: '比喻有志报国的人奋发图强，抓紧时间努力。' },
    { title: '投笔从戎', idiom: '投笔从戎', story: '班超家贫靠抄书度日，他扔下笔感叹：大丈夫应像张骞那样建功立业，怎能老在笔砚间讨生活？后参军出使西域封定远侯。', meaning: '比喻放弃文墨生涯，参加军队，投身疆场。' },
    { title: '程门立雪', idiom: '程门立雪', story: '杨时和游酢请教程颐，程颐正闭目养神。二人不忍打扰，在门外恭立等候，雪深一尺仍恭敬站立，程颐深受感动。', meaning: '比喻学生恭敬求教，尊师重道。' },
    { title: '凿壁偷光', idiom: '凿壁偷光', story: '匡衡家贫买不起蜡烛，在墙上凿洞借邻居烛光夜读。后来拜师学习，成为大学问家，官至丞相。', meaning: '形容家境贫寒却勤学苦读。' },
    { title: '悬梁刺股', idiom: '悬梁刺股', story: '孙敬读书时把头发系在房梁上防瞌睡；苏秦读书犯困就用锥子刺大腿。两人刻苦读书终成大器。', meaning: '形容人刻苦学习，废寝忘食。' },
    { title: '铁杵成针', idiom: '铁杵成针', story: '李白逃学遇到老婆婆磨铁杵，说要磨成绣花针。老婆婆说只要功夫深铁杵磨成针。李白深受感动发愤读书成大诗人。', meaning: '比喻只要有毅力，肯下功夫，再难的事也能成功。' },
    { title: '毛遂自荐', idiom: '毛遂自荐', story: '平原君要挑二十门客赴楚求救只挑出十九人，毛遂自荐凑数。到楚国后他凭口才说服楚王出兵救赵。', meaning: '比喻自告奋勇，自己推荐自己担任某项工作。' },
    { title: '退避三舍', idiom: '退避三舍', story: '晋公子重耳流亡楚国时许诺日后交战退避三舍。后重耳回国为君，晋楚交战时晋军果然后退九十里，诱敌深入大败楚军。', meaning: '比喻对人让步，不与人相争。' },
    { title: '一鼓作气', idiom: '一鼓作气', story: '长勺之战，曹刿待齐军擂鼓三次后才命鲁军出击。他说一鼓振作二鼓衰退三鼓耗尽，敌气衰我气盛故胜。', meaning: '比喻趁劲头大的时候一下子把事情做完。' },
    { title: '胸有成竹', idiom: '胸有成竹', story: '画家文同四季观察竹子，画竹时心中早有竹的形象，一挥而就栩栩如生。苏轼说他画竹必先得成竹于胸中。', meaning: '比喻做事之前已经有充分的考虑和把握。' },
    { title: '水滴石穿', idiom: '水滴石穿', story: '县令张乖崖判偷钱小吏：一日一钱千日千钱，绳锯木断水滴石穿。滴水不断能穿石，坚持必成。', meaning: '比喻力量虽小，但坚持不懈，事情就能成功。' },
    { title: '一字千金', idiom: '一字千金', story: '吕不韦编成《吕氏春秋》悬于咸阳城门，悬赏千金请人增减一字，结果无人敢动，形容文章精妙价值极高。', meaning: '形容诗文作品写得极好，价值极高。' },
    { title: '入木三分', idiom: '入木三分', story: '王羲之在木板上写字，工匠刻字时发现墨迹渗入木板三分深，可见用笔之遒劲有力。', meaning: '形容书法笔力强劲，也比喻分析议论深刻透彻。' },
    { title: '洛阳纸贵', idiom: '洛阳纸贵', story: '左思用十年写成《三都赋》，洛阳人争相传抄，纸张供不应求价格大涨，形容作品广为流传。', meaning: '比喻著作广泛流传，风行一时。' },
    { title: '鸡鸣狗盗', idiom: '鸡鸣狗盗', story: '孟尝君被困秦国，靠门客装狗偷出狐白裘献宠妃获释，逃到函谷关靠门客学鸡叫骗开城门逃脱。', meaning: '比喻微不足道的本领，也指偷偷摸摸的行为。' },
    { title: '狡兔三窟', idiom: '狡兔三窟', story: '冯谖为孟尝君烧借据买民心，又谋退路，说狡兔三窟才能免患，如今一窟不够，需多谋退路。', meaning: '比喻藏身的地方多，便于躲避灾祸。' },
    { title: '背水一战', idiom: '背水一战', story: '韩信背水列阵，将士后退即落水，无路可退只能拼死作战，置之死地而后生，以少胜多大败赵军。', meaning: '比喻处于绝境之中，为求生路而决一死战。' },
    { title: '暗度陈仓', idiom: '暗度陈仓', story: '韩信明面上派人修栈道迷惑敌人，暗中率大军绕道陈仓突袭，打了章邯措手不及，平定关中。', meaning: '比喻用假象迷惑对方，暗中实现目的。' },
    { title: '图穷匕见', idiom: '图穷匕见', story: '荆轲献督亢地图给秦王，地图展到最后露出藏的匕首。荆轲抓秦王袖刺之，未成被杀。', meaning: '比喻事情发展到最后，真相或本意显露出来。' },
    { title: '刮目相看', idiom: '刮目相看', story: '吕蒙发愤读书后学问大进，鲁肃感叹。吕蒙说：士别三日即更刮目相待，不能用老眼光看人。', meaning: '比喻别人已有进步，不能再用老眼光看待。' },
    { title: '手不释卷', idiom: '手不释卷', story: '孙权劝吕蒙读书，说自己比他们更忙却从不放下书本。吕蒙从此勤读，手不释卷，学问大进。', meaning: '形容勤学不倦，手里总是拿着书。' },
    { title: '开卷有益', idiom: '开卷有益', story: '宋太宗每天读三卷《太平御览》，一年读完。别人劝他少读，他说我喜欢读书开卷有益不觉劳累。', meaning: '读书总会有好处，常用作勉励人读书。' },
    { title: '不耻下问', idiom: '不耻下问', story: '孔圉死后谥为文。子贡问孔子为何，孔子说他聪明好学，不以向地位低下的人请教为耻，所以谥为文。', meaning: '比喻谦虚好学，不以向不如自己的人请教为耻。' },
    { title: '韦编三绝', idiom: '韦编三绝', story: '孔子晚年爱读《周易》，反复翻阅，串竹简的牛皮带子都断了好多次，每次断了就换新的继续读。', meaning: '形容读书刻苦勤奋。' },
    { title: '废寝忘食', idiom: '废寝忘食', story: '孔子在齐国听到《韶》乐，沉醉其中三个月吃不出肉味，专心到顾不得睡觉吃饭。', meaning: '顾不得睡觉，忘记了吃饭，形容专心努力。' },
    { title: '老马识途', idiom: '老马识途', story: '齐军出征迷路，管仲让人挑几匹老马走在前面，老马凭记忆找到回路，大军安全返齐。', meaning: '比喻有经验的人对事情比较熟悉，能起引导作用。' },
    { title: '伯乐相马', idiom: '伯乐相马', story: '伯乐认出拉盐车的瘦马是千里马，买下精心饲养成宝马，并把相马经验写成书传授后人。', meaning: '比喻善于发现人才、识别人才的人。' },
    { title: '多多益善', idiom: '多多益善', story: '刘邦问韩信能统多少兵，韩信说陛下最多十万。问韩信自己，他说多多益善。刘邦笑问怎么反被擒，韩信说陛下善统将。', meaning: '形容越多越好。' },
    { title: '成也萧何', idiom: '成也萧何', story: '萧何月下追韩信并荐为大将，是成也萧何；后吕后让萧何设计骗杀韩信，是败也萧何。成败皆因萧何。', meaning: '比喻事情的成败都由同一个人造成。' },
    { title: '十面埋伏', idiom: '十面埋伏', story: '韩信设十面埋伏之计，把项羽楚军层层围于垓下，又用四面楚歌瓦解斗志，项羽突围失败自刎乌江。', meaning: '比喻设下重重包围，使敌人无处逃遁。' },
    { title: '居安思危', idiom: '居安思危', story: '魏绛劝晋悼公：居安思危，思则有备，有备无患。处在安定的环境要想到可能出现的危险。', meaning: '处在安定的环境中要想到可能发生的危险。' },
    { title: '防患未然', idiom: '防患未然', story: '易经说君子以思患而豫防之，在灾祸发生之前就加以防备，可以避免损失，如堵堤防洞防决堤。', meaning: '在事故或灾害尚未发生时采取预防措施。' },
    { title: '一字之师', idiom: '一字之师', story: '齐己写早梅诗有数枝开，郑谷说数枝不算早改一枝。齐己觉得改得好连忙拜谢，称郑谷为一字之师。', meaning: '比喻能改正一个字使文章更完善的老师。' },
    { title: '得过且过', idiom: '得过且过', story: '寒号虫夏天长满羽毛得意唱凤凰不如我，冬天冻僵说过且过不垒窝，最终冻死，形容不思进取。', meaning: '只要勉强过得去就这样过下去，也指敷衍了事。' },
    { title: '草木皆兵', idiom: '草木皆兵', story: '苻坚在淝水败退时，望八公山草木摇动以为都是晋兵，惊惧万分，形容惊慌时疑神疑鬼。', meaning: '把山上的草木都当做敌兵，形容惊慌时疑神疑鬼。' },
    { title: '黄粱一梦', idiom: '黄粱一梦', story: '卢生在客店枕瓷枕入梦，梦中享尽荣华富贵经历一生沉浮，醒来时店主煮的黄粱饭还没熟，一切皆空。', meaning: '比喻虚幻不能实现的梦想或欲望的破灭。' },
    { title: '南柯一梦', idiom: '南柯一梦', story: '淳于棼梦入槐安国做南柯郡太守享尽荣华，醒来发现槐安国只是槐树下蚂蚁洞，南柯只是南枝下蚁穴。', meaning: '形容一场大梦，或比喻一场空欢喜。' },
    { title: '精卫填海', idiom: '精卫填海', story: '炎帝小女儿女娃淹死东海，灵魂化作精卫鸟，每天衔西山木石投东海，誓要填平大海，日复一日从不歇息。', meaning: '比喻不畏艰难，坚持不懈地奋斗。' },
    { title: '夸父逐日', idiom: '夸父逐日', story: '巨人夸父立志追赶太阳，追到日落处口渴难耐，喝干黄河渭水仍不解渴，北去大泽途中渴死，手杖化作桃林。', meaning: '比喻有宏大志向和巨大力量，也比喻不自量力。' },
    { title: '愚公移山', idiom: '愚公移山', story: '愚公年近九十，率家人挖太行王屋二山。智叟嘲笑，愚公说子孙无穷而山不增高终会挖平。天帝感动派神背走山。', meaning: '比喻坚持不懈地改造自然和坚定不移地斗争。' },
    { title: '女娲补天', idiom: '女娲补天', story: '天塌地陷灾祸四起，女娲炼五色石补天，斩龟足撑天，杀黑龙，积芦灰止洪水，拯救了苍生。', meaning: '比喻改造天地的雄伟气魄和大无畏的斗争精神。' },
    { title: '后羿射日', idiom: '后羿射日', story: '天上十日并出烤焦大地，后羿拉神弓射下九个太阳，留一个照耀大地，百姓从此安居乐业。', meaning: '比喻战胜自然、征服自然的英雄气概和勇敢精神。' },
    { title: '嫦娥奔月', idiom: '嫦娥奔月', story: '嫦娥为防仙药落入坏人之手，吞下仙药飞上月宫。后羿思念嫦娥，每年八月十五摆月饼望月寄托思念。', meaning: '比喻为正义和善良而不惜牺牲个人幸福的精神。' },
    { title: '八仙过海', idiom: '八仙过海', story: '八位神仙去蓬莱仙岛，吕洞宾提议各显神通不用乘船。他们各用法宝乘风破浪渡过东海。', meaning: '比喻各有各的办法和本领，各自拿出本领完成任务。' },
    { title: '开天辟地', idiom: '开天辟地', story: '盘古挥神斧劈开混沌，轻者上升为天重者下降为地。他头顶天脚踩地一万八千年，身死后化为世间万物。', meaning: '比喻有史以来第一次，也形容极其伟大的事业。' },
    { title: '大禹治水', idiom: '大禹治水', story: '禹继承父业治水，改堵塞为疏导，疏通河道引洪水入海。治水十三年三过家门而不入，终于治好水患。', meaning: '比喻为民造福、公而忘私的精神。' },
    { title: '神农尝草', idiom: '神农尝草', story: '神农为给百姓治病，亲尝百草辨别药性，一日中七十种毒仍不停止，教会人们种五谷、用药草。', meaning: '比喻为造福人类勇于探索和献身的精神。' },
    { title: '仓颉造字', idiom: '仓颉造字', story: '黄帝史官仓颉观察鸟兽足迹和山川形胜，创造了文字，使人类得以记载历史传承文明。传说造字时天雨粟鬼夜哭。', meaning: '比喻文化开创的伟大事件。' },
    { title: '庄周梦蝶', idiom: '庄周梦蝶', story: '庄子梦见自己变成蝴蝶翩翩起舞，不知自己是庄周。醒来却又是庄周，不知是庄周梦蝶还是蝶梦庄周。', meaning: '比喻虚幻的事物或人生如梦。' },
    { title: '三过家门', idiom: '三过家门', story: '大禹治水十三年，三次路过家门都没进去，听到儿子啼哭也忍住，全身心投入治水终获成功。', meaning: '形容舍小家为大家，公而忘私。' },
    { title: '惊弓之鸟', idiom: '惊弓之鸟', story: '更羸只拉弓弦不射箭，一只受过伤的大雁听到弦声就掉下来。它受过箭伤，听到弦声就害怕挣扎旧伤发作而落。', meaning: '比喻受过惊吓的人，遇到一点动静就非常害怕。' },
    { title: '一鸣惊人', idiom: '一鸣惊人', story: '齐威王三年不理朝政，大臣说有大鸟三年不飞不鸣。齐威王说此鸟不飞则已一飞冲天，不鸣则已一鸣惊人，从此勤政。', meaning: '比喻平时没有特殊表现，一下子做出惊人的成绩。' },
    { title: '一箭双雕', idiom: '一箭双雕', story: '北朝长孙晟武艺高强，一次随使团出使突厥，天上有两只大雕争肉，他一箭射去，两雕同时被射落，众人叹服。', meaning: '比喻做一件事达到两个目的。' },
    { title: '一诺千金', idiom: '一诺千金', story: '西汉季布为人守信，答应别人的事一定做到。当时流传：得黄金百斤不如得季布一诺，形容他的承诺比金子还贵重。', meaning: '形容说话算数，极有信用。' },
    { title: '三人成虎', idiom: '三人成虎', story: '庞葱问魏王：一人说街上有虎你信吗？不信。两人呢？半信。三人呢？信。庞葱说三人言而成虎，谣言传多了就有人信。', meaning: '比喻谣言或讹传一再重复，就可能使人信以为真。' },
    { title: '大器晚成', idiom: '大器晚成', story: '三国时崔琰的堂弟崔林年轻时默默无闻，崔琰说大器晚成，好材料做成大器物需要更长时间。后来崔林果然成大才。', meaning: '比喻能担当重任的人物要经过长期的锻炼，所以成就较晚。' },
    { title: '天衣无缝', idiom: '天衣无缝', story: '传说郭翰夏夜乘凉，遇天上织女下凡，见她衣服没有缝。郭翰问怎么没缝，织女说天衣本非针线所做，哪来缝隙。', meaning: '比喻事物浑然天成，没有破绽，十分完美。' },
    { title: '半途而废', idiom: '半途而废', story: '乐羊子外出求学，中途因想家而归来。妻子拿刀割断织布机上的布说：求学和织布一样，半途而废就会前功尽弃。乐羊子深受感动回去完成学业。', meaning: '比喻做事不能坚持到底，中途停顿，有始无终。' },
    { title: '举一反三', idiom: '举一反三', story: '孔子说：教导学生不到他苦思冥想仍不明白时不启发他，举出一个角不能推想到其他三个角的，我就不再教他了。', meaning: '比喻从一件事情类推而知道其他许多事情。' },
    { title: '事半功倍', idiom: '事半功倍', story: '孟子说当今齐国若推行仁政，效果会比古人好，因为用力少而收效大，这叫事半功倍。', meaning: '形容用力小，收效大。' },
    { title: '囫囵吞枣', idiom: '囫囵吞枣', story: '有人对吃梨和枣发表看法，一人说梨益齿伤脾，枣益脾伤齿。另一人说那我吃梨只嚼不咽，吃枣只吞不嚼，囫囵吞下。', meaning: '比喻对事物不加分析思考，笼统地接受。' },
    { title: '夜郎自大', idiom: '夜郎自大', story: '汉代夜郎国君问汉朝使者：汉朝和夜郎哪个大？夜郎只有汉一郡之大，却妄自尊大，不知天高地厚。', meaning: '比喻人见识短浅却妄自尊大。' },
    { title: '安步当车', idiom: '安步当车', story: '战国时齐人颜斶不愿做官，齐宣王留他。他说晚食以当肉，安步以当车，无罪以当贵，清静贞正以自娱。', meaning: '比喻从容步行代替乘车，也指安贫乐道。' },
    { title: '异曲同工', idiom: '异曲同工', story: '韩愈评价不同的文章：曲调虽然不同但同样精妙，这叫异曲同工。不同的方法或风格可以达到同样好的效果。', meaning: '不同的曲调演得同样好，比喻不同方法收到同样效果。' },
    { title: '悬崖勒马', idiom: '悬崖勒马', story: '骑着马跑到悬崖边及时勒住缰绳停住，没有掉下去。比喻在危险边缘及时醒悟回头，避免灾祸发生。', meaning: '比喻到了危险的边缘及时清醒回头。' },
    { title: '捷足先登', idiom: '捷足先登', story: '汉代蒯通对韩信说：秦失其鹿，天下共逐之，疾足者先得。意思是谁跑得快谁先得到，后指行动快的人先达到目的。', meaning: '比喻行动敏捷的人先达到目的。' },
    { title: '熟能生巧', idiom: '熟能生巧', story: '陈尧咨善射自矜，卖油翁看他射箭微微点头。翁取一葫芦盖孔放铜钱，舀油从钱孔倒入不湿钱。说我不过是熟能生巧。', meaning: '熟练了就能产生巧办法，或找出窍门。' },
    { title: '鹤立鸡群', idiom: '鹤立鸡群', story: '晋代嵇绍身材高大仪表堂堂，一次入洛阳，有人对王戎说：昨天见到嵇绍，在人群中如野鹤立于鸡群，出众非常。', meaning: '比喻人的仪表或才能在一群人中显得很突出。' },
    { title: '锲而不舍', idiom: '锲而不舍', story: '荀子说：雕刻东西不停地刻下去，金石也能刻穿；如果半途而废，朽木也刻不断。学习要锲而不舍才能成功。', meaning: '比喻有恒心，有毅力，坚持到底，毫不松懈。' },
    { title: '雪中送炭', idiom: '雪中送炭', story: '宋太宗冬天大雪，想到缺衣少食的穷人，派人送去柴炭粮食。在别人最困难时给予帮助，比锦上添花更可贵。', meaning: '比喻在别人急需时给予物质上或精神上的帮助。' },
    { title: '青出于蓝', idiom: '青出于蓝', story: '荀子说：青色是从蓝草中提取的，却比蓝草更蓝。比喻学生胜过老师，后人胜过前人，后辈超过前辈。', meaning: '比喻学生超过老师，或后人胜过前人。' },
    { title: '风声鹤唳', idiom: '风声鹤唳', story: '淝水之战，前秦苻坚大败溃逃，士兵听到风声和鹤的叫声，都以为是晋军追来，吓得拼命逃跑，溃不成军。', meaning: '形容惊慌失措，自相惊扰。' },
    { title: '老骥伏枥', idiom: '老骥伏枥', story: '曹操写诗：老骥伏枥，志在千里；烈士暮年，壮心不已。年老的千里马虽伏在马槽旁，仍有驰骋千里的志向。', meaning: '比喻有志向的人虽然年老，仍有雄心壮志。' },
    { title: '舍本逐末', idiom: '舍本逐末', story: '战国时齐王问赵威后收成百姓怎样，使者奇怪为何先问贱后问贵。赵威后说没有百姓哪有国君，舍本逐末才是错的。', meaning: '比喻做事不抓根本，而只顾细枝末节。' },
    { title: '舍生取义', idiom: '舍生取义', story: '孟子说鱼和熊掌不可兼得时，舍鱼而取熊掌；生命和道义不可兼得时，舍生而取义。为正义可以牺牲生命。', meaning: '为正义而牺牲生命。' },
    { title: '触类旁通', idiom: '触类旁通', story: '周易说引而申之，触类而长之，天下之能事毕矣。掌握一事物的知识，就能类推懂得同类的其他事物。', meaning: '掌握某一事物的知识，就能类推了解同类的其他事物。' },
    { title: '赴汤蹈火', idiom: '赴汤蹈火', story: '汉代晁错说：要让人为你赴汤蹈火，必须以诚相待。形容不畏艰险，哪怕沸水烈火也敢于去闯。', meaning: '比喻不避艰险，奋勇向前。' },
    { title: '趁热打铁', idiom: '趁热打铁', story: '铁匠打铁要趁铁烧红时锤打，才能打成想要的形状。比喻做事要抓紧有利时机，趁热打铁一气呵成。', meaning: '比喻做事抓紧时机，加速进行。' },
    { title: '路不拾遗', idiom: '路不拾遗', story: '商鞅变法后秦国大治，东西掉在路上没人捡走据为己有，形容社会风气好，百姓遵纪守法。', meaning: '形容社会风气好，路上掉的东西没人捡。' },
    { title: '迎刃而解', idiom: '迎刃而解', story: '晋代杜预伐吴，有人说春天雨水多不利作战应等冬天。杜预说现在军威大振，势如破竹，几节之后迎刃而解。', meaning: '比喻主要问题解决了，其他问题就容易解决。' },
    { title: '逐鹿中原', idiom: '逐鹿中原', story: '蒯通对韩信说：秦失其鹿，天下共逐之，高材者先得。鹿比喻帝位政权，群雄争夺天下叫逐鹿中原。', meaning: '比喻群雄并起，争夺天下。' },
    { title: '金石为开', idiom: '金石为开', story: '李广夜里把石头当老虎一箭射去，箭头深深扎进石头。他说只要心诚，连金石这样坚硬的东西也能打开。', meaning: '比喻只要诚心诚意，再难的事也能办成。' },
    { title: '破镜重圆', idiom: '破镜重圆', story: '南朝陈将亡，徐德言与乐昌公主破镜各执一半，约定正月十五卖镜寻妻。陈亡后公主入杨素府，正月十五老人卖镜，二人终在杨素成全下重圆。', meaning: '比喻夫妻失散或决裂后重新团聚与和好。' },
    { title: '盲人摸象', idiom: '盲人摸象', story: '几个盲人摸大象，摸腿的说象像柱子，摸耳朵的说像扇子，摸尾巴的说像绳子。各执一词争吵不休，其实都没说全。', meaning: '比喻对事物只凭片面的了解就下结论，以偏概全。' },
    { title: '目无全牛', idiom: '目无全牛', story: '庖丁解牛技艺高超，眼中看到的不再是整头牛，而是牛的内部结构。比喻技艺达到纯熟境界，得心应手。', meaning: '比喻技艺极其纯熟，达到得心应手的境界。' },
    { title: '老当益壮', idiom: '老当益壮', story: '东汉马援说：丈夫为志，穷当益坚，老当益壮。年岁虽老，志气应当更加旺盛。后他年过花甲仍请缨出征。', meaning: '年纪虽老，志气更旺盛，干劲更足。' },
    { title: '萍水相逢', idiom: '萍水相逢', story: '王勃写滕王阁序：萍水相逢，尽是他乡之客。浮萍随水漂泊偶然相遇，比喻素不相识的人偶然相遇。', meaning: '比喻素不相识的人偶然相遇。' },
    { title: '落井下石', idiom: '落井下石', story: '韩愈说：有人落井，不但不救，反而投下石头。比喻趁人有危难时加以陷害，雪上加霜。', meaning: '比喻趁人有危难时加以陷害。' },
    { title: '虚怀若谷', idiom: '虚怀若谷', story: '老子说：敦兮其若朴，旷兮其若谷。胸怀像山谷一样深广空虚，能容纳别人的意见，形容十分谦虚。', meaning: '形容十分谦虚，能容纳别人的意见。' },
    { title: '蛛丝马迹', idiom: '蛛丝马迹', story: '蜘蛛的丝和马的痕迹都很细微，但顺着这些线索可以找到真相。比喻事情留下的隐约可寻的痕迹和线索。', meaning: '比喻事情留下的隐约可寻的痕迹和线索。' },
    { title: '袖手旁观', idiom: '袖手旁观', story: '把手缩在袖子里在一旁观看，比喻置身事外，不参与其中，也不帮助别人。', meaning: '比喻置身事外，既不参与，也不帮助别人。' },
    { title: '豁然开朗', idiom: '豁然开朗', story: '陶渊明写桃花源记：林尽水源，便得一山，从口入，豁然开朗。由狭窄幽暗突然变得宽阔明亮，形容一下子明白过来。', meaning: '形容由狭窄幽暗突然变得宽阔明亮，也指一下子领悟。' },
    { title: '改过自新', idiom: '改过自新', story: '汉代淳于意获罪，女儿缇萦上书愿为官婢赎父罪。汉文帝感动，废肉刑。淳于意得以改过自新重新做人。', meaning: '改正错误，重新做人。' },
    { title: '旗鼓相当', idiom: '旗鼓相当', story: '两军对阵，旗帜和战鼓势均力敌，不分上下。比喻双方实力不相上下，难分高低。', meaning: '比喻双方力量不相上下。' },
    { title: '水落石出', idiom: '水落石出', story: '苏轼写：山高月小，水落石出。水位下降后石头露出来。比喻事情的真相完全显露出来。', meaning: '比喻事情的真相完全显露出来。' },
    { title: '汗马功劳', idiom: '汗马功劳', story: '战马奔驰出汗，形容征战的劳苦。后指在战争中或工作中立下的功劳。韩信打下江山立下汗马功劳。', meaning: '指在战争中立下的功劳，也泛指作出的贡献。' },
    { title: '沧海桑田', idiom: '沧海桑田', story: '神仙麻姑说：自接侍以来，已见东海三为桑田。大海变成桑田，比喻世事变化很大。', meaning: '比喻世事变化很大。' },
    { title: '燕雀安知', idiom: '燕雀安知', story: '陈胜年轻时被人雇用种地，他说：苟富贵勿相忘。同伴笑他，他叹道：燕雀安知鸿鹄之志哉！燕雀哪能懂得天鹅的志向。', meaning: '比喻平庸的人哪里知道英雄伟人的志向。' },
    { title: '独树一帜', idiom: '独树一帜', story: '单独树起一面旗帜，比喻自成一家，有自己的独特风格，与众不同。形容在艺术或学术上独创一派。', meaning: '比喻自成一家，独创一派，与众不同。' },
    { title: '玩物丧志', idiom: '玩物丧志', story: '《尚书》说：玩人丧德，玩物丧志。沉迷于所喜爱的事物，就会丧失进取的志向。卫懿公好鹤亡国就是例子。', meaning: '指迷恋于所玩赏的事物而消磨了进取心。' },
    { title: '画地为牢', idiom: '画地为牢', story: '相传上古时在地上画圈当监狱，犯人留在圈内不能出去，比喻只许在指定的范围内活动。也比喻自我束缚。', meaning: '比喻只许在指定的范围内活动，也比喻自我束缚。' },
    { title: '畏首畏尾', idiom: '畏首畏尾', story: '左传载：畏首畏尾，身其余几。怕头又怕尾，身子还能剩下多少。比喻胆小怕事，疑虑太多。', meaning: '比喻胆小怕事，疑虑重重。' },
    { title: '疾风知劲草', idiom: '疾风知劲草', story: '汉光武帝刘秀对王霸说：颍川从我者皆逝，而子独留，努力！疾风知劲草。大风过后才知道哪种草坚韧。', meaning: '比喻在严峻的考验中才能显示出谁的意志坚强。' },
    { title: '笨鸟先飞', idiom: '笨鸟先飞', story: '飞得慢的鸟先起飞，比喻能力差的人做事比别人先动手，用勤奋弥补不足。也用作谦辞。', meaning: '比喻能力差的人做事怕落后，便比别人先动手。' },
    { title: '精诚所至', idiom: '精诚所至', story: '庄子说：真者，精诚之至也。不精不诚，不能动人。真诚所到之处，连金石也能打开，形容诚心能打动一切。', meaning: '比喻人的诚心所到，能感动天地，使金石为开。' },
    { title: '耳濡目染', idiom: '耳濡目染', story: '耳朵经常听到，眼睛经常看到，不知不觉地受到影响。韩愈说孩子受父母耳濡目染，言行举止都会相像。', meaning: '耳朵经常听到，眼睛经常看到，不知不觉地受到影响。' },
    { title: '聚沙成塔', idiom: '聚沙成塔', story: '把细沙聚集成佛塔，比喻把零散的东西积少成多，就能成为很大的数量。法华经说乃至童子戏聚沙为佛塔。', meaning: '比喻聚少成多，积小成大。' },
    { title: '节衣缩食', idiom: '节衣缩食', story: '省吃省穿，节约衣服和食物，形容生活非常节俭，把省下的钱用在更需要的地方。陆游诗云节衣缩食为读书。', meaning: '省吃省穿，形容生活节俭。' },
    { title: '福无双至', idiom: '福无双至', story: '俗语说福无双至，祸不单行。幸运的事不会接连到来，灾祸却往往接踵而至。劝人遇福莫骄，遇祸莫馁。', meaning: '幸运的事不会连续到来。' },
    { title: '祸不单行', idiom: '祸不单行', story: '俗语说福无双至，祸不单行。灾祸往往不会单独发生，一件接一件。提醒人们遇祸要提高警惕，防患未然。', meaning: '指不幸的事接连发生。' },
    { title: '矢志不移', idiom: '矢志不移', story: '立下誓言决心不改变，发誓立志后坚定不移。形容意志坚定，无论遇到什么困难都不改变初衷。', meaning: '发誓立志，决不改变。' },
    { title: '轻而易举', idiom: '轻而易举', story: '事情很轻很容易就能举起办到，形容事情容易做，不费力气。就像举起轻的东西一样简单。', meaning: '形容事情容易做，不费力气。' },
    { title: '远水救近火', idiom: '远水救近火', story: '战国时鲁国想联合晋国对抗齐国，有人劝说不必舍近求远，因为远水解不了近渴，远水救不了近火。比喻慢办法救不了急。', meaning: '比喻缓慢的救助不能解决眼前的急难。' },
    { title: '醉翁之意', idiom: '醉翁之意', story: '欧阳修写醉翁亭记：醉翁之意不在酒，在乎山水之间也。本意不在酒，而在于山水之乐。比喻本意不在此而在别的方面。', meaning: '比喻本意不在此而另有所图。' },
    { title: '名落孙山', idiom: '名落孙山', story: '孙山考中末名回家，有人问儿子考中没有，孙山说解名尽处是孙山，贤郎更在孙山外。意为你儿子排在我后面，没考上。', meaning: '比喻考试或选拔没有被录取。' },
    { title: '名列前茅', idiom: '名列前茅', story: '春秋时楚国行军，前军用茅草当旗帜开路。后把名次排在前面叫名列前茅，形容成绩优秀，名次靠前。', meaning: '比喻名次排在前面，成绩优秀。' },
    { title: '同舟共济', idiom: '同舟共济', story: '孙武说：吴越同舟共济，遇风相救如左右手。同乘一条船渡河的人，遇到风浪会互相救助，比喻齐心协力共渡难关。', meaning: '比喻团结互助，同心协力，战胜困难。' },
    { title: '后生可畏', idiom: '后生可畏', story: '孔子说：后生可畏，焉知来者之不如今也。年轻人值得敬畏，怎知他们将来的成就不如现在的人呢。', meaning: '青年人很容易超过老一辈，令人敬畏。' },
    { title: '因势利导', idiom: '因势利导', story: '孙膑说作战要因势利导，顺着事物发展的趋势加以引导。马陵之战他顺应魏军轻敌的心理，减灶诱敌，大败魏军。', meaning: '顺着事情发展的趋势，向有利于实现目的的方向引导。' },
    { title: '坚持不懈', idiom: '坚持不懈', story: '坚持到底，毫不松懈。形容做事有恒心有毅力，不半途而废。无论多困难都不放弃，直到达到目标。', meaning: '坚持到底，一点不松懈。' },
    { title: '奉公守法', idiom: '奉公守法', story: '赵国赵奢收租时，平原君家不肯交，赵奢依法处死其管家。他说奉公守法则上下平。平原君认为他有才，荐他理国。', meaning: '奉行公事，遵守法令。' },
    { title: '安居乐业', idiom: '安居乐业', story: '老子说：民各甘其食，美其服，安其居，乐其俗。百姓生活安定，安居乐业，是治理国家的理想状态。', meaning: '安定地生活，愉快地工作。' },
    { title: '差强人意', idiom: '差强人意', story: '东汉吴汉作战总是振奋精神，光武帝说：吴公差强人意，隐若一敌国矣。意思是勉强还能让人满意，还算不错。', meaning: '大体上还能使人满意。' },
    { title: '开诚布公', idiom: '开诚布公', story: '诸葛亮辅佐后主，坦诚无私，公开公正地处理政事。后人评他开诚心布公道，形容诚意待人，坦白无私。', meaning: '诚意待人，坦白无私。' },
    { title: '弄假成真', idiom: '弄假成真', story: '三国时周瑜用假招亲之计想困住刘备，不料弄假成真，刘备真的娶了孙权妹妹并安然返回，周瑜赔了夫人又折兵。', meaning: '本来是假装的，结果却变成真事。' },
    { title: '形影不离', idiom: '形影不离', story: '形体和影子分不开，比喻关系十分亲密，常在一起。像身体和影子一样，到哪里都在一起，不分离。', meaning: '形容关系十分亲密，常在一起。' },
    { title: '忘恩负义', idiom: '忘恩负义', story: '忘记别人对自己的恩情，做出对不起别人的事。农夫救活冻僵的蛇，蛇醒后反咬农夫一口，是典型的忘恩负义。', meaning: '忘记别人对自己的恩德，做出对不起别人的事。' },
    { title: '忠言逆耳', idiom: '忠言逆耳', story: '张良劝刘邦接受秦宫珍宝不可取时说：忠言逆耳利于行，良药苦口利于病。诚恳的劝告虽不顺耳，却有利于行事。', meaning: '诚恳的劝告听起来不顺耳，但对人有好处。' },
    { title: '急中生智', idiom: '急中生智', story: '司马光小时候见同伴掉进大水缸，急中生智搬起石头砸破水缸，水流出来救了同伴。形容在紧急情况下突然想出好办法。', meaning: '在紧急情况下突然想出好办法。' },
    { title: '恩将仇报', idiom: '恩将仇报', story: '用仇恨报答恩惠，忘恩负义反过来伤害帮助过自己的人。农夫救活冻僵的蛇，蛇却咬死农夫，是典型的恩将仇报。', meaning: '忘恩负义，用仇恨报答恩惠。' },
    { title: '摩拳擦掌', idiom: '摩拳擦掌', story: '战斗或比赛前，大家摩拳擦掌，跃跃欲试。形容做事前振奋精神，跃跃欲试的样子，准备大干一场。', meaning: '形容做事前振奋精神，跃跃欲试的样子。' },
    { title: '朝气蓬勃', idiom: '朝气蓬勃', story: '早晨的气息充满生机活力，形容精神振奋，生气勃勃，充满活力。少年人应当朝气蓬勃，奋发向上。', meaning: '形容精神振奋，生气勃勃，充满活力。' },
    { title: '欢呼雀跃', idiom: '欢呼雀跃', story: '高兴得像麻雀一样跳跃欢呼，形容非常高兴，欢腾跳跃的样子。孩子们听到放假的消息欢呼雀跃。', meaning: '高兴得像雀鸟一样跳跃，形容十分欢乐。' },
    { title: '此起彼伏', idiom: '此起彼伏', story: '这里起来那里落下，形容一起一落，接连不断。海浪此起彼伏，连绵不绝。也形容声音、事物起伏不断。', meaning: '这里起来，那里落下，表示连续不断。' },
    { title: '吐故纳新', idiom: '吐故纳新', story: '庄子说：吹呴呼吸，吐故纳新。呼出浊气吸入新鲜空气。比喻扬弃旧的吸收新的，也指呼吸健身。', meaning: '比喻扬弃旧的，吸收新的。' },
    { title: '好逸恶劳', idiom: '好逸恶劳', story: '喜欢安逸，厌恶劳动。后唐庄宗李存勖好逸恶劳，贪图享乐，最终导致身死国灭，是前车之鉴。', meaning: '贪图安逸，厌恶劳动。' },
    { title: '不可救药', idiom: '不可救药', story: '诗经讽刺周厉王：病到不可救药的地步。比喻人或事物坏到无法挽救的程度，就像病重得治不好了。', meaning: '比喻人或事物坏到无法挽救的地步。' },
    { title: '不学无术', idiom: '不学无术', story: '汉书评霍光：不学亡术，暗于大理。没有学问也没有本领。形容既没有学问又没有能力。', meaning: '没有学问，没有本领。' },
    { title: '东山再起', idiom: '东山再起', story: '东晋谢安隐居东山，后国家危难他再度出山任职，指挥淝水之战大败前秦。比喻失势后重新恢复地位。', meaning: '比喻失势后重新恢复地位或势力。' },
    { title: '两袖清风', idiom: '两袖清风', story: '于谦进京不带礼物，写诗说两袖清风朝天去。衣袖里只有清风，形容做官廉洁，不贪不占。', meaning: '比喻做官廉洁，不贪赃枉法。' },
    { title: '事倍功半', idiom: '事倍功半', story: '形容用力大而收效小，花了两倍力气却只有一半效果。方法不对就会事倍功半，与事半功倍相反。', meaning: '形容费力大，收效小。' },
    { title: '小题大做', idiom: '小题大做', story: '明清科举，小题目用大文章的写法叫小题大做。后比喻把小事当作大事来处理，有故意夸张之意。', meaning: '比喻把小事当作大事来处理，有意夸张。' },
    { title: '大公无私', idiom: '大公无私', story: '祁黄羊举荐人才，外举不避仇，内举不避子。孔子称赞他大公无私，办事完全出于公心，没有私念。', meaning: '完全为公，没有一点私心。' },
    { title: '三令五申', idiom: '三令五申', story: '孙武为吴王操练宫女，三令五申讲明军令，宫女们嬉笑不听。孙武依军法斩了两个队长，宫女们这才认真操练。', meaning: '多次命令和告诫，反复说明。' },
    { title: '无孔不入', idiom: '无孔不入', story: '没有孔洞不钻进去，比喻有空子就钻。空气无孔不入，水也无孔不入。也比喻坏人或坏事到处钻营。', meaning: '比喻有空子就钻，多含贬义。' },
    { title: '入乡随俗', idiom: '入乡随俗', story: '庄子说到了一个地方就要随当地的风俗。楚臣庄蹻到滇国做王，就改穿当地服装遵从当地风俗。', meaning: '到一个地方就顺从当地的习俗。' },
    { title: '因地制宜', idiom: '因地制宜', story: '吴起治理西河，根据各地不同情况制定不同政策，因地制宜，使西河治理得井井有条，百姓安居。', meaning: '根据各地的具体情况，制定适宜的办法。' }
    //IDIOM_END
  ],

  // ===== 十万个为什么 =====
  whyQuestions: [
    { category: '动物', question: '为什么鱼在水里不会淹死？', answer: '鱼是用鳃呼吸的动物。鳃里有很多细血管，水流过鳃时，鳃就能从水中提取溶解的氧气供鱼呼吸。所以鱼在水里不会淹死，反而能自在生活。但鱼离开水后鳃会干掉，就无法呼吸了。' },
    { category: '动物', question: '为什么鸟会飞？', answer: '鸟的身体结构特别适合飞行：骨头空心很轻，翅膀宽大有力量能产生升力，胸肌发达能有力扇翅，羽毛轻而结实，身体呈流线型可减少空气阻力。这些特点让鸟能在空中飞翔。' },
    { category: '动物', question: '为什么猫的眼睛在夜里会发光？', answer: '猫的眼睛本身不发光。猫眼里有一层叫照膜的反光膜，能像镜子一样把进入眼睛的微弱光线反射回去，让感光细胞再次接收。所以猫在夜里能看清东西，我们看到的光其实是反射的光。' },
    { category: '动物', question: '为什么狗常常吐舌头？', answer: '狗皮肤上没有汗腺，不能像人一样出汗散热。狗的汗腺主要长在舌头和脚垫上，天热或运动后它就张大嘴吐舌头，通过舌头上的水分蒸发带走热量，让自己凉快下来。' },
    { category: '动物', question: '为什么兔子耳朵那么长？', answer: '兔子的长耳朵有两个重要作用：一是听觉灵敏，像雷达一样收集四面八方的声音，及时发现危险逃跑；二是帮助散热，耳朵布满血管，天热时血液流过耳朵可散发热量降温。' },
    { category: '动物', question: '为什么变色龙会变色？', answer: '变色龙皮肤里有许多特殊的色素细胞，能在神经和激素调节下扩张或收缩，使皮肤显示不同颜色。变色不仅为了伪装保护自己，还用来表达情绪、与同伴交流和调节体温。' },
    { category: '动物', question: '为什么蜜蜂会跳"8"字舞？', answer: '蜜蜂找到花蜜回巢后用跳舞告诉同伴花蜜位置。蜜源近跳圆圈舞，蜜源远跳"8"字摇摆舞。身体摆动方向表示蜜源相对太阳的方向，摆动快慢表示距离远近，同伴据此就能找到花蜜。' },
    { category: '动物', question: '为什么蚂蚁会排队走？', answer: '蚂蚁走路时腹部会排出一种叫信息素的化学物质留在地上。其他蚂蚁闻到气味就顺着痕迹跟在后面，一只跟一只就排成整齐的队伍。信息素像看不见的路标，指引蚂蚁找到食物并运回巢穴。' },
    { category: '动物', question: '为什么萤火虫会发光？', answer: '萤火虫腹部末端有发光器，里面含荧光素。荧光素与氧气在酶的帮助下结合就会发光，这种光几乎不产生热量叫冷光。萤火虫发光主要是为了在黑夜中寻找和吸引配偶繁殖后代。' },
    { category: '动物', question: '为什么蛇没有脚也能走路？', answer: '蛇靠身体肌肉和腹部宽大的腹鳞移动。肋骨带动腹鳞向前伸展抓住地面，配合肌肉收缩舒张，蛇就能蜿蜒前进。蛇的脊椎骨多而灵活，身体能做波浪状运动，所以没有脚也走得很快。' },
    { category: '动物', question: '为什么骆驼被称为"沙漠之舟"？', answer: '骆驼驼峰储存脂肪，缺食时提供能量；脚掌宽大有肉垫，踩沙不陷；鼻孔能闭合挡风沙；还能耐渴几天不喝水。骆驼能驮重物在沙漠长途行走，像船在沙漠中航行，所以叫沙漠之舟。' },
    { category: '动物', question: '为什么壁虎的尾巴断了还能长出来？', answer: '壁虎的尾巴有再生能力。遇到危险被抓住尾巴时，尾巴会自动断下并扭动吸引敌人，壁虎趁机逃跑。过一段时间断处会长出新尾巴，这叫再生，是壁虎保护自己的本领。' },
    { category: '动物', question: '为什么蝙蝠要倒挂着睡觉？', answer: '蝙蝠后腿短小无力，不能走路也不能从地上起飞。倒挂在高处，遇到危险只要松开爪子展开翅膀就能飞起，很方便。倒挂在高处也能躲避地上敌人，比较安全。' },
    { category: '动物', question: '为什么啄木鸟不会得脑震荡？', answer: '啄木鸟头骨特别厚实，大脑和头骨间几乎没有空隙，大脑被紧紧包裹不会晃动。它的喙和头骨间还有软骨垫能缓冲冲击力。这些特殊结构保护了啄木鸟的大脑，使它每天啄树万次也安然无恙。' },
    { category: '动物', question: '为什么鸡要吃小石子？', answer: '鸡没有牙齿不能咀嚼食物。食物先进入肌胃，肌胃肌肉发达收缩力强。鸡吃的小石子储存在肌胃里，像磨盘一样把食物磨碎帮助消化。所以鸡吃石子不是当食物，而是帮助消化。' },
    { category: '动物', question: '为什么候鸟要迁徙？', answer: '候鸟迁徙主要为了寻找食物和适宜环境。冬天北方寒冷食物减少，候鸟飞到温暖南方觅食过冬。春天北方回暖食物丰富，又飞回北方繁殖后代。这是候鸟长期适应环境形成的本能。' },
    { category: '动物', question: '为什么蜗牛爬过会留下白线？', answer: '蜗牛爬行靠腹足肌肉收缩前进。为减少摩擦保护身体，蜗牛的足腺会分泌黏液润滑路面。这条白线就是黏液干燥后留下的痕迹。黏液还能帮助蜗牛吸附光滑表面，甚至在刀刃上爬行不受伤。' },
    { category: '动物', question: '为什么蝴蝶的翅膀那么漂亮？', answer: '蝴蝶翅膀覆盖着无数细小鳞片，像屋顶瓦片排列。鳞片含色素能呈现各种颜色，还有些鳞片有特殊细微结构，能反射折射光线产生闪光效果。不同蝴蝶鳞片颜色排列不同，所以花纹千姿百态。' },
    { category: '动物', question: '为什么青蛙冬眠时不吃东西不会饿死？', answer: '青蛙冬眠时新陈代谢非常缓慢，心跳呼吸大大减慢，消耗能量极少。秋天青蛙多吃东西，把多余营养变成脂肪储存体内。冬眠期间就靠这些脂肪维持生命，所以不吃东西也不会饿死。' },
    { category: '动物', question: '为什么松鼠的尾巴那么大？', answer: '松鼠大尾巴用处很多：树上跳跃时像降落伞保持平衡当方向舵；从高处跳下时减缓下落速度；冬天睡觉当被子盖身上保暖；夏天还能帮助散热。真是多功能的宝贝。' },
    { category: '动物', question: '为什么大象的鼻子那么长？', answer: '大象长鼻子是上唇和鼻子连在一起进化来的，有四万多块肌肉非常灵活。大象用鼻子呼吸闻味、喝水、卷食物、搬东西，还能打招呼保护自己。长鼻子是大象最重要的工具。' },
    { category: '动物', question: '为什么北极熊不怕冷？', answer: '北极熊有厚厚脂肪层能保温隔热；它的毛是中空透明的，能收集反射阳光像小暖房锁住热量；毛下面是黑色皮肤易吸收太阳热量。这些特点让北极熊在冰天雪地也不觉得冷。' },
    { category: '动物', question: '为什么鲸鱼不是鱼？', answer: '鲸鱼虽生活在水里外形像鱼，但它是哺乳动物。鲸鱼用肺呼吸要浮出水面换气；它是胎生的，小鲸鱼吃妈妈奶长大；体温恒定；尾鳍是水平的而鱼是垂直的。所以鲸鱼不是鱼。' },
    { category: '动物', question: '为什么蜘蛛不是昆虫？', answer: '昆虫身体分头胸腹三部分，有六条腿，多数有两对翅膀。而蜘蛛身体分头胸部和腹部两部分，有八条腿，没有翅膀。所以蜘蛛不属于昆虫，属于蛛形纲动物。蜈蚣蚯蚓等也都不是昆虫。' },
    { category: '动物', question: '为什么鸵鸟不会飞？', answer: '鸵鸟是现存最大的鸟，体重很大翅膀却相对较小，无法产生足够升力。它的羽毛柔软蓬松不像会飞的鸟那样坚硬。但鸵鸟腿又长又粗壮，跑起来时速达七十公里，靠奔跑躲避危险。' },
    { category: '动物', question: '为什么猫喜欢抓老鼠？', answer: '猫是天生的捕猎者，抓老鼠是它的本能。猫爪锋利能伸缩，动作敏捷，夜里视力好，适合捕捉老鼠。老鼠体内含牛磺酸，猫需要它保持夜视能力，所以猫爱吃老鼠。家猫抓老鼠的本能仍在。' },
    { category: '动物', question: '为什么孔雀会开屏？', answer: '会开屏的都是雄孔雀。春天繁殖季节，雄孔雀为吸引雌孔雀注意，把漂亮尾羽竖起展开像绚丽大扇子，还不停抖动。雌孔雀会挑尾羽最漂亮的雄孔雀做伴侣。开屏也是显示自己吓退敌人的方式。' },
    { category: '动物', question: '为什么鱼会有鱼鳞？', answer: '鱼鳞是鱼的保护甲，像铠甲保护身体不受伤害和病菌侵入。鱼鳞很光滑能减少水的阻力让鱼游得更快。鱼鳞还是保温层帮助保持体温。鱼鳞上的生长纹像树的年轮可看出鱼的年龄。' },
    { category: '动物', question: '为什么鸭子游泳时羽毛不会湿？', answer: '鸭子尾部有尾脂腺分泌油脂。鸭子常用嘴把油脂涂抹全身羽毛，油脂不溶于水像给羽毛穿防水衣。水滴在油性羽毛上会滚落不会浸湿，所以鸭子在水里羽毛也干爽蓬松，还能借浮力浮在水面。' },
    { category: '动物', question: '为什么蚊子吸血后皮肤会痒？', answer: '蚊子吸血时会往皮肤里注入含抗凝血物质的唾液，防止血液凝固方便吸食。人体免疫系统发现外来物质会释放组胺来对抗，组胺使皮肤血管扩张刺激神经，于是被叮处红肿发痒。' },
    { category: '动物', question: '为什么马站着睡觉？', answer: '马由野马驯化来，野马在草原要随时警惕猛兽，站着睡觉一有危险能立刻奔跑逃跑，久而久之养成习惯。马腿关节有特殊锁扣结构，站立不费力就能稳定。很安全放松时也会躺下睡一会。' },
    { category: '动物', question: '为什么企鹅生活在南极不怕冷？', answer: '企鹅身上有密密麻麻的羽毛，羽毛下还有厚厚脂肪层，保暖效果非常好。企鹅还会成千上万只挤在一起取暖轮流到外围挡风。脚有特殊血液循环系统防止冻伤，所以能在零下几十度生活。' },
    { category: '动物', question: '为什么蚯蚓被切断后还能活？', answer: '蚯蚓有很强再生能力。被切成两段后，含头部那一段会重新长出尾部；尾部那一段若切的位置合适器官完整，也可能长出头部变成新蚯蚓。因为蚯蚓体内有未分化细胞能重新发育成需要的器官。' },
    { category: '动物', question: '为什么蜜蜂蜇人后自己会死？', answer: '蜜蜂尾刺有倒刺，蜇人后想拔出时倒刺钩住皮肤，结果连同毒囊和部分内脏被拉出体外。蜜蜂失去重要内脏不久就会死去。所以蜜蜂一般不轻易蜇人，只有在受威胁保护蜂巢时才拼死一蜇。' },
    { category: '动物', question: '为什么猫从高处落下不容易受伤？', answer: '猫平衡感特别好。从高处落下时内耳能迅速感知方向，在空中扭转身体使四肢朝下。脚垫有厚厚肉垫能缓冲冲击力，身体柔韧脊椎灵活也能分散冲击力，所以猫从不太高处落下一般不会受伤。' },
    { category: '动物', question: '为什么鱼睡觉时不闭眼睛？', answer: '因为鱼没有眼皮，所以无论醒着还是睡觉都闭不上眼睛。鱼睡觉时不像我们躺下，而是停在水中不动，或躲在石缝水草间，鳍轻轻摆动维持位置。这时警觉性降低，一有动静就会游走。' },
    { category: '动物', question: '为什么蜗牛要背着壳？', answer: '蜗牛的壳是它的家也是保护甲。壳由碳酸钙组成，能保护柔软身体不受伤害。遇到危险或干燥天气就缩进壳里躲避。壳还能保持水分防止身体干燥，会随蜗牛一起长大，所以走到哪背到哪。' },
    { category: '动物', question: '为什么狗的鼻子总是湿的？', answer: '狗鼻子上常分泌黏液保持湿润，能更好溶解空气中气味分子让嗅觉更灵敏。狗还会经常舔鼻子保持湿润清洁。如果狗鼻子干燥发热可能是生病了。狗嗅觉比人强上千倍，湿润鼻子是重要保证。' },
    { category: '动物', question: '为什么燕子要在屋檐下筑巢？', answer: '燕子筑巢要选安全避雨向阳的地方。人类屋檐下能遮风挡雨躲避天敌比较安全，常有蜘蛛等昆虫方便觅食。燕子喜欢和人做邻居，因为人能帮它驱赶蛇猫等敌人。燕子吃蚊子等害虫是人类好朋友。' },
    { category: '动物', question: '为什么鱼会有腥味？', answer: '鱼皮肤里含有氧化三甲胺，鱼死后这种物质分解成三甲胺散发出腥味。鱼生活在水里身上有藻类和细菌也会产生腥味，生活在泥里的鱼腥味更重。做鱼时加料酒生姜醋等可以去腥。' },
    { category: '动物', question: '为什么马蜂比蜜蜂凶？', answer: '马蜂的刺是光滑的，蜇人后能拔出来反复蜇不会死，所以敢于主动攻击。蜜蜂的刺有倒刺蜇人后会死，所以蜜蜂一般不主动攻击。马蜂毒性也比蜜蜂强，对人的威胁更大，遇到马蜂窝要远离。' },
    { category: '动物', question: '为什么小猫出生后眼睛是闭着的？', answer: '小猫在妈妈肚子里发育时间较短，出生时还没发育完全，眼睛闭着是在继续发育。一般出生后七到十天小猫眼睛才慢慢睁开。这是动物保护眼睛的方式，因为眼睛娇嫩闭着可避免受伤和感染。' },
    { category: '动物', question: '为什么斑马身上有条纹？', answer: '斑马条纹有几种作用：一是伪装，条纹在阳光树影中能迷惑敌人让狮子等难看清个体轮廓；二是防蚊虫，条纹能干扰马蝇等吸血昆虫视觉让它们不易落在斑马身上叮咬。每只斑马条纹都不一样可互相辨认。' },
    { category: '动物', question: '为什么青蛙的眼睛对飞动的虫子很敏感？', answer: '青蛙眼睛有特殊本领，对飞动物体特别敏感，对静止物体几乎看不见。因为青蛙视网膜上有特殊细胞只能对运动图像做出反应。死虫子放面前它看不见，虫子一飞动青蛙就能发现并用舌头捕捉。' },
    { category: '动物', question: '为什么海龟要上岸产卵？', answer: '海龟虽一生大部分时间在海里生活，但它是用肺呼吸的爬行动物，蛋也需要在空气中孵化。海龟妈妈夜里爬上沙滩用鳍挖坑产蛋，用沙子盖好就回海里。蛋靠阳光和沙子温度孵化，小海龟破壳后自己爬向大海。' },
    { category: '动物', question: '为什么啄木鸟是"森林医生"？', answer: '啄木鸟专吃藏在树干里的害虫。它用尖锐的喙敲击树干，听到空洞声就知道里面有虫，于是啄开树皮伸出带倒刺的长舌头把虫子勾出来吃掉。被虫害侵蚀的树经啄木鸟治疗就能恢复健康。' },
    { category: '动物', question: '为什么鱼要成群游动？', answer: '鱼成群游动有很多好处：一是防御敌害，一大群鱼游动让捕食者眼花缭乱难以锁定目标，每条鱼被吃的几率就小了；二是方便觅食，一起寻找食物机会更多；三是节省体力，鱼群一起游动能减少水的阻力。' },
    { category: '动物', question: '为什么猫的眼睛瞳孔会变？', answer: '猫瞳孔会根据光线强弱变化。强光下瞳孔收缩成细线减少进光量保护眼睛；暗处瞳孔放大成圆形让更多光线进入方便看清东西。猫瞳孔也会随情绪变化，兴奋或准备攻击时瞳孔会放大。' },
    { category: '动物', question: '为什么蜗牛下雨天会出来？', answer: '蜗牛喜欢潮湿环境，身体需要保持湿润才能活动。晴天天气干燥，蜗牛躲在阴凉处缩进壳里防止水分流失。下雨天空气湿润蜗牛身体不会干燥活动起来很舒服，食物也鲜嫩，所以会出来觅食活动。' },
    { category: '动物', question: '为什么鸡要打鸣？', answer: '公鸡打鸣主要是生物钟在起作用。公鸡体内有生物钟，到清晨就会自然打鸣，宣告领地召唤鸡群。白天公鸡也会打鸣表示警戒或宣示地位。公鸡打鸣受光线影响，天亮时光线变亮会刺激公鸡打鸣。' },
    { category: '植物', question: '为什么树叶在秋天会变黄？', answer: '树叶含绿色叶绿素、黄色叶黄素和橙色胡萝卜素。春夏叶绿素很多遮住其他色素，叶子是绿的。秋天变冷叶绿素被破坏分解，而叶黄素和胡萝卜素较稳定还存在，所以叶子显出黄色或橙色。' },
    { category: '植物', question: '为什么仙人掌有刺？', answer: '仙人掌的刺是它退化了的叶子。仙人掌生活在干旱沙漠，叶子又大又宽水分会很快蒸发。为减少水分散失，叶子退化成针状刺，大大减少蒸发面积。刺还能防止沙漠动物啃食，茎变得肥厚用来储水。' },
    { category: '植物', question: '为什么花有香味？', answer: '许多花的花瓣里有制造香气的油细胞，能分泌芳香的挥发油散发香味。花香是为了吸引昆虫来传粉帮助繁殖。昆虫闻香飞来采蜜身上沾上花粉，飞到另一朵花就把花粉带过去完成传粉。' },
    { category: '植物', question: '为什么向日葵总是朝着太阳？', answer: '向日葵茎顶端含生长素，生长素怕光总跑到背光一侧。背光侧生长素多长得快，向光侧长得慢，茎就向太阳那一边弯曲。太阳移动生长素也跟着移动，向日葵就总是朝着太阳转。' },
    { category: '植物', question: '为什么有些植物会吃虫？', answer: '有些植物生长在贫瘠土壤里养分不够，特别缺少氮元素。为获得营养这些植物进化出捕虫本领。如捕蝇草叶子像夹子昆虫一碰就合拢；猪笼草叶子变瓶子里面有消化液能把掉进去的虫子消化吸收掉。' },
    { category: '植物', question: '为什么树干是圆的？', answer: '圆形树干承受力最大，从各方向来的力都能较好承受不易被风吹断。同样材料圆形面积最大，输送水分养分效率最高。圆形树干没有棱角不易被动物啃咬受伤，也不易积水腐烂，是植物适应环境的结果。' },
    { category: '植物', question: '为什么春天树叶是绿色的？', answer: '春天阳光充足气温回暖，树叶里叶绿素大量形成。叶绿素是绿色的，它吸收阳光进行光合作用制造养分供植物生长。叶绿素含量很高遮盖了叶子里的黄色和橙色色素，所以春夏树叶看起来都是绿色。' },
    { category: '植物', question: '为什么含羞草会"害羞"？', answer: '含羞草叶柄基部有膨大的叶枕，里面充满水分。叶子被触碰时叶枕下半部水分迅速流到上半部，下半部瘪下去上半部鼓起来，叶子就垂下来像害羞。这是含羞草保护自己免受伤害的本能反应。' },
    { category: '植物', question: '为什么荷花出污泥而不染？', answer: '荷叶表面布满密密麻麻的微小突起，上面还有蜡质。水滴落在上面无法铺开只能形成圆珠滚落，顺便把灰尘带走，所以荷叶总是干干净净。荷花花瓣也有类似结构，这叫荷叶效应。' },
    { category: '植物', question: '为什么树有年轮？', answer: '树木每年春夏生长快细胞大颜色浅形成宽的早材；秋天生长慢细胞小颜色深形成窄的晚材。一年里浅深两层合起来就是一圈年轮。数年轮圈数就知道树的年龄，年轮宽说明那年气候好窄说明气候差。' },
    { category: '植物', question: '为什么花生在地上开花却在地下结果？', answer: '花生开花受粉后花冠凋谢，但子房柄会不断伸长像针一样钻入土中叫下针。子房在黑暗湿润疏松的泥土里发育成果实就是花生。花生果实需要在黑暗湿润疏松的土壤里才能形成，所以果针要钻到地下结果。' },
    { category: '植物', question: '为什么松树冬天不落叶？', answer: '松树不是不落叶，而是叶子是针状的面积很小水分蒸发少，叶子表面有蜡质能锁住水分，所以能在冬天保持绿叶。其实松针也会老化和脱落，只是两三年才换一次且不同时掉落，所以看起来四季常绿叫常绿树。' },
    { category: '植物', question: '为什么有的植物能爬墙？', answer: '攀缘植物有各种攀爬本领：爬山虎茎上长有吸盘能牢牢吸附墙壁；牵牛花茎会缠绕别的东西往上爬；葡萄用卷须缠绕支撑物；常春藤长有气生根能扎进墙缝。这些本领让植物向上生长争取阳光。' },
    { category: '植物', question: '为什么蒲公英的种子会飞？', answer: '蒲公英种子上长有一团白色绒毛像小降落伞。风吹来时绒毛展开带着种子飘向远方。这种结构让种子能借助风力传播到很远的地方落地生根长出新的蒲公英，是植物传播种子的聪明方式。' },
    { category: '植物', question: '为什么蘑菇不是植物？', answer: '蘑菇属于真菌不是植物。植物有叶绿素能进行光合作用自己制造养分，而蘑菇没有叶绿素不能光合作用，要靠分解吸收现成的有机物生活。蘑菇细胞壁成分也和植物不同。真菌是单独的一大类生物。' },
    { category: '植物', question: '为什么有些植物有毒？', answer: '植物不会跑动，为不被动物吃掉，有些植物进化出产生毒素的本领作自我保护的武器。如夹竹桃全身有毒，断肠草有剧毒。毒素让动物吃了不舒服甚至死亡就不敢再吃。这是植物生存竞争的策略。' },
    { category: '植物', question: '为什么树叶掉落后会卷起来？', answer: '树叶掉落后慢慢变干水分流失。叶子上表皮和下表皮结构不同，失水时收缩程度不一样。通常叶子下表皮细胞比较大失水收缩得更厉害，所以叶子会向上表面方向卷曲，这就是落叶卷起来的原因。' },
    { category: '植物', question: '为什么水果成熟后会变甜？', answer: '没有成熟的水果里储存着淀粉没有甜味还有些酸。水果成熟时淀粉在酶的作用下分解成糖，有机酸也被消耗，所以变得又甜又香。同时果肉变软颜色也变鲜艳，吸引动物来吃帮助传播种子。' },
    { category: '植物', question: '为什么树根要往下长？', answer: '树根往下长一是受地球引力影响，根有向地性总朝地心方向生长；二是为了吸收土壤深处的水分和养分；三是为了牢牢固定住树干抵抗风雨。根在地下纵横交错像一只只大手紧紧抓住泥土让大树站稳。' },
    { category: '植物', question: '为什么西瓜里有那么多水？', answer: '西瓜原产于干旱的非洲沙漠，为在缺水环境里生存进化出储水的本领。西瓜果肉里有大量薄壁细胞里面装满汁液能储存很多水分。这些水是西瓜为种子发育准备的，也吸引动物吃果肉帮助传播种子。' },
    { category: '植物', question: '为什么茶叶有苦涩味？', answer: '茶叶里含茶多酚和咖啡碱等物质有苦味和涩味。泡茶时这些物质溶解到水里茶水就有了苦涩味。不过这些物质对人体有好处能提神醒脑帮助消化。好茶经过加工苦涩味会减少留下清香回甘的味道。' },
    { category: '植物', question: '为什么嫁接能改变植物？', answer: '嫁接是把一种植物枝条接到另一种植物茎干上让它们长在一起。接上去的接穗保留原来品种优良特性如果实好吃；下面的砧木提供根系抗病耐旱。嫁接能结合两种植物优点是改良果树的好方法。' },
    { category: '植物', question: '为什么香蕉没有种子？', answer: '我们吃的香蕉是经人工长期培育的栽培品种。野生香蕉是有种子的又硬又多。人们挑选种子少甚至没种子的香蕉培育繁殖，经很多代得到现在果肉多没种子的香蕉。无籽香蕉不能用种子繁殖是用侧芽繁殖的。' },
    { category: '植物', question: '为什么红树林能长在海里？', answer: '红树林有特殊本领适应海水：根能过滤盐分不让过多盐分进入体内；长有露出水面的气生根能在缺氧泥滩里呼吸；种子在树上就发芽长成小苗掉下就能扎根生长叫胎生。这些本领让红树林能在海边滩涂茂盛生长。' },
    { category: '植物', question: '为什么有的花只在晚上开？', answer: '有些花如昙花夜来香只在晚上开放，因为它们的传粉者是在夜间活动的蛾子蝙蝠等。晚上开花散发浓郁香气吸引这些夜行动物来传粉。这是一种适应性进化让植物和传粉者相互配合更好繁殖后代。' },
    { category: '植物', question: '为什么种子能保存很久？', answer: '种子在成熟后会进入休眠状态新陈代谢非常缓慢，只要环境干燥低温低氧就能保存很长时间还保持生命力。种子里的胚是活的，等温度水分氧气等条件合适时就会苏醒发芽。有些种子埋地下几百年还能发芽。' },
    { category: '植物', question: '为什么多肉植物叶子厚厚的？', answer: '多肉植物大多生长在干旱地区，为在缺水地方生存，叶子和茎变得肥厚多汁里面储存了大量水分和养分。它们表面还有蜡质能减少水分蒸发。所以多肉植物很耐旱长时间不浇水也能活。' },
    { category: '植物', question: '为什么树叶落地时大多背面朝上？', answer: '树叶正面和背面结构不同。正面细胞排列紧密比较重，背面细胞疏松比较轻。落叶时较重的正面朝下较轻的背面朝上，所以树叶落地时大多背面朝上。另外叶柄连接处的组织断裂方式也有影响。' },
    { category: '植物', question: '为什么竹子长得那么快？', answer: '竹子是草本植物，它的节间同时伸长每个节都在生长加起来就很快。竹子有发达的地下茎储存了大量养分，春天竹笋出土后靠这些养分迅速拔高，有的竹子一天能长一米多。' },
    { category: '植物', question: '为什么棉花不是花？', answer: '棉花白色的部分不是花，而是果实成熟后裂开露出的白色绒毛长在种子上叫种子的表皮毛。棉花的真正花朵是黄白色的会变红变紫。人们采摘的棉花是去掉种子后的纤维用来纺纱织布，其实是种子上的纤维。' },
    { category: '植物', question: '为什么有些植物能测空气污染？', answer: '有些植物对空气污染很敏感，空气中有害气体超标时叶片会出现斑点变色枯萎等症状，像报警器一样提醒人们。比如苔藓对二氧化硫很敏感，监测植物能帮人们了解空气质量，这叫植物监测。' },
    { category: '植物', question: '为什么苹果切开后会变褐色？', answer: '苹果里含多酚物质和一种酶。苹果切开后多酚接触空气中氧气，在酶帮助下发生氧化反应生成褐色物质，所以苹果切面变褐。把切开的苹果泡在盐水或柠檬水里可以隔绝氧气减缓变色。' },
    { category: '植物', question: '为什么玫瑰有刺？', answer: '玫瑰的刺是茎上的皮刺是它自我保护的武器。玫瑰长得不高容易被动物踩踏啃食，刺让动物不敢随便靠近和吃它保护自己不被伤害。这是植物在自然界中保护自己的一种方式，就像仙人掌的刺荨麻的毛一样。' },
    { category: '植物', question: '为什么松树的叶子是针状的？', answer: '松树生活在比较寒冷或干旱的地方，针状叶子面积小水分蒸发少能帮助松树保水耐旱。针叶表面还有蜡质进一步减少水分散失。针叶还能承受积雪不易折断，这些特点让松树能在艰苦环境中生存。' },
    { category: '植物', question: '为什么有的植物能扦插繁殖？', answer: '很多植物的枝条叶片有很强的再生能力。把枝条剪下插到土里，在合适温度和湿度下，枝条下端能长出不定根上端长出新芽慢慢长成新植株。这叫扦插，像柳树月季都能扦插繁殖，方法简单。' },
    { category: '植物', question: '为什么腊梅在冬天开花？', answer: '腊梅有耐寒的本领能在低温下开花。冬天开花竞争少，腊梅能独占冬天的传粉资源。腊梅花瓣有蜡质能抵抗寒冷。虽然冬天传粉昆虫少，但腊梅花香浓郁能吸引少数活动的昆虫。腊梅不畏严寒常被诗人赞美。' },
    { category: '植物', question: '为什么核桃的外壳那么硬？', answer: '核桃硬硬的外壳是保护里面种子的铠甲。核桃的种子营养丰富动物爱吃。硬壳让动物很难打开保护种子不被吃掉。即使被动物吞下硬壳也能保护种子通过肠道随粪便排出落地发芽，这是核桃保护种子的策略。' },
    { category: '植物', question: '为什么有的植物会"午睡"？', answer: '炎热的夏天中午植物为避免水分过度散失会关闭叶片上的气孔。气孔一关二氧化碳进不来光合作用减弱就像休息一样这叫植物的午睡。等下午温度降下来气孔重新打开光合作用又恢复，这是植物适应高温的自我保护。' },
    { category: '植物', question: '为什么白桦树的树皮是白色的？', answer: '白桦树皮含有一种叫白桦脂的物质，加上树皮表层细胞里含有空气和白色物质，所以看起来是白色的。白色的树皮能反射阳光防止树干被晒伤，还能像纸一样一层层剥落，帮助树木除掉附着的苔藓和害虫。' },
    { category: '植物', question: '为什么树到冬天会落叶？', answer: '冬天天气寒冷干燥，树根吸收的水分减少，如果还保留大量叶子，水分会通过叶子大量蒸发，树木会因缺水干枯。落叶树在秋天落下叶子，减少水分散失，就能安全过冬。来年春天再长出新叶进行光合作用。' },
    { category: '天文地理', question: '为什么天是蓝色的？', answer: '太阳光包含七种颜色，当阳光穿过大气层时，空气中的气体分子会把蓝光散射到四面八方。蓝光波长短更容易被散射，所以我们抬头看到的天空就是被散射的蓝光，天空就呈现蓝色了。' },
    { category: '天文地理', question: '为什么会有四季？', answer: '地球在绕太阳公转时，地轴是倾斜的，倾斜角约23.5度。当地球转到不同位置，太阳光直射的地方不同，各地接收的热量也不同，就形成了春夏秋冬四季更替。地轴倾斜是产生四季的根本原因。' },
    { category: '天文地理', question: '为什么月亮有圆有缺？', answer: '月亮自己不发光，靠反射太阳光。月亮绕地球转，地球人看到的被太阳照亮的部分不断变化。当亮面全部朝向我们就是满月，当亮面侧向我们就是弯月。月亮圆缺变化叫月相，一个周期约29.5天。' },
    { category: '天文地理', question: '为什么会下雨？', answer: '地面和海洋的水被太阳晒热后蒸发变成水蒸气升到空中。水蒸气在高空遇冷凝结成小水滴或冰晶，聚集多了就形成云。云里水滴越聚越大越来越重，空气托不住时就掉下来变成雨落到地面。' },
    { category: '天文地理', question: '为什么彩虹有七种颜色？', answer: '雨后天空中悬浮着很多小水滴。阳光穿过水滴时发生折射，不同颜色的光折射角度不同就被分开，形成红橙黄绿蓝靛紫七种颜色排列的彩虹。彩虹是阳光被水滴折射和反射形成的自然现象。' },
    { category: '天文地理', question: '为什么星星会眨眼睛？', answer: '星星发出的光穿过地球大气层时，由于大气层空气流动不稳定，密度不断变化，星光被反复折射，光芒就忽明忽暗，看上去像在眨眼睛。如果到大气层外的太空看星星，星星就不会眨眼了。' },
    { category: '天文地理', question: '为什么太阳会发光发热？', answer: '太阳是一个巨大的气体球，主要成分是氢和氦。太阳内部温度和压力极高，氢原子不断发生核聚变反应变成氦，在这个过程中释放出巨大的能量，这些能量以光和热的形式辐射出来，就是太阳的光和热。' },
    { category: '天文地理', question: '为什么会有白天和黑夜？', answer: '地球是一个不透明的球体，自己不发光。地球不停地自西向东自转，转到面向太阳的一面就是白天，背向太阳的一面就是黑夜。地球自转一圈大约24小时，所以我们经历一次白天黑夜的交替。' },
    { category: '天文地理', question: '风是怎么形成的？', answer: '太阳照在地面上，各地受热不均匀。受热多的地方空气变暖上升，气压降低；周围较冷的空气就会流过来补充。空气从气压高的地方流向气压低的地方，这种空气的流动就形成了风。' },
    { category: '天文地理', question: '云是怎么形成的？', answer: '地面和水面被太阳晒热后，水蒸发成水蒸气升到空中。高空气温低，水蒸气遇冷凝结成无数小水滴或小冰晶。这些小水滴小冰晶聚集在一起飘浮在空中，就是我们看到的云。' },
    { category: '天文地理', question: '为什么会打雷闪电？', answer: '雷雨天云层中水滴摩擦产生大量电荷，云的上部带正电下部带负电。当电荷积累到一定程度就会放电，放电时产生强烈的闪光就是闪电。闪电使周围空气急剧受热膨胀爆炸，发出的声音就是雷声。' },
    { category: '天文地理', question: '为什么雪是白色的？', answer: '雪花是冰的结晶，里面有很多小气泡和冰晶的交界面。当光线照到雪上时，这些交界面把光线向各个方向反射散射，所有颜色的光混在一起就呈现白色。所以雪看起来是洁白的。' },
    { category: '天文地理', question: '雾是怎么形成的？', answer: '当空气中含有较多水蒸气，夜间或清晨气温降低时，水蒸气遇冷凝结成无数细小的水滴悬浮在近地面的空气中，就形成了雾。雾其实就是地面的云，太阳出来温度升高后雾就会散去。' },
    { category: '天文地理', question: '为什么早晨草叶上有露水？', answer: '白天温度高空气含较多水蒸气。夜里气温降低，空气容纳水蒸气的能力减小，多余的水蒸气就在草叶等较凉的物体表面凝结成小水珠，这就是露水。晴朗无风的夜晚最容易形成露水。' },
    { category: '天文地理', question: '为什么会发生地震？', answer: '地球表面由几大板块组成，板块在不断运动。当板块互相挤压碰撞或错动时，会产生巨大的力量，使岩层突然断裂或错位，释放出能量引起地面震动，这就是地震。绝大多数地震是构造地震。' },
    { category: '天文地理', question: '为什么火山会喷发？', answer: '地球内部温度很高，岩石熔化成岩浆。岩浆在地下不断聚集，压力越来越大。当压力大到一定程度，岩浆就会从地壳薄弱的地方冲出来，同时喷出气体和火山灰，这就是火山喷发。' },
    { category: '天文地理', question: '为什么海水是咸的？', answer: '雨水流过岩石土壤，溶解了里面的盐分，带到河流再流入大海。海水不断蒸发，盐分留在海里越积越多，经过几十亿年积累，海水就变咸了。海底火山也会带来一些盐分。' },
    { category: '天文地理', question: '为什么海水看起来是蓝色的？', answer: '太阳光照到海面上，海水会吸收红光黄光等长波光，而蓝光绿光等短波光被反射出来。所以我们看到海水是蓝色的。海水越深蓝色越深，近岸水浅显浅蓝或绿色。' },
    { category: '天文地理', question: '为什么大海会涨潮退潮？', answer: '海水涨潮退潮主要受月球和太阳引力影响。月球离地球近引力大，把海水吸向自己方向形成涨潮，背向月球一面也涨潮。地球自转使各地依次经历涨潮退潮，一天约两次。' },
    { category: '天文地理', question: '为什么会有极光？', answer: '太阳会喷出带电粒子流。当这些粒子到达地球附近，被地球磁场引导到南北两极上空，与高空大气中的气体分子碰撞，使气体发光，就形成绚丽多彩的极光。极光多出现在极地地区。' },
    { category: '天文地理', question: '为什么会有流星？', answer: '太空中有很多小石头和尘埃叫流星体。当它们靠近地球被地球引力吸引进入大气层时，与空气剧烈摩擦燃烧发光，在夜空中划出一道亮光，就是流星。没有烧完落到地面的叫陨石。' },
    { category: '天文地理', question: '为什么太阳东升西落？', answer: '地球自西向东自转，所以我们看到太阳好像从东方升起西方落下。其实太阳没有动，是地球在转动。就像坐在前进的火车里看窗外的景物好像在后退一样，是一种相对运动。' },
    { category: '天文地理', question: '山是怎么形成的？', answer: '地球表面由几大板块组成，板块不断运动。当两个板块互相挤压碰撞，地壳岩层受力褶皱隆起，就形成了山脉，这叫褶皱山。也有的山是火山喷发岩浆冷却堆积形成的叫火山。喜马拉雅山就是这样形成的。' },
    { category: '天文地理', question: '河流是怎么形成的？', answer: '雨雪水和高山冰雪融化形成的水流，顺着地势从高处往低处流，汇聚成小溪。小溪不断汇集更多的水变成小河，小河又汇成大河，沿着河道流向低处，最终汇入海洋或湖泊，就形成河流。' },
    { category: '天文地理', question: '沙漠是怎么形成的？', answer: '有些地方常年干旱少雨，又加上风大，把地面的沙土吹走堆积在一起。加上植被稀少不能固定沙土，日积月累就形成了大片沙地沙漠。沙漠地区蒸发量远大于降水量，气候干燥。' },
    { category: '天文地理', question: '冰川是怎么形成的？', answer: '在高山上或两极地区，常年气温在零度以下，下的雪不会融化。雪一层层堆积压实，下层的雪变成粒雪，再慢慢变成冰。这些冰在重力作用下慢慢流动，就形成冰川，像一条缓缓流动的冰河。' },
    { category: '天文地理', question: '为什么会发生日食和月食？', answer: '当月亮转到太阳和地球中间，挡住太阳光就发生日食。当地球转到太阳和月亮中间，地球挡住太阳光月亮照不到光就发生月食。日食发生在农历初一，月食发生在农历十五左右。' },
    { category: '天文地理', question: '为什么会有回声？', answer: '声音在传播过程中遇到障碍物如高山墙壁会被反射回来。如果反射回来的声音和原声相隔一定时间，我们就能先后听到两个声音，后一个就是回声。空旷的山谷和大房间容易听到回声。' },
    { category: '天文地理', question: '为什么火星是红色的？', answer: '火星表面的岩石和土壤中含有大量的氧化铁，也就是我们常说的铁锈。铁锈是红褐色的，所以从远处看火星表面呈现红色，火星也因此被称为红色星球。' },
    { category: '天文地理', question: '为什么北极星能指示北方？', answer: '北极星几乎正对着地球北极的延长线，地球自转时北极星位置几乎不变。所以无论地球怎么转，北极星总在北方的天空。在北半球的人们只要找到北极星，就能确定正北方向，它像一盏天然的指路灯。' },
    { category: '天文地理', question: '为什么说地球是圆的？', answer: '地球是一个巨大的球体。宇航员从太空能清楚看到地球是圆的。海边看远来的船先看到桅杆后看到船身，月食时地球影子是圆的，这些都证明地球是圆的。地球因自转略扁，是椭球体。' },
    { category: '天文地理', question: '为什么会有温泉？', answer: '在地下深处有岩浆活动的地方，地下水被加热变成热水。这些热水沿着地壳裂缝涌出地面，就形成温泉。有的温泉水温很高还能喷出蒸汽叫间歇泉。温泉里常含矿物质对身体有益。' },
    { category: '天文地理', question: '钟乳石是怎么形成的？', answer: '溶洞顶部的地下水含溶解的碳酸钙。水滴落下时，碳酸钙慢慢沉淀出来。洞顶的水滴长期沉淀向下生长形成钟乳石，滴到洞底的水沉淀向上生长形成石笋，钟乳石和石笋连起来形成石柱。' },
    { category: '天文地理', question: '为什么天黑后能看到星星？', answer: '白天星星其实也在天上，只是太阳光太强，天空太亮，把微弱的星光盖住了看不见。到了夜晚，太阳光照不到我们这边的天空，天空变暗，星星的亮光就能显现出来被我们看到。' },
    { category: '天文地理', question: '为什么月亮上有环形山？', answer: '月亮表面没有大气保护，太空中陨石和小石头直接撞击月亮表面，砸出一个个圆形的坑，这就是环形山。月亮没有风和水流的侵蚀，这些坑能长久保留，所以月亮表面布满环形山。' },
    { category: '天文地理', question: '太阳系有哪些成员？', answer: '太阳系以太阳为中心，有八大行星：水星金星地球火星木星土星天王星海王星。还有许多矮行星如冥王星，无数小行星彗星和流星体。所有成员都绕着太阳转，太阳引力把它们联系在一起。' },
    { category: '天文地理', question: '什么是黑洞？', answer: '黑洞是宇宙中一种天体，它的引力极其强大，连光都无法逃脱，所以看上去是黑的。黑洞通常由巨大的恒星燃烧完后坍缩形成。因为光出不来，我们看不见黑洞，只能通过它对周围的影响来发现。' },
    { category: '天文地理', question: '龙卷风是怎么形成的？', answer: '雷暴云中上下层空气温度差很大，热空气猛烈上升冷空气下沉，形成强烈的旋转气流。旋转越来越快越来越细形成漏斗状的云柱伸向地面，就是龙卷风。龙卷风风力极大破坏力很强。' },
    { category: '天文地理', question: '为什么会发生海啸？', answer: '海底发生大地震火山喷发或滑坡时，会使大量海水突然移动，产生巨大的波浪向四周传播，这就是海啸。海啸在深海不明显，到近岸水浅处波浪变高，能造成巨大破坏。' },
    { category: '天文地理', question: '为什么高山上煮饭难熟？', answer: '水的沸点受气压影响，气压越低沸点越低。高山上海拔高气压低，水不到100度就开了。水温不够高，饭就不容易煮熟。所以在高山上煮饭要用高压锅，提高锅内气压使水温升高才能煮熟。' },
    { category: '人体', question: '为什么人会发烧？', answer: '当病菌病毒侵入人体，人体的免疫系统会奋起抵抗。为了对付病菌，大脑会调高身体的温度，因为较高的体温能抑制病菌繁殖，还能让免疫细胞更活跃。所以发烧是身体在和疾病作斗争的表现。' },
    { category: '人体', question: '为什么我们要刷牙？', answer: '我们吃的食物残渣会留在牙缝里，口腔里的细菌会分解这些残渣产生酸性物质。酸性物质会腐蚀牙齿，时间久了就会形成蛀牙，还会引起口臭。刷牙可以清除食物残渣和细菌，保护牙齿健康。' },
    { category: '人体', question: '为什么头发会变白？', answer: '头发里含有黑色素所以是黑的。随着年龄增长，毛囊里的黑色素细胞功能减弱，产生的黑色素减少，头发就慢慢变白。精神紧张营养不良或某些疾病也会使黑色素减少，导致头发早白。' },
    { category: '人体', question: '为什么人会打嗝？', answer: '打嗝是因为横膈膜突然收缩痉挛引起的。横膈膜是分隔胸腔和腹腔的肌肉，它收缩时我们猛地吸气，声带突然关闭就发出嗝的声音。吃太快太饱喝碳酸饮料或受凉都可能引起打嗝。' },
    { category: '人体', question: '为什么我们会感到饿？', answer: '我们吃下去的食物被消化吸收后，胃里空了血糖降低。胃的收缩和低血糖会通过神经告诉大脑的饥饿中枢，大脑就发出饥饿信号，提醒我们该吃东西补充能量了，这就是饿的感觉。' },
    { category: '人体', question: '为什么人会感到困？', answer: '我们白天活动消耗能量，大脑会产生一种叫腺苷的物质，积累多了就会让人感到困倦。另外到了晚上大脑会分泌褪黑素，告诉我们该睡觉了。充足的睡眠能让身体休息恢复精力。' },
    { category: '人体', question: '为什么人会出汗？', answer: '人体皮肤上有汗腺。天气热或运动后身体产生大量热量，为了保持正常体温，汗腺就会分泌汗液。汗液在皮肤表面蒸发时会带走热量，使身体凉快下来，所以出汗是人体调节体温的重要方式。' },
    { category: '人体', question: '为什么人会打喷嚏？', answer: '当鼻腔受到灰尘冷空气或异物刺激时，鼻粘膜上的神经会把信号传给大脑。大脑指挥胸腔肌肉猛烈收缩，把气流从鼻子和嘴巴快速喷出，把刺激物清除掉，这就是打喷嚏，是身体的自我保护反应。' },
    { category: '人体', question: '为什么心脏会一直跳动？', answer: '心脏里有特殊的起搏细胞，能自动有节律地发出电信号，让心脏肌肉收缩舒张，不停地跳动。心脏跳动把血液输送到全身，为身体各部分提供氧气和营养。人活着心脏就一刻不停地跳动。' },
    { category: '人体', question: '为什么人会做梦？', answer: '人睡觉时大脑并没有完全休息，一部分脑细胞还在活动。睡眠中大脑对白天经历的事情进行整理加工，就形成了各种各样的梦。做梦是正常的生理现象，有助于记忆和情绪的调节。' },
    { category: '人体', question: '为什么肚子会咕咕叫？', answer: '肚子饿了或消化时，胃和肠子里有气体和液体，胃肠蠕动时气体液体被挤压移动，就会发出咕咕的声音。饿的时候胃空空的收缩更明显，声音就更大，这是在提醒我们该吃东西了。' },
    { category: '人体', question: '为什么手指泡水久了会起皱？', answer: '手指皮肤最外层是角质层，泡水后角质层吸水膨胀。但皮肤下面没有吸水，所以表皮起皱。这其实是神经控制的反应，起皱的手指能更好地抓住湿滑的物体，是人体的一种适应本领。' },
    { category: '人体', question: '为什么人会有指纹？', answer: '指纹是手指皮肤上的花纹，在胎儿时期就形成了。指纹可以增加手指的摩擦力，让我们更容易抓住东西。每个人的指纹都不同，连双胞胎也不一样，所以指纹可以用来识别身份。' },
    { category: '人体', question: '为什么人会打哈欠？', answer: '人疲劳困倦或大脑缺氧时会打哈欠。打哈欠时张大嘴深吸一口气，能吸入更多氧气排出二氧化碳，让大脑清醒一些。打哈欠还会传染，看到别人打哈欠自己也会忍不住跟着打。' },
    { category: '人体', question: '为什么血是红色的？', answer: '血液中含有红细胞，红细胞里有血红蛋白，血红蛋白含铁元素，呈红色，所以血液是红色的。血红蛋白能结合氧气，把氧气从肺部运送到全身各处，供身体使用，所以血是红色的是因为血红蛋白。' },
    { category: '人体', question: '为什么人会眨眼睛？', answer: '眨眼是一种保护眼睛的本能。眨眼时眼皮把眼泪均匀涂在眼球表面，保持眼睛湿润不干燥。眨眼还能清除进入眼睛的灰尘。人平均每分钟眨眼十几次，这些都是身体在自动保护眼睛。' },
    { category: '人体', question: '为什么人会哭？', answer: '哭是人类表达情绪的方式。伤心难过或太高兴时，大脑情绪中枢被激活，会发出信号让泪腺分泌眼泪。哭能释放压力舒缓情绪，眼泪还能把体内积压的紧张物质排出，所以哭完后心情会好些。' },
    { category: '人体', question: '为什么切洋葱会流泪？', answer: '洋葱被切开时会释放出一种含硫的挥发性物质。这种物质飘到眼睛里刺激角膜上的神经，眼睛为了冲洗掉刺激物就分泌大量眼泪，所以我们切洋葱时会流泪。把洋葱冷藏后再切可减少刺激。' },
    { category: '人体', question: '为什么骨头那么硬？', answer: '骨头主要由坚硬的无机盐如钙磷化合物和有弹性的有机物如胶原蛋白组成。无机盐让骨头坚硬能支撑身体，有机物让骨头有韧性不易折断。两者结合使骨头既坚硬又有弹性，能承受很大力量。' },
    { category: '人体', question: '为什么人会变老？', answer: '人体细胞在不断分裂更新，但分裂次数有限。随着时间推移，细胞修复能力下降，身体各器官功能逐渐减退，皮肤出现皱纹，头发变白，这就是衰老。衰老是自然规律，健康的生活方式可以延缓衰老。' },
    { category: '人体', question: '为什么有人是左撇子？', answer: '人的大脑分左右半球，左脑控制右手，右脑控制左手。哪边大脑占优势，对侧手就更灵活。左撇子是右脑占优势，右撇子是左脑占优势。这与遗传有关，是天生的，左撇子和右撇子一样聪明。' },
    { category: '人体', question: '为什么剪指甲不疼？', answer: '指甲是由死亡的角质细胞组成的，没有神经和血管，所以剪指甲时不会感到疼。指甲从指甲基质不断生长推出来。虽然没有感觉，但指甲保护着手指尖端，还能帮助我们抓捏细小东西。' },
    { category: '人体', question: '为什么睡觉会打呼噜？', answer: '人睡觉时喉咙的肌肉放松，气道变窄。呼吸时气流通过狭窄的气道使周围组织振动，就发出呼噜声。仰睡鼻子不通气肥胖或疲劳等都可能加重打呼噜。经常打呼噜严重时会影响健康要去就医。' },
    { category: '人体', question: '为什么人要呼吸？', answer: '人体每个细胞都需要氧气才能把食物转化成能量。我们吸气时把氧气吸入肺部，氧气进入血液被运送到全身。同时身体产生的废气二氧化碳通过血液运到肺部呼出。人一刻不呼吸就会有生命危险。' },
    { category: '人体', question: '为什么吃下去的食物能变成营养？', answer: '食物在消化道里被消化。口腔咀嚼和胃蠕动把食物磨碎，消化液里的酶把食物分解成小分子，如蛋白质分解成氨基酸，淀粉分解成葡萄糖。这些小分子在小肠被吸收进入血液，运送到全身供身体使用。' },
    { category: '人体', question: '为什么耳朵能听到声音？', answer: '声音是空气的振动。声波进入耳道引起鼓膜振动，鼓膜振动传到内耳的耳蜗，耳蜗里的毛细胞把振动转变成神经信号传给大脑，大脑就把它解释成声音，所以我们就听到了各种各样的声音。' },
    { category: '人体', question: '为什么眼睛能看见东西？', answer: '物体反射的光进入眼睛，透过角膜和晶状体聚焦在视网膜上。视网膜上的感光细胞把光信号变成神经信号，通过视神经传给大脑。大脑处理后我们就看见了物体的形状颜色和大小。' },
    { category: '人体', question: '为什么鼻子能闻到气味？', answer: '鼻腔上部有嗅觉区，里面有嗅觉细胞。空气中的气味分子进入鼻腔，刺激嗅觉细胞，嗅觉细胞把信号传给大脑，大脑识别后就闻到气味了。人的嗅觉能分辨上万种气味，还能引起记忆和情绪。' },
    { category: '人体', question: '为什么舌头能尝出味道？', answer: '舌头表面有许多小突起叫味蕾，味蕾里有味觉细胞。食物溶解在唾液中刺激味蕾，味觉细胞把信号传给大脑，大脑就识别出酸甜苦咸鲜等味道。舌头不同部位对味道的敏感程度不同。' },
    { category: '人体', question: '为什么皮肤会被晒黑？', answer: '太阳光中有紫外线，过多紫外线会伤害皮肤。为保护皮肤，皮肤里的黑色素细胞会制造更多黑色素，吸收紫外线防止它伤害细胞。黑色素多了皮肤就变黑了。所以晒黑是皮肤自我保护的反应。' },
    { category: '人体', question: '为什么人会长高？', answer: '人小时候骨头两端有软骨层叫骨骺。软骨细胞不断分裂长大，慢慢变成硬骨，骨头变长人就长高了。到了成年骨骺闭合不再生长，身高就基本定型了。营养运动和睡眠都会影响长高。' },
    { category: '人体', question: '为什么骨头会骨折？', answer: '骨头虽然坚硬，但承受的力量超过一定限度就会断裂，这就是骨折。摔倒撞击或受到大力打击都可能造成骨折。儿童骨头较软不易完全折断，老人骨头变脆更容易骨折。骨折后要固定治疗让它重新愈合。' },
    { category: '人体', question: '为什么伤口会自己愈合？', answer: '皮肤受伤后，血液中的血小板会聚集形成血块堵住伤口止血。然后新细胞开始生长，成纤维细胞制造新的组织填补伤口，最后皮肤细胞覆盖表面，伤口就慢慢愈合了，这是身体的自我修复能力。' },
    { category: '人体', question: '为什么小朋友会换牙？', answer: '小朋友先长的是乳牙，比较小也不够结实。随着身体长大，颌骨变大，乳牙不够用了。这时恒牙在下面长出来把乳牙顶掉，换上更大更结实的恒牙，能用一辈子，所以小朋友会换牙。' },
    { category: '人体', question: '为什么人有不同的肤色？', answer: '皮肤里有黑色素，黑色素多肤色就深，黑色素少肤色就浅。生活在阳光强烈地区的人，黑色素多肤色深，能保护皮肤不被紫外线伤害。生活在阳光少地区的人黑色素少肤色浅。肤色是适应环境的产物。' },
    { category: '人体', question: '为什么人会近视？', answer: '近视是看近处清楚看远处模糊。长时间近距离看书看手机，眼球里的晶状体调节肌肉一直紧张，久而久之眼球变长，远处物体的像落在视网膜前面，就看不清远处了。注意用眼卫生可以预防近视。' },
    { category: '人体', question: '为什么人会感冒？', answer: '感冒大多是由病毒引起的。感冒病毒通过空气飞沫或接触进入我们的鼻腔喉咙，在粘膜上繁殖，引起鼻塞流涕咳嗽等症状。受凉疲劳时免疫力下降，病毒就更容易侵入繁殖，所以会感冒。' },
    { category: '人体', question: '为什么人要喝水？', answer: '人体约百分之六十都是水。水是血液的主要成分，能运输营养和废物；水帮助消化和吸收食物；水通过出汗排尿调节体温排出毒素。我们每天会流失很多水，必须及时喝水补充，否则会影响健康。' },
    { category: '人体', question: '为什么人有不同的血型？', answer: '红细胞表面有不同的抗原物质，根据抗原不同把血液分型，常见的有ABO血型系统分A型B型AB型O型。血型是遗传的，由父母决定。输血时血型必须匹配否则会发生危险，所以输血前要验血型。' },
    { category: '人体', question: '为什么脚会抽筋？', answer: '脚抽筋是肌肉突然不自主地强烈收缩，常伴有疼痛。运动过度肌肉疲劳受凉缺钙或血液循环不好都可能引起抽筋。发生抽筋时可以轻轻按摩拉伸肌肉缓解。平时注意补钙和运动前热身可以预防。' },
    { category: '物理', question: '为什么冰会融化？', answer: '冰是固态的水，水分子在冰里排列整齐固定。当温度升高到0度以上时，冰吸收热量，水分子运动加快，挣脱原来的排列变成能流动的液态水，冰就融化了。温度越高融化越快。' },
    { category: '物理', question: '为什么影子是黑色的？', answer: '光沿直线传播，遇到不透明的物体被挡住，物体后面照不到光就形成影子。影子区域因为没有光照到，所以看起来比周围暗呈现黑色。其实影子不是真正的颜色，而是缺少光的表现。' },
    { category: '物理', question: '为什么物体会往下掉？', answer: '地球对一切物体都有吸引力叫重力。重力方向总是竖直向下，所以抛出去的物体都会落回地面，水总是往低处流。重力让我们能稳稳站在地面上，也是重力让月亮绕着地球转。' },
    { category: '物理', question: '为什么镜子能照出人影？', answer: '镜子表面光滑平整能反射光。当光照到我们身上反射到镜子上，镜子又把光反射回来进入我们眼睛，我们就看到镜中的自己。镜子里的像和真实物体左右相反，大小一样距离相等。' },
    { category: '物理', question: '为什么磁铁能吸铁？', answer: '磁铁周围有磁场。铁是一种铁磁性材料，内部有微小的磁区。当铁靠近磁铁时，磁铁的磁场使铁里的磁区排列整齐，铁就被磁化吸引过来。磁铁还能吸钴镍等金属，但不能吸铜铝等。' },
    { category: '物理', question: '为什么气球能飞上天？', answer: '氢气或氦气比空气轻，充入气球后，气球受到的浮力大于它的重量，气球就会上升。但普通气球充的是空气，不会飞起来。注意氢气遇到火会爆炸，现在一般用安全的氦气球。' },
    { category: '物理', question: '为什么冰能浮在水面上？', answer: '大多数物质都是热胀冷缩，但水有个特别之处：水结成冰后体积反而变大。同样重量的冰比水体积大，所以冰的密度比水小，冰就浮在水面上了。这对水中生物过冬很重要。' },
    { category: '物理', question: '为什么热水瓶能保温？', answer: '热水瓶有双层玻璃壁，中间抽成真空没有空气，热量不易通过传导散失；瓶胆内壁涂银像镜子能反射热辐射；瓶塞用软木隔热阻止热对流。这三者结合使热水瓶里的热量很难跑出来，所以能保温。' },
    { category: '物理', question: '为什么放大镜能放大物体？', answer: '放大镜是凸透镜，中间厚边缘薄。光穿过凸透镜时会折射弯折。把物体放在放大镜一倍焦距以内，光线折射后进入眼睛，眼睛看到的是放大的虚像，所以物体看起来变大了。' },
    { category: '物理', question: '为什么铁块会沉而木头会浮？', answer: '物体浮沉取决于它的密度和水的密度。铁的密度比水大，同样体积的铁比水重，所以铁块下沉。木头的密度比水小，同样体积的木头比水轻，所以木头浮在水面。这叫阿基米德浮力原理。' },
    { category: '物理', question: '为什么声音有大有小？', answer: '声音是由物体振动产生的。物体振动幅度大产生的声音就大，振动幅度小声音就小。用力敲鼓鼓面振幅大声音就响，轻轻敲振幅小声音就弱。离声源越近声音越大，越远越小。' },
    { category: '物理', question: '为什么冬天脱毛衣会有静电？', answer: '不同材料摩擦时电子会从一个物体转移到另一个物体，使物体带电叫静电。冬天空气干燥，脱毛衣时衣物摩擦产生静电不易跑掉积聚起来，就会听到噼啪声看到小火花。潮湿天气静电少。' },
    { category: '物理', question: '为什么车轮要做成圆形？', answer: '圆形车轮滚动时，车轴到地面的距离始终等于半径不变，所以车行驶平稳不会颠簸。圆形滚动时与地面是点接触，摩擦力小跑得快省力。其他形状滚动时高度会变化会颠簸，所以车轮做成圆形。' },
    { category: '物理', question: '为什么会有热胀冷缩？', answer: '物体由分子组成，分子之间有空隙。温度升高时分子运动加快，分子间距离变大，物体体积膨胀叫热胀。温度降低时分子运动减慢，分子间距离变小，物体体积收缩叫冷缩。大多数物体都有热胀冷缩。' },
    { category: '物理', question: '为什么湿衣服会干？', answer: '湿衣服上的水不断蒸发变成水蒸气跑到空气中。温度越高空气越干燥风越大，水蒸发越快，衣服干得越快。所以晾衣服要放在有阳光通风的地方。蒸发是水从液态变成气态的过程。' },
    { category: '物理', question: '为什么玻璃是透明的？', answer: '玻璃是一种结构均匀的物质，可见光能直接穿过它几乎不被吸收，所以玻璃是透明的。而木头铁块等物质会吸收或阻挡光线，光穿不过去就不透明。水空气也是透明的，原理类似。' },
    { category: '物理', question: '为什么水能灭火？', answer: '水灭火主要有两个原因：一是水覆盖在燃烧物上隔绝了氧气，没有氧气火就烧不起来；二是水蒸发时会吸收大量热量，使燃烧物温度降到燃点以下。所以水能把火扑灭。但电器起火和油起火不能用水浇。' },
    { category: '物理', question: '为什么金属能导电？', answer: '金属内部有大量自由电子，它们可以在金属里自由移动。通电时这些自由电子定向移动形成电流，所以金属能导电。铜铝银是很好的导体。而塑料橡胶木头几乎没有自由电子不能导电是绝缘体。' },
    { category: '物理', question: '为什么太阳灶能烧水？', answer: '太阳灶是一个凹面镜，能把太阳光汇聚到一个焦点上。焦点处聚集了大量光能温度很高，把水壶放在焦点上，热量传给水就能把水烧开。这是利用太阳能的好方法既环保又省钱。' },
    { category: '物理', question: '为什么滑冰要穿冰刀？', answer: '冰刀很窄与冰面接触面积小，对冰面压强大。压强增大使冰的熔点降低，冰刀下的冰暂时融化成一层薄薄的水，这层水起润滑作用使摩擦力大大减小，所以穿冰刀能在冰上快速滑行。' },
    { category: '物理', question: '为什么骑自行车不会倒？', answer: '骑自行车时车轮快速转动，产生一种叫陀螺效应的稳定性，使车子不容易倒。另外骑行时人会不自觉地调整重心和车把方向保持平衡。骑得越快越稳，停下来反而容易倒。' },
    { category: '物理', question: '为什么肥皂能洗干净衣服？', answer: '肥皂分子一端亲水一端亲油。洗衣服时亲油端吸附在油污上，把油污从衣服上拉下来分散到水中，亲水端让油污悬浮在水里被水冲走，衣服就干净了。这就是肥皂去污的原理。' },
    { category: '物理', question: '为什么温度计能测温度？', answer: '常用温度计里面装的是水银或酒精等液体。液体有热胀冷缩的性质，温度升高液体体积膨胀液柱上升，温度降低液柱下降。看液柱对应的刻度就知道温度了。体温计就是用来量体温的温度计。' },
    { category: '物理', question: '为什么弹簧能弹起来？', answer: '弹簧是用弹性材料做的，受到外力时会变形。当外力消失后弹簧要恢复原来的形状，就产生弹力把东西弹回去。拉得越长或压得越紧，弹力越大。弹簧秤就是利用这个原理测力的大小。' },
    { category: '物理', question: '为什么高压锅做饭快？', answer: '高压锅密封好，加热时锅内气压升高。气压越高水的沸点越高，高压锅里水温可超过100度。温度高食物熟得快，所以高压锅做饭比普通锅快很多，还能节省燃料。' },
    { category: '物理', question: '为什么电灯会亮？', answer: '白炽灯泡里有灯丝，电流通过灯丝时，灯丝电阻大发热发光，灯就亮了。LED灯则是电流通过半导体材料直接发光，更省电寿命更长。电灯把电能变成光能，让我们在夜晚也有光明。' },
    { category: '物理', question: '为什么夏天穿浅色衣服凉快？', answer: '浅色衣服能反射大部分阳光，吸收的热量少，所以穿浅色衣服感觉凉快。深色衣服吸收阳光多吸热多，穿深色衣服感觉热。冬天穿深色衣服能吸收更多阳光更暖和。所以夏浅冬深有道理。' },
    { category: '物理', question: '为什么水珠是圆的？', answer: '水分子之间有吸引力叫表面张力。在表面张力作用下水会尽量缩小表面积。同样体积的物体球形表面积最小，所以小水珠在表面张力作用下缩成球形，看起来圆圆的。' },
    { category: '物理', question: '为什么不倒翁不会倒？', answer: '不倒翁底部很重，重心在底部。把它推倒时重心升高，重力使它回到原来重心最低的位置，所以它自己又立起来。不管怎么推它都会回到直立状态，这就是不倒翁不倒的秘密。' },
    { category: '物理', question: '为什么陀螺转起来不倒？', answer: '陀螺高速旋转时产生陀螺效应，旋转轴的方向趋于稳定不易改变，所以转动的陀螺能立着不倒。一旦转速慢下来陀螺效应减弱，陀螺就会摇晃倒下。骑自行车不倒也和这个原理有关。' },
    { category: '物理', question: '为什么三棱镜能把光分开？', answer: '白光是由红橙黄绿蓝靛紫七种颜色的光组成的。不同颜色的光波长不同，穿过三棱镜时折射程度不同，红光偏折最少紫光偏折最多，七种光被分开就形成彩色光带，这叫光的色散。' },
    { category: '物理', question: '为什么潜水艇能上浮下沉？', answer: '潜水艇有水舱。要下沉时往水舱注水，潜艇变重超过浮力就下沉。要上浮时把水舱里的水排出，潜艇变轻浮力大于重量就上浮。通过调节水舱里的水量，潜水艇就能自由上浮和下沉。' },
    { category: '物理', question: '为什么降落伞能减速？', answer: '降落伞张开时面积很大，下落时兜住大量空气，空气阻力大大增加。当空气阻力接近重力时，降落伞下落速度就变慢，人就能安全着陆。伞面越大阻力越大下落越慢。' },
    { category: '物理', question: '为什么会有惯性？', answer: '惯性是物体保持原来运动状态的性质。行驶的车突然刹车，人因惯性还要往前冲所以会前倾。静止的物体也有惯性，不容易动起来。一切物体都有惯性，质量越大惯性越大。系安全带就是为了防止惯性伤人。' },
    { category: '物理', question: '为什么飞机能飞上天？', answer: '飞机机翼上面弯曲下面平。飞机前进时空气流过机翼，上面空气流速快气压小，下面空气流速慢气压大，上下气压差产生向上的升力。速度越快升力越大，当升力大于飞机重量时飞机就飞起来了。' },
    { category: '物理', question: '为什么会有摩擦力？', answer: '两个物体接触时表面看似光滑其实凹凸不平。相对运动时这些凹凸互相咬合阻碍运动就产生摩擦力。摩擦力有利有弊：能让我们走路不滑倒，但也会使机器零件磨损。加润滑油可以减小摩擦。' },
    { category: '物理', question: '为什么杠杆能省力？', answer: '杠杆有力点阻力点和支点。当力点到支点的距离（动力臂）大于阻力点到支点的距离（阻力臂）时，用较小的力就能撬动较重的物体，这就是杠杆省力原理。撬棍开瓶器都利用了杠杆原理。' },
    { category: '物理', question: '为什么望远镜能看清远处？', answer: '望远镜有两组镜片。物镜把远处物体的光汇聚成实像，目镜再把实像放大。两者配合使我们能看到放大了的远处物体的像，所以用望远镜能看清肉眼看不清的远处物体。' },
    { category: '物理', question: '为什么物体会浮在水上？', answer: '物体浸在水中会受到向上的浮力，浮力大小等于物体排开水的重量。如果浮力大于物体重力物体就上浮，浮力小于重力就下沉，相等就悬浮。这就是阿基米德原理，船能浮在水上就是这个道理。' },
    { category: '物理', question: '为什么回音壁能传声很远？', answer: '回音壁的墙壁是圆形光滑的，声波碰到光滑墙面会反射，反射的声波继续传播又碰到墙面再反射。声波沿着圆形墙壁不断反射传到很远的地方，能量损失小，所以对面的人能听到说话声。' },
    { category: '化学', question: '为什么铁会生锈？', answer: '铁暴露在潮湿空气中，铁会和空气中的氧气和水发生氧化反应，生成红褐色的氧化铁就是铁锈。铁锈疏松多孔不能保护里面的铁，所以铁会一直锈下去。涂油漆镀锌保持干燥都能防锈。' },
    { category: '化学', question: '为什么盐能融化冰雪？', answer: '盐溶解在雪里形成盐水，盐水的凝固点比纯水低。在0度以下盐水也不会结冰，所以撒盐能使路面冰雪融化。但温度太低时盐的效果就不好了，这时需要用其他融雪剂。' },
    { category: '化学', question: '为什么火柴一划就着？', answer: '火柴头上有氯酸钾和硫等化学物质，火柴盒侧面涂有红磷。划火柴时摩擦产生热量使红磷着火，引燃火柴头上的化学物质，火柴就燃起来了。这是利用摩擦生热引发化学反应。' },
    { category: '化学', question: '为什么牛奶放久了会变酸？', answer: '牛奶含乳糖等营养物质。放久了空气中的乳酸菌进入牛奶，把乳糖分解成乳酸。乳酸使牛奶变酸，还会使蛋白质凝固成絮状。所以变酸的牛奶不能喝，喝了会肚子疼。' },
    { category: '化学', question: '为什么面团能发酵变大？', answer: '和面时加入酵母菌，酵母菌在温暖的面团里大量繁殖，把面团里的糖分分解产生二氧化碳气体。气体被包裹在面团里形成小气泡，面团就膨胀变大了。蒸烤时气泡固定面包就松软多孔。' },
    { category: '化学', question: '为什么小苏打能让面团膨松？', answer: '小苏打是碳酸氢钠，遇酸或受热会分解产生二氧化碳气体。揉面时加小苏打，产生的气体在面团里形成小气泡，使面团膨松。蒸馒头烤饼干时小苏打受热放出气体使食物松软。' },
    { category: '化学', question: '为什么铜器表面会变绿？', answer: '铜在潮湿空气中与氧气二氧化碳和水反应，生成绿色的碱式碳酸铜俗称铜绿。铜绿覆盖在铜器表面能保护里面的铜不再被腐蚀。古代青铜器上常有一层绿色就是铜绿。' },
    { category: '化学', question: '为什么糖放到水里会消失？', answer: '糖是由糖分子组成的。糖放到水里，糖分子在水分子作用下分散到水分子之间，均匀分布在水中形成糖水，所以看不到糖了，这叫溶解。水变甜是因为糖分子分散在水中。加热搅拌能加快溶解。' },
    { category: '化学', question: '为什么会有酸雨？', answer: '工厂烧煤和汽车尾气排放出二氧化硫和氮氧化物等气体，这些气体升到高空与水蒸气反应生成硫酸和硝酸，随雨水落下就是酸雨。酸雨会腐蚀建筑伤害植物污染水源，所以要减少有害气体排放。' },
    { category: '化学', question: '为什么灭火器能灭火？', answer: '灭火器里装有化学药剂，使用时药剂反应产生二氧化碳泡沫等不可燃物质覆盖在燃烧物上，隔绝氧气并降温，火就灭了。不同灭火器原理不同，干粉灭火器通过中断燃烧反应来灭火。' },
    { category: '化学', question: '为什么铅笔能写字？', answer: '铅笔芯的主要成分是石墨。石墨是碳的一种形式，质地软呈深灰色。写字时笔尖在纸上摩擦，石墨粉末附着在纸上就留下字迹。石墨按硬度分H和B等型号，H硬色浅B软色深。' },
    { category: '化学', question: '为什么蜡烛能燃烧？', answer: '蜡烛主要成分是石蜡。点燃烛芯，热量使石蜡熔化并汽化成可燃气体，气体燃烧发出光和热。燃烧是石蜡和氧气发生的化学反应，生成二氧化碳和水。没有氧气蜡烛就会熄灭。' },
    { category: '化学', question: '为什么钻石那么硬？', answer: '钻石和铅笔芯的石墨都是碳组成的，但原子排列不同。钻石里每个碳原子和周围四个碳原子紧紧连在一起形成立体网状结构，非常牢固，所以钻石是自然界最硬的物质。石墨是层状结构所以软。' },
    { category: '化学', question: '为什么水壶用久了会结水垢？', answer: '自来水中含有钙镁等矿物质。烧水时这些矿物质受热沉淀出来附着在水壶壁上，时间久了就形成一层硬硬的水垢。水垢影响传热浪费燃料，用醋可以溶解清除水垢。' },
    { category: '化学', question: '为什么紫甘蓝汁能变色？', answer: '紫甘蓝含有花青素，是一种酸碱指示剂。遇到酸性物质变红或粉红，遇到碱性物质变蓝或绿。所以把紫甘蓝汁滴到不同液体里会显示不同颜色，像神奇的药水一样能测出液体的酸碱性。' },
    { category: '化学', question: '为什么面包会膨胀变大？', answer: '做面包和面时加入酵母，酵母在温暖环境里把糖分分解产生二氧化碳。面团里的面筋有弹性把气体包住形成气泡，烤的时候气体膨胀气泡变大，面包就膨胀起来，烤熟后气泡固定面包就松软多孔。' },
    { category: '化学', question: '为什么汽油能洗掉油污？', answer: '汽油是一种有机溶剂，能溶解油污。衣服上沾了油渍，用汽油擦洗，汽油把油污溶解带走，汽油挥发后油污就没了。这和肥皂去污不同，汽油是直接溶解油污，适合洗纯油渍。' },
    { category: '化学', question: '为什么银器会变黑？', answer: '银和空气中的硫化氢或硫化合物反应生成黑色的硫化银，所以银器表面会变黑。鸡蛋空气污染等都含硫，会加速银器变黑。用牙膏擦拭或专门的银器清洁剂可以去除黑色让银器恢复光亮。' },
    { category: '化学', question: '为什么烟花是五颜六色的？', answer: '烟花里装有不同的金属化合物。不同金属在燃烧时火焰颜色不同，这叫焰色反应。锶是红色钡是绿色铜是蓝色钠是黄色。把这些化合物按配方混合，烟花爆炸就绽放出五颜六色的光芒。' },
    { category: '化学', question: '为什么嚼馒头会越嚼越甜？', answer: '馒头含淀粉没有甜味。唾液里有一种酶叫淀粉酶，能把淀粉分解成麦芽糖。麦芽糖是甜的，所以嚼馒头时间越长，淀粉被分解得越多，就越觉得甜。这是化学消化的第一步。' },
    { category: '化学', question: '为什么漂白水能把东西漂白？', answer: '漂白水含次氯酸钠，能放出活性氧。活性氧能破坏色素分子的结构，使有色物质变成无色，所以能把东西漂白。漂白水有腐蚀性，使用时要戴手套稀释，不能和洁厕剂混用以免产生毒气。' },
    { category: '化学', question: '为什么金属有金属光泽？', answer: '金属内部有大量自由电子。光照到金属表面时，自由电子吸收光又把光反射出来，所以金属有明亮的金属光泽。抛光的金属表面更光滑反射更强更有光泽。不同的金属光泽颜色略有不同。' },
    { category: '化学', question: '为什么塑料不容易腐烂？', answer: '塑料是人工合成的高分子化合物，结构很稳定，自然界里的微生物很难分解它，所以塑料不容易腐烂。一个塑料袋可能要几百年才能分解，会造成白色污染。我们要少用塑料袋注意回收利用。' },
    { category: '化学', question: '为什么石灰水会变浑浊？', answer: '石灰水是氢氧化钙溶液。往石灰水里吹气，呼出的二氧化碳和氢氧化钙反应生成不溶于水的碳酸钙白色沉淀，石灰水就变浑浊了。这个反应常用来检验二氧化碳气体的存在。' },
    { category: '化学', question: '为什么汽水里有很多气泡？', answer: '汽水是在高压下把二氧化碳气体压进水里制成的。打开瓶盖气压降低，二氧化碳在水里的溶解度变小，多余的气体跑出来形成大量气泡冒上来。喝汽水打嗝就是二氧化碳气体从体内排出。' },
    { category: '化学', question: '为什么食物会腐烂变质？', answer: '食物含有丰富的营养，空气中的细菌霉菌等微生物落在食物上大量繁殖，把食物里的营养成分分解掉，产生异味和有害物质，食物就腐烂变质了。低温干燥密封能减缓微生物繁殖，延长食物保质期。' },
    { category: '化学', question: '为什么不锈钢不容易生锈？', answer: '不锈钢是在铁里加入铬镍等金属制成的合金。铬在表面形成一层致密的氧化铬薄膜，像保护膜一样隔绝氧气和水，防止里面的铁继续被氧化，所以不锈钢不容易生锈。' },
    { category: '化学', question: '为什么粉笔能在黑板上写字？', answer: '粉笔主要成分是石膏(硫酸钙)质地软而白。写字时粉笔在黑板上摩擦，粉笔粉末附着在粗糙的黑板表面就留下字迹。黑板粗糙能挂住粉笔灰，擦黑板时黑板擦把粉笔灰擦掉字就没了。' },
    { category: '化学', question: '为什么樟脑丸会越来越小？', answer: '樟脑丸是萘或樟脑做的，这种物质在常温下会直接从固体变成气体，这叫升华。樟脑丸放在衣柜里慢慢升华变成气体挥发掉，所以会越来越小最后消失。升华产生的气体能驱虫防霉。' },
    { category: '化学', question: '为什么酒精能消毒？', answer: '酒精能渗入细菌体内使蛋白质凝固变性，细菌就死了，所以酒精能消毒杀菌。百分之七十五的酒精消毒效果最好，浓度太高会使表面蛋白质迅速凝固形成保护膜反而不杀菌，太稀杀菌力不够。' },
    { category: '日常生活', question: '为什么打雷时不能站在树下？', answer: '打雷时云层带电，高的树木容易吸引雷电。站在树下万一雷电劈到树，电流会通过树干传到地面，可能伤到树旁的人。所以打雷时要远离大树和空旷高地，到室内躲避才安全。' },
    { category: '日常生活', question: '为什么肥皂泡是彩色的？', answer: '肥皂泡是一层薄薄的水膜，光照到肥皂泡内外两个表面反射。两束反射光相互干涉，有的颜色加强有的减弱，就形成五颜六色的彩色条纹。这就是光的薄膜干涉现象，所以肥皂泡看起来彩色。' },
    { category: '日常生活', question: '为什么吃太咸的东西后想喝水？', answer: '盐分多了血液里盐浓度升高，身体为了保持平衡需要稀释盐分。大脑检测到血液变咸就发出渴的信号，让我们喝水来稀释盐分通过尿液排出多余的盐。所以吃咸了要多喝水。' },
    { category: '日常生活', question: '为什么不能空腹喝牛奶？', answer: '空腹喝牛奶时牛奶很快通过胃进入肠道，牛奶里的蛋白质来不及被充分消化吸收就被排出，造成浪费。而且有些人空腹喝牛奶会腹胀腹泻。先吃些面包等食物再喝牛奶吸收更好。' },
    { category: '日常生活', question: '为什么不能多吃糖？', answer: '糖吃多了有几个坏处：糖残渣留在牙里被细菌分解产生酸腐蚀牙齿形成蛀牙；多余的糖会变成脂肪堆积让人发胖；吃太多糖还会影响食欲不想吃正餐导致营养不均衡。所以要少吃糖。' },
    { category: '日常生活', question: '为什么饭前便后要洗手？', answer: '我们的手每天接触很多东西会沾上很多细菌和虫卵。饭前不洗手，手上的细菌会跟着食物吃进肚子里引起肚子疼拉肚子。便后手上也有细菌更要洗手。用肥皂洗手能去掉大部分细菌。' },
    { category: '日常生活', question: '为什么小朋友不能挑食？', answer: '不同食物含不同营养，肉类含蛋白质帮助长身体，蔬菜含维生素和纤维促进消化，米饭含碳水化合物提供能量。挑食会造成某些营养缺乏影响生长发育和免疫力。所以要不挑食营养均衡。' },
    { category: '日常生活', question: '为什么睡觉要盖被子？', answer: '睡觉时人不动了身体产热减少，体温容易下降。盖被子能保持身体温暖防止着凉感冒。尤其夜里气温低，不盖被子容易受凉。被子还能挡风，让睡眠更舒适安稳。' },
    { category: '日常生活', question: '为什么不能长时间看电视手机？', answer: '长时间盯着屏幕眼睛一直紧张调节容易疲劳，久了会近视。屏幕的蓝光还会伤害眼睛。看屏幕时间长了也影响脊椎和睡眠。建议每看20分钟远眺20秒，每天不超过一小时保护眼睛。' },
    { category: '日常生活', question: '为什么读书写字姿势要端正？', answer: '姿势不端正离书本太近，眼睛要使劲调节看清字，久了会造成近视。弯腰驼背还会使脊椎变形影响发育。正确姿势是眼离书一尺胸离桌一拳手离笔尖一寸，能保护视力和脊椎。' },
    { category: '日常生活', question: '为什么早饭一定要吃好？', answer: '经过一晚睡眠，胃里食物消化完了，上午学习需要大量能量。不吃早饭血糖低会头晕没精神注意力不集中，长期不吃还伤胃。早饭要吃好有营养，给一天的学习提供充足能量。' },
    { category: '日常生活', question: '为什么不能喝生水？', answer: '生水(没烧开的水)里可能有细菌病毒和寄生虫卵，喝了容易拉肚子甚至得传染病。把水烧开能杀死这些有害微生物，喝开水才安全。井水河水更不能直接喝一定要烧开后饮用。' },
    { category: '日常生活', question: '为什么感冒了要多休息？', answer: '感冒时身体在和病毒作斗争，需要集中能量让免疫系统工作。休息能减少能量消耗让身体专心对抗病毒。如果还剧烈活动消耗体力，抵抗力下降感冒不容易好。多喝水多休息好得快。' },
    { category: '日常生活', question: '为什么背书包要双肩背？', answer: '单肩背包一边肩膀受力，长期会造成肩膀一高一低脊柱侧弯影响体态。双肩背两个肩膀均匀受力，背起来省力也不会影响脊柱发育。书包太重时要整理好减轻重量保护肩膀和腰背。' },
    { category: '日常生活', question: '为什么不能边走边吃东西？', answer: '边走边吃有几个坏处：走路时灰尘细菌容易落到食物上不卫生；边走边吃消化不好容易肚子疼；走路注意力分散容易呛到或摔倒。所以吃东西要坐下来安心吃吃完再走。' },
    { category: '日常生活', question: '为什么吃晚饭不能太晚？', answer: '晚饭吃太晚离睡觉时间近，食物没消化完就睡觉，会加重胃的负担影响消化，容易得胃病。还会影响睡眠质量，多余热量变成脂肪让人发胖。晚饭最好在睡前两三小时吃，吃七八分饱。' },
    { category: '日常生活', question: '为什么不能蒙头睡觉？', answer: '蒙头睡觉被子里的空气不流通，呼出的二氧化碳越积越多，氧气越来越少。长时间吸不到新鲜空气会头晕胸闷睡不好觉，第二天没精神。所以睡觉要把头露在外面保持呼吸顺畅。' },
    { category: '日常生活', question: '为什么饭后不能马上剧烈运动？', answer: '饭后胃里装满食物需要大量血液帮助消化。这时剧烈运动，血液流向肌肉胃里血液减少，影响消化容易肚子疼。饭后应休息半小时到一小时，可以散步等轻微活动，一小时后再做剧烈运动。' },
    { category: '日常生活', question: '为什么不能咬铅笔？', answer: '铅笔表面涂有油漆可能含铅等有害物质，咬铅笔会把有害物质吃进身体影响健康。咬铅笔还会损坏牙齿，铅笔屑也可能误吞。另外铅笔上有很多细菌不卫生。所以要改掉咬铅笔的坏习惯。' },
    { category: '日常生活', question: '为什么冬天穿深色衣服暖和？', answer: '深色衣服吸收阳光多，能把更多太阳光变成热量，所以冬天穿深色衣服比较暖和。浅色衣服反射阳光多吸热少。另外冬天穿的厚衣服里有空气层能保温，深色衣料吸热后保温效果更好。' },
    { category: '日常生活', question: '为什么不能用湿手摸电器？', answer: '水能导电，湿手上有水摸电器时，电可能通过水传到人身上造成触电。生活用水不是纯水含有矿物质更容易导电。所以摸电器开关插头前一定要把手擦干，湿手绝对不能碰电器。' },
    { category: '日常生活', question: '为什么过马路要看红绿灯？', answer: '红绿灯是交通信号灯，红灯停绿灯行黄灯等一等。红灯时车辆通行行人停下等待，绿灯时行人可以安全通过。看红绿灯能避免人和车抢道发生危险，是保护行人安全的重要规则，人人都要遵守。' },
    { category: '日常生活', question: '为什么小朋友不能玩火？', answer: '火很危险，小朋友对火的认识不够，玩火容易引发火灾烧毁房屋伤及人身。火势一旦蔓延很难控制，会造成严重后果。打火机火柴要放在小朋友拿不到的地方，发现火灾要拨打119报警。' },
    { category: '日常生活', question: '为什么夏天要多喝水？', answer: '夏天天气热出汗多，身体会流失大量水分和盐分。如果不及时补充水分，会口渴头晕甚至中暑。所以夏天要多喝水，出汗多时还可以喝点淡盐水补充盐分，不要等渴了才喝要主动喝水。' },
    { category: '日常生活', question: '为什么食物要多样化？', answer: '没有一种食物含有人体需要的所有营养。肉类提供蛋白质，蔬菜水果提供维生素，米饭面食提供能量，牛奶补钙。只有吃各种各样的食物才能获得全面均衡的营养，保证身体健康成长。' },
    { category: '日常生活', question: '为什么睡前不能吃东西？', answer: '睡前吃东西胃要加班消化影响睡眠，食物没消化完躺着还容易反流。长期睡前吃东西会加重胃的负担引起消化不良，还会因为热量消耗不掉变成脂肪让人发胖。睡前一两小时最好别吃东西。' },
    { category: '日常生活', question: '为什么不能长时间吹空调？', answer: '空调房门窗紧闭空气不流通，时间长了空气变差容易头晕。空调房温度低和室外温差大，进出容易感冒。空调还会使空气干燥皮肤嗓子不舒服。所以空调温度别太低，定时开窗通风多喝水。' },
    { category: '日常生活', question: '为什么坐车要系安全带？', answer: '车突然刹车或碰撞时，人因惯性会向前冲撞到前面造成伤害。安全带能把人固定在座位上防止撞击。研究表明系安全带能大大减少车祸伤亡。所以坐车无论前后排都要系好安全带保护自己。' },
    { category: '日常生活', question: '为什么不能在河边危险地方玩耍？', answer: '河边湿滑容易滑倒掉进水里，小朋友不会游泳很危险。河边的泥土松软可能塌陷，有的河水深看不见底。在河边玩耍万一落水后果严重。所以不要独自去河边池塘边玩耍，要有大人陪同注意安全。' },
    { category: '日常生活', question: '为什么要经常开窗通风？', answer: '室内人呼吸会产生二氧化碳，还有各种气味和细菌。门窗紧闭时间长了空气污浊氧气减少，人会觉得头晕不舒服。开窗通风能换进新鲜空气排出污浊空气，减少细菌病毒传播，对身体好。' },
    { category: '历史文化', question: '为什么中国人过年要贴春联？', answer: '春联源于古代的桃符。古人认为桃木能驱鬼避邪，过年时在桃木板上写神荼郁垒两位神将的名字挂在门上保平安。后来改成在红纸上写吉利话，就成了春联。贴春联表达人们对新年的美好祝愿。' },
    { category: '历史文化', question: '为什么端午节要吃粽子赛龙舟？', answer: '相传战国时楚国诗人屈原在五月初五投汨罗江殉国。百姓划船去救他演变成赛龙舟，又怕鱼虾吃屈原的身体就往江里投粽子喂鱼。后来端午节吃粽子赛龙舟就成了纪念屈原的传统习俗。' },
    { category: '历史文化', question: '为什么中秋节要吃月饼赏月？', answer: '中秋是农历八月十五，月亮最圆最亮。古人把圆月当作团圆的象征，全家聚在一起赏月。月饼是圆的代表团圆，所以中秋节要吃月饼。这个习俗从唐朝开始流行，表达人们对家人团聚的期盼。' },
    { category: '历史文化', question: '为什么元宵节要猜灯谜？', answer: '元宵节是农历正月十五。古时挂花灯庆祝，有人把谜语写在纸条上贴在花灯上让人猜，猜中有奖。猜灯谜既有趣又能长知识，还能增添节日气氛，从宋代起就成了元宵节的传统活动。' },
    { category: '历史文化', question: '为什么清明节要扫墓踏青？', answer: '清明既是节气也是节日。清明时节万物复苏，人们在这天祭拜祖先扫墓表达对先人的怀念。同时春天天气好适合外出，扫墓后顺便游玩踏青欣赏春光。扫墓和踏青是清明节两大传统。' },
    { category: '历史文化', question: '为什么重阳节要登高喝菊花酒？', answer: '重阳是农历九月初九，古人认为九是阳数两九相重叫重阳。传说登高喝菊花酒能避灾。这天秋高气爽适合爬山，菊花盛开可赏菊。1989年起重阳节被定为敬老节，倡导尊老爱老。' },
    { category: '历史文化', question: '为什么古代人要修建长城？', answer: '古代北方游牧民族常骑马南下侵扰，中原以农耕为主。为防御骑兵进攻，从春秋战国起各国就开始修筑长城。秦始皇统一后把各国长城连起来。长城依山而建易守难攻，是重要的军事防御工程。' },
    { category: '历史文化', question: '为什么秦始皇要统一文字？', answer: '秦统一六国前各国文字不同，政令不通交流困难。秦始皇下令用小篆作为全国统一文字，方便政令传达和百姓交流。统一文字促进了文化认同和国家统一，对中华文明延续有重要作用。' },
    { category: '历史文化', question: '为什么丝绸之路叫丝绸之路？', answer: '西汉张骞出使西域开辟了从长安到中亚欧洲的商路。这条路主要运输中国出产的丝绸，丝绸运到西方很受欢迎，所以德国学者称之为丝绸之路。丝绸之路也传播了文化技术促进了东西方交流。' },
    { category: '历史文化', question: '为什么古人称老师为先生？', answer: '先是有先后的先，生指人。先生原意是先出生的人，也就是长辈。古人尊重有学问的长辈，称老师为先生表示老师比自己年长有见识值得尊敬。现在先生也用作对人的尊称，但在学校仍用来称呼老师。' },
    { category: '历史文化', question: '为什么古代建筑多用木头而不用石头？', answer: '中国树木资源丰富取材方便，木头加工容易建造快。木头建筑抗震好住着舒适。古人还认为木头有生命符合天人合一思想。而西方石头多崇尚永恒用石建筑。中国木建筑故宫是杰出代表。' },
    { category: '历史文化', question: '为什么京剧演员脸上要画脸谱？', answer: '京剧脸谱用不同颜色图案表现人物性格。红脸代表忠勇如关羽，黑脸代表刚正如包拯，白脸代表奸诈如曹操，金脸代表神仙。观众一看脸谱就知道角色好坏，这是京剧特有的化妆艺术。' },
    { category: '历史文化', question: '为什么古人写字要从右到左？', answer: '古人在竹简上写字，写好后卷起来。展开时右手拿卷左手展开，从右往左看比较顺手，所以从右到左竖着写。后来用纸也沿袭了这个习惯。近代为方便与国际接轨改为从左到右横着写。' },
    { category: '历史文化', question: '为什么中国的房子多朝南？', answer: '中国大部分在北半球，太阳偏南。房子朝南冬天阳光能照进屋保暖，夏天阳光直射屋顶照不进屋里凉爽。朝南还能避开寒冷北风。坐北朝南冬暖夏凉，是中国传统建筑的讲究。' },
    { category: '历史文化', question: '为什么古代皇帝穿黄色衣服？', answer: '黄色在古代是尊贵的颜色。唐代起皇帝规定黄色为皇家专用，百姓不能穿。黄色象征中央和土地，皇帝是天子代表天下。龙袍上绣龙纹，龙是皇帝的象征。所以黄色成了皇帝的标志色。' },
    { category: '历史文化', question: '为什么过年要发红包？', answer: '红包又叫压岁钱。传说有种叫祟的小妖过年时摸小孩头让孩子发烧变傻。人们用红纸包铜钱放枕边，铜钱闪光吓跑小妖。后来红纸包钱成压岁钱，意为压住邪祟保孩子平安。现在发红包是祝福。' },
    { category: '历史文化', question: '为什么十二生肖里没有猫？', answer: '十二生肖在先秦就基本定型，那时中国还没有家猫。家猫原产埃及，汉代才沿丝绸之路传入中国，而生肖已定型无法再加。所以十二生肖有鼠有虎却没有猫。民间还有猫鼠结仇的有趣传说。' },
    { category: '历史文化', question: '为什么古代称学校为书院？', answer: '书院是古代私人讲学和藏书的地方。始于唐代盛于宋代，著名的有白鹿洞书院岳麓书院。书院不仅是学习的地方，也是学者讨论学问的场所。书院教育注重品德修养，是中国古代教育的重要形式。' },
    { category: '历史文化', question: '为什么古人称结婚为完婚？', answer: '完是完成的意思。古人认为结婚是人生大事，结了婚才算成家立业，人生大事完成一件。完婚也指婚礼各项仪式都完成了。古人重视婚礼，把结婚看作承前启后传宗接代的大事。' },
    { category: '历史文化', question: '为什么中秋节又叫团圆节？', answer: '中秋月亮又圆又亮，圆代表团圆。出门在外的人中秋这天尽量赶回家和家人团聚一起赏月吃月饼。即使回不去也望月思念亲人，表达团圆的愿望。所以中秋节又叫团圆节，是家人团聚的节日。' },
    { category: '历史文化', question: '为什么古代官员上朝要拿笏板？', answer: '笏板是古代大臣上朝时拿的狭长板子。大臣要把奏报的事写在笏板上防止忘记，类似备忘录。不同品级用不同材质，象牙为尊玉次之。拿笏板也是礼仪表示对皇帝的恭敬。清代以后废除。' },
    { category: '历史文化', question: '为什么中国被誉为瓷器之国？', answer: '中国是瓷器的故乡，商代就出现原始瓷器，东汉烧出真正的瓷器。瓷器的英文名china和China中国同名，可见瓷器是中国的代表。景德镇是著名瓷都。瓷器经丝绸之路传到世界，所以中国称瓷器之国。' },
    { category: '历史文化', question: '为什么过年要放鞭炮？', answer: '传说过年有种叫年的怪兽出来伤人，人们发现年怕红色怕响声。于是过年时烧竹子发出噼啪响声赶走年兽，后来用火药做成鞭炮。放鞭炮还有辞旧迎新增添喜庆的意思，是过年的传统习俗。' },
    { category: '历史文化', question: '为什么古代称医生为大夫郎中？', answer: '大夫和郎中本是古代官职名称。宋代为提高医生地位，尊称医生为大夫或郎中。这反映古人对行医者的尊重，因为医生治病救人很重要。现在北方多称医生为大夫，南方多称郎中或医生。' },
    { category: '历史文化', question: '为什么古人把书叫做汗牛充栋？', answer: '汗牛充栋形容书多。汗牛指牛拉书累得出汗，充栋指书堆满屋子顶到房梁。古人书多搬运用牛车，牛累出汗；存放堆到屋梁。这个成语出自柳宗元文章，形容藏书极多，是赞美人学识渊博。' },
    { category: '历史文化', question: '为什么古代小孩要背三字经？', answer: '三字经是宋代王应麟编的启蒙读物，三字一句朗朗上口好记。内容涵盖历史天文地理道德，是古代儿童的必修课本。背三字经既能识字又能学知识懂道理，所以古代小孩入学先背三字经。' },
    { category: '历史文化', question: '为什么过年要扫尘？', answer: '腊月二十四扫尘是过年习俗。尘和陈谐音，扫尘就是扫去陈旧的东西，寓意把一年的晦气穷运扫出门，干干净净迎新年。扫尘也确实把家里打扫干净，让人心情舒畅过个好年。' },
    { category: '历史文化', question: '为什么古人称丈夫为良人？', answer: '良人在古代是夫妻互称，意为好人。后来专指丈夫。古人认为好丈夫应是善良有担当的人，所以称丈夫为良人。后来又演变为郎君相公官人等。这些称呼都体现了古人对夫妻关系的重视和尊重。' },
    { category: '历史文化', question: '为什么中国的国花候选有牡丹梅花？', answer: '牡丹雍容华贵代表繁荣昌盛，唐代就被誉为国色天香。梅花凌寒独放象征坚贞不屈的民族精神。两种花各有特色都深受中国人喜爱。关于国花一直有争议，目前牡丹和梅花都是有力的国花候选。' },
    { category: '历史文化', question: '为什么古人要把筷子称为箸？', answer: '箸是筷子的古称。后来船家忌讳箸和住同音，住有停止不前之意不吉利，于是反其意改称快儿，希望船行得快。因快儿多用竹木做又加了竹字头，就成了筷子。现在南方有些地方还保留叫箸的习惯。' },
    //WHY_END
  ],

  // ===== 百科知识 =====
  encyclopedia: [
    // ---- 中国历史 ----
    { category: '中国历史', title: '夏朝', content: '约公元前2070年大禹建立夏朝，是中国史书上记载的第一个世袭制朝代。禹的儿子启继位，把禅让制改为世袭制。夏朝共传十四代十七王，约四百多年，最后被商汤所灭。' },
    { category: '中国历史', title: '商朝', content: '约公元前1600年商汤灭夏建立商朝。商朝多次迁都，盘庚迁殷后稳定下来所以又叫殷商。商朝已有成熟的甲骨文，是汉字的前身。青铜器制造发达，司母戊鼎是代表作。商纣王无道被周武王所灭。' },
    { category: '中国历史', title: '周朝', content: '公元前1046年周武王灭商建周，定都镐京称西周。周平王东迁洛邑后称东周。东周分春秋和战国两个时期。周朝实行分封制，天子把土地分给诸侯。周朝共传三十代三十七王，享国约八百年。' },
    { category: '中国历史', title: '春秋五霸', content: '春秋时期周天子衰微，诸侯争霸。齐桓公宋襄公晋文公秦穆公楚庄王相继称霸，史称春秋五霸。齐桓公任用管仲改革最早称霸，晋文公城濮之战大败楚军。春秋时期百家争鸣文化繁荣。' },
    { category: '中国历史', title: '战国七雄', content: '战国时期齐楚燕韩赵魏秦七国最强，史称战国七雄。各国变法图强，秦国商鞅变法最彻底国力大增。经过长期兼并战争，秦王嬴政先后灭掉六国，于公元前221年统一中国，建立秦朝。' },
    { category: '中国历史', title: '秦朝', content: '公元前221年秦始皇统一六国建立秦朝，定都咸阳。秦始皇统一文字货币度量衡，修长城建驰道，设郡县制。但秦朝赋税沉重徭役繁多，秦始皇死后不久陈胜吴广起义，秦朝二世而亡，仅存十五年。' },
    { category: '中国历史', title: '汉朝', content: '公元前202年刘邦建立汉朝，定都长安史称西汉。汉武帝时国力最强，派张骞出使西域开辟丝绸之路。公元9年王莽篡汉西汉亡。光武帝刘秀恢复汉朝迁都洛阳史称东汉。汉朝共四百多年。' },
    { category: '中国历史', title: '三国鼎立', content: '东汉末年群雄割据，最后形成魏蜀吴三国鼎立。曹操控制北方建立魏，刘备占据西南建立蜀汉，孙权占据东南建立吴。三国互相征伐，最后司马炎篡魏灭蜀吴，于公元280年统一建立晋朝。' },
    { category: '中国历史', title: '晋朝', content: '公元265年司马炎建立西晋，280年统一全国。但西晋很快因八王之乱衰弱，316年被少数民族所灭。317年司马睿在建康建立东晋偏安江南。两晋共一百五十多年。晋朝书法兴盛王羲之是代表。' },
    { category: '中国历史', title: '南北朝', content: '东晋后南方依次经历宋齐梁陈四朝称南朝。北方少数民族建立多个政权，后北魏统一北方又分裂为东魏西魏，再演变为北齐北周称北朝。南北对立近一百七十年，最后隋文帝统一全国。' },
    { category: '中国历史', title: '隋朝', content: '公元581年隋文帝杨坚建立隋朝，589年灭陈统一全国。隋朝开创科举制和三省六部制，影响深远。隋炀帝开凿大运河沟通南北。但隋炀帝暴政劳民，引发农民起义，隋朝仅存三十七年而亡。' },
    { category: '中国历史', title: '唐朝', content: '公元618年李渊建立唐朝，定都长安。唐太宗开创贞观之治，唐玄宗开创开元盛世，唐朝国力强盛文化繁荣。唐诗是中国文学高峰，李白杜甫白居易是代表。安史之乱后唐朝衰落，907年灭亡，共近三百年。' },
    { category: '中国历史', title: '宋朝', content: '公元960年赵匡胤陈桥兵变建立宋朝，定都东京史称北宋。北宋重文轻武经济文化发达，毕昇发明活字印刷。1127年金兵南下北宋亡。赵构南渡建立南宋定都临安。宋朝共三百多年，后被元朝所灭。' },
    { category: '中国历史', title: '元朝', content: '1206年成吉思汗建立蒙古汗国，不断扩张。1271年忽必烈改国号为元，1279年灭南宋统一全国。元朝疆域辽阔是史上最大。元朝实行行省制度。马可波罗来元游历写下游记。元朝不足百年被明朝取代。' },
    { category: '中国历史', title: '明朝', content: '1368年朱元璋建立明朝，定都南京后迁北京。明初郑和七下西洋宣扬国威。明朝修筑明长城，编纂永乐大典。明朝中后期资本主义萌芽，但政治腐败宦官专权。1644年李自成攻入北京，明朝灭亡。' },
    { category: '中国历史', title: '清朝', content: '1636年皇太极改国号为清，1644年清军入关定都北京。康熙雍正乾隆三朝是盛世，疆域奠定今日版图。但清朝闭关锁国逐渐落后。1840年鸦片战争后沦为半殖民地。1911年辛亥革命爆发，清朝灭亡。' },
    { category: '中国历史', title: '秦始皇', content: '秦始皇嬴政是中国第一位皇帝。他十三岁继位为秦王，二十二岁亲政，重用李斯王翦等，十年间灭六国统一天下。他自称始皇帝，统一文字货币度量衡，修长城建陵墓。公元前210年病逝于巡游途中。' },
    { category: '中国历史', title: '汉武帝', content: '汉武帝刘彻是西汉第七位皇帝，在位五十四年。他罢黜百家独尊儒术，派卫青霍去病北击匈奴，派张骞出使西域开辟丝绸之路，开通丝绸之路。汉武帝时期汉朝疆域空前辽阔国力最强，是位雄才大略的皇帝。' },
    { category: '中国历史', title: '唐太宗', content: '唐太宗李世民是唐朝第二位皇帝。他助父建唐功勋卓著，玄武门之变后继位。唐太宗虚心纳谏重用魏征，开创贞观之治。他推行均田制减轻赋税，社会安定经济繁荣，被誉为千古明君。' },
    { category: '中国历史', title: '武则天', content: '武则天是中国历史上唯一的女皇帝。她原是唐太宗才人，后成为唐高宗皇后，逐渐掌握大权。公元690年自立为帝改国号为周。武则天重视科举选拔人才，统治时期社会经济继续发展。晚年还政于唐。' },
    { category: '中国历史', title: '孔子', content: '孔子名丘字仲尼，春秋末期鲁国人，是伟大的思想家教育家。他创立儒家学派，主张仁和礼，提倡有教无类因材施教。相传孔子有弟子三千贤人七十二。他的言行被弟子记录在论语中，影响中国两千多年。' },
    { category: '中国历史', title: '老子', content: '老子姓李名耳字聃，春秋末期楚国人，是道家学派创始人。老子主张无为而治，认为事物会向对立面转化。他写的道德经只有五千字却博大精深，是中国哲学经典。老子被道教尊为太上老君。' },
    { category: '中国历史', title: '司马迁', content: '司马迁是西汉伟大的史学家文学家。他继父任太史令，因替李陵辩护受宫刑。他忍辱负重用十几年写成史记。史记是中国第一部纪传体通史，记载了从黄帝到汉武帝约三千年历史，被鲁迅誉为史家之绝唱。' },
    { category: '中国历史', title: '诸葛亮', content: '诸葛亮字孔明，三国蜀汉丞相，杰出的政治家军事家。他辅佐刘备建立蜀汉，刘备托孤后他鞠躬尽瘁死而后已。诸葛亮发明木牛流马孔明灯，留下出师表等名篇。他是忠臣和智慧的象征。' },
    { category: '中国历史', title: '郑和下西洋', content: '明朝永乐年间郑和率领庞大船队七次下西洋。从1405到1433年，船队到过亚非三十多国最远到非洲东岸。郑和下西洋比哥伦布早八十多年，规模也大得多。这是世界航海史上的壮举，增进了中外交流。' },
    { category: '中国历史', title: '四大发明', content: '四大发明是造纸术印刷术火药指南针，是中国对世界的伟大贡献。东汉蔡伦改进造纸术，北宋毕昇发明活字印刷，火药是炼丹时发明的，指南针用于航海。四大发明经阿拉伯传到欧洲，推动了世界文明。' },
    { category: '中国历史', title: '丝绸之路', content: '丝绸之路是古代中国通往中亚欧洲的商路，西汉张骞出使西域后开辟。因主要运输丝绸得名。丝绸之路不仅贸易商品，还传播了文化宗教技术，促进了东西方交流。海上丝绸之路也同时发展。' },
    { category: '中国历史', title: '大运河', content: '隋炀帝时期开凿的京杭大运河，北起北京南到杭州，全长约一千八百公里，是世界最长的人工运河。大运河沟通海河黄河淮河长江钱塘江五大水系，促进了南北经济文化交流，至今仍部分通航。' },
    { category: '中国历史', title: '长城', content: '长城是古代防御工程，从春秋战国开始修建。秦始皇把各国长城连成一体。明代重修的长城东起鸭绿江西到嘉峪关。长城依山而建气势雄伟，是世界文化遗产，也是中华民族坚韧精神的象征。' },
    { category: '中国历史', title: '科举制', content: '科举制是隋朝创立的选官制度，通过考试选拔人才。隋炀帝设进士科，唐代完善。科举制打破了世家大族垄断做官的局面，让平民也能通过读书做官。科举制延续了约一千三百年，清末1905年废除。' },
    { category: '中国历史', title: '贞观之治', content: '贞观是唐太宗的年号。唐太宗吸取隋亡教训，虚心纳谏重用人才，轻徭薄赋发展生产，社会安定经济繁荣，史称贞观之治。贞观之治为唐朝盛世奠定基础，是历代治世的典范，唐太宗被誉为明君。' },
    { category: '中国历史', title: '开元盛世', content: '开元是唐玄宗前期的年号。唐玄宗任用贤能改革弊政，发展经济，唐朝达到鼎盛，国力强盛文化繁荣万邦来朝，史称开元盛世。但唐玄宗后期宠信杨贵妃不理朝政，引发安史之乱，唐朝由盛转衰。' },
    { category: '中国历史', title: '安史之乱', content: '公元755年唐朝将领安禄山史思明发动叛乱，史称安史之乱。叛军攻占洛阳长安，唐玄宗逃往四川。安史之乱持续八年才被平定，但唐朝元气大伤由盛转衰。这是唐朝乃至中国历史的重大转折点。' },
    { category: '中国历史', title: '鸦片战争', content: '1840年英国为打开中国市场倾销鸦片发动侵略战争，史称鸦片战争。清政府战败被迫签订南京条约，割香港赔巨款开口岸。鸦片战争是中国近代史的开端，中国开始沦为半殖民地半封建社会。' },
    { category: '中国历史', title: '辛亥革命', content: '1911年孙中山领导的辛亥革命爆发，推翻了清朝统治，结束了中国两千多年的封建帝制。1912年元旦中华民国成立。辛亥革命是伟大的民主革命，但革命果实被袁世凯窃取，没有改变中国半殖民地性质。' },
    { category: '中国历史', title: '孙中山', content: '孙中山名文字逸仙，是伟大的民主革命先行者。他创建同盟会提出三民主义，领导辛亥革命推翻帝制建立民国。他矢志革命百折不挠，临终留下革命尚未成功同志仍须努力的遗训，被尊为国父。' },
    { category: '中国历史', title: '官渡之战', content: '公元200年曹操与袁绍在官渡决战。袁绍兵多粮足，曹操兵少但善用计谋。曹操采纳许攸计策夜袭乌巢烧毁袁绍粮草，袁军大乱。曹操以少胜多打败袁绍，为统一北方奠定基础，是著名以弱胜强的战役。' },
    { category: '中国历史', title: '赤壁之战', content: '公元208年曹操率大军南下，孙权刘备联军在赤壁迎战。周瑜采用黄盖诈降火攻之计，借东南风火烧曹军战船，曹军大败。赤壁之战是以少胜多的著名战役，奠定了三国鼎立的基础。' },
    { category: '中国历史', title: '淝水之战', content: '公元383年前秦苻坚率大军南下攻东晋，东晋谢安谢玄率军在淝水迎战。东晋以八万兵力大败前秦号称百万的大军。苻坚中箭溃逃，留下风声鹤唳草木皆兵的典故。此战保全了东晋偏安江南。' },
    { category: '中国历史', title: '文成公主入藏', content: '唐太宗把文成公主嫁给吐蕃赞普松赞干布。文成公主带去谷物种子医药书籍和工匠，传播了中原先进文化技术，促进了吐蕃经济文化发展。文成公主入藏加强了汉藏友好，传为历史佳话。' },
    { category: '中国历史', title: '玄武门之变', content: '公元626年秦王李世民在长安玄武门发动政变，杀死了太子李建成和齐王李元吉。唐高祖李渊被迫立李世民为太子，不久让位。李世民继位即唐太宗。玄武门之变使李世民登上皇位开创贞观之治。' },
    { category: '中国历史', title: '杯酒释兵权', content: '宋太祖赵匡胤建国后担心将领兵权过重，设宴请石守信等大将喝酒，借酒暗示他们交出兵权。将领们领会帝意，第二天纷纷称病交出兵权。这就是杯酒释兵权。赵匡胤兵不血刃收回兵权加强了中央集权。' },
    { category: '中国历史', title: '靖康之变', content: '1127年金兵攻破北宋都城东京，掳走宋徽宗宋钦宗父子及大量皇族大臣，北宋灭亡，史称靖康之变。岳飞词中靖康耻犹未雪即指此事。康王赵构南渡在临安建立南宋，与金对峙了一百多年。' },
    { category: '中国历史', title: '郑成功收复台湾', content: '明末荷兰殖民者侵占台湾。1661年郑成功率领大军从金门出发渡海东征，经过九个月战斗，1662年迫使荷兰投降收复台湾。郑成功成为民族英雄。他在台湾设府治理开发，可惜收复台湾同年病逝。' },
    { category: '中国历史', title: '虎门销烟', content: '清朝道光年间英国向中国大量倾销鸦片毒害人民。1839年林则徐到广州禁烟，收缴英美商人鸦片二百多万斤，在虎门海滩当众销毁，史称虎门销烟。虎门销烟显示了中华民族禁烟的决心，林则徐是民族英雄。' },
    { category: '中国历史', title: '甲午中日战争', content: '1894年日本挑起甲午中日战争。清军在平壤黄海战役中战败，北洋水师在威海卫全军覆没。1895年清政府被迫签订马关条约，割让辽东半岛台湾澎湖给日本赔巨款。甲午战败使中国民族危机加深。' },
    { category: '中国历史', title: '戊戌变法', content: '1898年光绪帝任用康有为梁启超谭嗣同等推行变法，史称戊戌变法或百日维新。变法涉及政治经济教育军事。但变法触犯守旧派利益，慈禧太后发动政变囚禁光绪，杀害谭嗣同等六君子，变法失败。' },
    { category: '中国历史', title: '五四运动', content: '1919年巴黎和会上中国外交失败，列强把德国在山东特权转给日本。5月4日北京学生游行示威高呼外争主权内除国贼，运动迅速扩展到全国。五四运动是反帝反封建的爱国运动，促进了马克思主义传播。' },
    { category: '中国历史', title: '中华人民共和国成立', content: '1949年10月1日毛泽东在天安门城楼庄严宣告中华人民共和国中央人民政府成立。新中国成立结束了半殖民地半封建社会，中国人民从此站起来了。10月1日被定为国庆节，每年全国欢庆。' },
    // ---- 世界地理 ----
    { category: '世界地理', title: '七大洲', content: '地球陆地分为七大洲：亚洲面积最大，非洲第二，北美洲第三，南美洲第四，南极洲第五，欧洲第六，大洋洲最小。亚洲和欧洲连在一起叫亚欧大陆。大洋洲是最年轻的洲，南极洲最冷没有常住人口。' },
    { category: '世界地理', title: '四大洋', content: '地球有四大洋：太平洋最大最深，约占海洋面积一半；大西洋第二大呈S形；印度洋第三，位于亚洲非洲大洋洲南极洲之间；北冰洋最小最浅最冷，大部分在北极圈内被冰雪覆盖。' },
    { category: '世界地理', title: '喜马拉雅山脉', content: '喜马拉雅山脉位于青藏高原南缘，是世界最高的山脉。珠穆朗玛峰海拔8848.86米是世界第一高峰。喜马拉雅山脉由印度板块向北挤压亚欧板块隆起形成，至今仍在缓慢升高，被称为世界屋脊。' },
    { category: '世界地理', title: '撒哈拉沙漠', content: '撒哈拉沙漠位于非洲北部，是世界最大的热带沙漠，面积约九百万平方公里。撒哈拉气候炎热干燥昼夜温差大，年降水量极少。沙漠中有绿洲，骆驼是重要交通工具。撒哈拉下面储藏丰富石油。' },
    { category: '世界地理', title: '亚马孙河', content: '亚马孙河位于南美洲，是世界流量最大流域面积最广的河流，全长约六千四百公里。亚马孙河流域有世界最大的热带雨林，被称为地球之肺，动植物种类极其丰富。亚马孙河注入大西洋。' },
    { category: '世界地理', title: '尼罗河', content: '尼罗河位于非洲东北部，是世界第一长河，全长约六千六百公里，自南向北流入地中海。尼罗河定期泛滥给两岸带来肥沃泥土，孕育了古埃及文明。古埃及人称尼罗河是母亲河，赞颂它的恩赐。' },
    { category: '世界地理', title: '马里亚纳海沟', content: '马里亚纳海沟位于太平洋西部，是世界最深的海沟，最深处约一万一千米。如果把珠穆朗玛峰放进去顶端还在水面以下两千米。海沟深处水压极大漆黑冰冷，但仍发现了一些奇特生物。' },
    { category: '世界地理', title: '赤道', content: '赤道是地球表面距离南北两极相等的圆周线，是最大的纬线圈，长约四万公里。赤道把地球分为南北两个半球。赤道地区终年炎热没有四季变化，全年都是夏天。赤道经过南美洲非洲和东南亚。' },
    { category: '世界地理', title: '南极洲', content: '南极洲位于地球最南端，被南极圈包围。南极洲终年冰雪覆盖是世界上最冷的大陆，最低气温达零下八十多度。南极洲没有常住居民，只有各国科考队。这里有丰富的磷虾和企鹅海豹等动物。' },
    { category: '世界地理', title: '北极地区', content: '北极地区主要是北冰洋，被亚欧北美三大洲包围。北极大部分是海洋覆盖着浮冰。北极有北极熊北极狐海象等特有动物。因纽特人世代生活在北极地区。北极有极昼极夜现象，能看到美丽的极光。' },
    { category: '世界地理', title: '东非大裂谷', content: '东非大裂谷位于非洲东部，是世界大陆上最大的裂谷带，被称为地球的伤疤。它南起赞比亚河口北至死海，全长六千多公里。大裂谷底部有众多湖泊火山，是研究地球板块运动的天然实验室。' },
    { category: '世界地理', title: '死海', content: '死海位于以色列约旦巴勒斯坦交界处，是世界陆地最低点，湖面低于海平面约四百三十米。死海湖水含盐量极高是一般海水的八九倍，人躺在水上不会沉。死海里没有鱼虾所以叫死海，但有疗养价值。' },
    { category: '世界地理', title: '乞力马扎罗山', content: '乞力马扎罗山位于坦桑尼亚，是非洲最高峰，海拔五千八百九十五米。虽然位于赤道附近，山顶却终年积雪，被称为赤道雪山。乞力马扎罗山是休眠火山，由于全球变暖山顶冰雪正在减少。' },
    { category: '世界地理', title: '亚马逊雨林', content: '亚马逊热带雨林位于南美洲亚马逊河流域，是世界最大的热带雨林，占全球雨林面积一半。雨林动植物种类占地球十分之一，被称为世界动植物王国和地球之肺。它吸收二氧化碳释放氧气调节气候。' },
    { category: '世界地理', title: '贝加尔湖', content: '贝加尔湖位于俄罗斯西伯利亚南部，是世界最深和蓄水量最大的淡水湖。最深处一千六百多米，湖水占全球淡水五分之一。贝加尔湖历史悠久有两千多万年，湖中有许多特有生物如贝加尔海豹。' },
    { category: '世界地理', title: '大堡礁', content: '大堡礁位于澳大利亚东北海岸，是世界最大的珊瑚礁群，绵延两千多公里。大堡礁由数十亿珊瑚虫分泌的石灰质堆积而成，色彩斑斓美不胜收。这里海洋生物丰富，是世界著名的旅游和潜水胜地。' },
    { category: '世界地理', title: '科罗拉多大峡谷', content: '科罗拉多大峡谷位于美国亚利桑那州，是科罗拉多河经数百万年冲刻而成的巨大峡谷。峡谷长约四百多公里，最深处一千八百米。峡谷两侧岩壁呈红褐色层次分明，记录了地球十几亿年的地质历史。' },
    { category: '世界地理', title: '维多利亚瀑布', content: '维多利亚瀑布位于非洲赞比西河上，在赞比亚和津巴布韦交界处。瀑布宽约一千七百米落差一百多米，是世界最宽的瀑布之一。瀑布激起的水雾高达数百米，当地人称它为莫西奥图尼亚即雷霆之雾。' },
    { category: '世界地理', title: '阿尔卑斯山', content: '阿尔卑斯山位于欧洲中南部，是欧洲最高大的山脉，横跨多个国家。勃朗峰是最高峰海拔四千八百多米。阿尔卑斯山风景秀丽是著名的滑雪胜地。山顶终年积雪山间有美丽湖泊和草地，是旅游胜地。' },
    { category: '世界地理', title: '安第斯山脉', content: '安第斯山脉位于南美洲西岸，是世界最长的山脉，全长约八千九百公里，纵贯多个国家。阿空加瓜山是最高峰海拔近七千米。安第斯山脉是印加文明的发祥地，山中有丰富的矿产资源如铜矿银矿。' },
    { category: '世界地理', title: '好望角', content: '好望角位于非洲南非共和国西南端，是大西洋和印度洋的分界处。1488年葡萄牙航海家迪亚士首次到达这里。好望角风浪很大，是航海险地，但也是从欧洲到亚洲的海上要道，战略位置重要。' },
    { category: '世界地理', title: '红海', content: '红海位于非洲东北部和阿拉伯半岛之间，是连接地中海和印度洋的重要通道。红海海水呈蓝绿色，因有时红藻繁殖使海水变红得名。红海盐度很高是世界上最咸的海之一，海底有奇特的热泉。' },
    { category: '世界地理', title: '里海', content: '里海位于亚欧大陆交界处，是世界最大的湖泊。虽然是湖但面积大像海所以叫海。里海是咸水湖，储藏丰富的石油和天然气。里海周边有俄罗斯哈萨克斯坦等多个国家，盛产鲟鱼鱼子酱。' },
    { category: '世界地理', title: '格陵兰岛', content: '格陵兰岛位于北美洲东北，是世界最大的岛屿，面积约二百一十六万平方公里。格陵兰岛大部分在北极圈内，终年冰雪覆盖。它属于丹麦但享有自治。因纽特人世代生活在这里，靠捕鱼狩猎为生。' },
    { category: '世界地理', title: '板块构造', content: '地球表面由六大板块组成：亚欧板块非洲板块美洲板块太平洋板块印度洋板块南极洲板块。板块在地幔上缓慢移动，相互碰撞挤压形成山脉海沟地震火山。喜马拉雅山就是板块碰撞形成的。' },
    { category: '世界地理', title: '时区', content: '地球自转一周二十四小时，为方便计时把地球分为二十四个时区，每个时区相差一小时。以本初子午线为零时区，向东向西各分十二时区。国际日期变更线大致沿一百八十度经线，过线日期变一天。' },
    { category: '世界地理', title: '洋流', content: '海洋中海水大规模定向流动叫洋流。暖流从低纬流向高纬带来温暖，寒流从高纬流向低纬带来凉爽。墨西哥湾暖流使欧洲西部温暖湿润。洋流影响沿岸气候，还带来丰富饵料形成大渔场。' },
    { category: '世界地理', title: '火山', content: '火山是地球内部岩浆喷出地表形成的。地壳下岩浆在高温高压下顺着裂隙喷出，带来熔岩火山灰等。火山分活火山休眠火山死火山。维苏威火山曾埋没庞贝城。火山灰肥沃适合种庄稼。' },
    // ---- 科学知识 ----
    { category: '科学知识', title: '太阳系', content: '太阳系由太阳和围绕它运转的行星组成。太阳是恒星，周围有八大行星：水星金星地球火星木星土星天王星海王星。地球是第三颗行星。行星都沿椭圆轨道绕太阳转，太阳引力是它们运转的动力。' },
    { category: '科学知识', title: '地球', content: '地球是太阳系第三颗行星，是已知唯一有生命的星球。地球是个两极稍扁赤道略鼓的椭球体，表面积约五点一亿平方公里。地球表面百分之七十一是海洋。地球有大气层磁场保护，温度适宜存在液态水。' },
    { category: '科学知识', title: '月球', content: '月球是地球唯一的天然卫星，距地球约三十八万公里。月球自转和公转周期相同，所以我们总看到同一面。月球表面有环形山和月海，没有空气和水。月球引力引起潮汐。1969年人类首次登上月球。' },
    { category: '科学知识', title: '日食月食', content: '日食是月球转到太阳和地球之间挡住太阳光形成。日食发生在农历初一。月食是地球转到太阳和月球之间挡住太阳光形成，月食发生在农历十五。日食分日全食日偏食日环食，月食分月全食月偏食。' },
    { category: '科学知识', title: '万有引力', content: '万有引力是任何两个物体之间都存在的吸引力，由牛顿发现。质量越大距离越近引力越大。地球引力使苹果落地也使月球绕地球转。重力就是地球对物体的引力。万有引力定律是物理学基本定律。' },
    { category: '科学知识', title: '相对论', content: '相对论是爱因斯坦提出的物理理论。狭义相对论指出光速不变，运动会使时间变慢长度变短。广义相对论指出引力是时空弯曲造成的。相对论改变了人们对时空的认识，是现代物理学两大支柱之一。' },
    { category: '科学知识', title: '原子', content: '原子是组成物质的基本微粒。原子由带正电的原子核和带负电的电子组成，原子核由质子和中子组成。原子很小，一亿个原子排成一行才约一厘米。不同原子组合成各种分子构成万物。' },
    { category: '科学知识', title: '元素周期表', content: '元素周期表是俄国化学家门捷列夫创立的，把元素按原子序数排列。周期表有七个周期十八个族。同族元素性质相似。目前发现一百多种元素，其中九十多种是天然存在的。元素周期表是化学的基础工具。' },
    { category: '科学知识', title: 'DNA', content: 'DNA是脱氧核糖核酸，是储存遗传信息的物质。DNA呈双螺旋结构，像扭曲的梯子。DNA上有基因，基因决定生物的性状。DNA能复制把遗传信息传给下一代。沃森和克里克发现了DNA双螺旋结构。' },
    { category: '科学知识', title: '细胞', content: '细胞是生物体结构和功能的基本单位。细胞分原核细胞和真核细胞。真核细胞有细胞膜细胞质细胞核，植物细胞还有细胞壁和叶绿体。细胞通过分裂繁殖。人体有约三十七万亿个细胞，各有不同功能。' },
    { category: '科学知识', title: '光合作用', content: '光合作用是植物用阳光二氧化碳和水制造有机物释放氧气的过程。叶绿体吸收光能，把水和二氧化碳合成葡萄糖放出氧气。光合作用是地球上氧气的主要来源，也是食物链的基础，对维持生态平衡至关重要。' },
    { category: '科学知识', title: '进化论', content: '进化论是达尔文提出的生物演化理论。达尔文认为生物在自然选择下，适应环境的个体更容易生存繁殖，把有利性状遗传下去，物种逐渐演化。达尔文在物种起源一书中系统阐述了进化论，改变了人们对生命的认识。' },
    { category: '科学知识', title: '光的折射', content: '光从一种介质进入另一种介质时方向会改变，这叫折射。折射是因为光在不同介质中速度不同。把筷子插进水里看起来弯了就是折射。透镜就是利用折射原理制成的，眼镜放大镜显微镜都用到折射。' },
    { category: '科学知识', title: '声音的传播', content: '声音由物体振动产生，以波的形式传播。声音传播需要介质，固体液体气体都能传声，真空不能传声。声音在固体中传播最快，气体中最慢。声音在空气中速度约每秒三百四十米。回声是声音反射形成的。' },
    { category: '科学知识', title: '电', content: '电是电荷运动产生的现象。电有正负两种电荷，同种相斥异种相吸。电流是电荷定向移动形成的。电通过导线传输，可以转化成光热机械能。发电机把机械能转成电能。要注意用电安全防止触电。' },
    { category: '科学知识', title: '磁', content: '磁体有南北两极，同名极相斥异名极相吸。地球本身是个大磁体，指南针就是利用地磁指示方向。电流可以产生磁场叫电磁铁。磁和电密切相关，发电机和电动机都利用电磁原理工作。' },
    { category: '科学知识', title: '能量守恒', content: '能量守恒定律指出能量既不会凭空产生也不会消失，只能从一种形式转化成另一种形式。比如电灯把电能转成光能和热能，水力发电把水的势能转成电能。能量守恒是自然界最基本的定律之一。' },
    { category: '科学知识', title: '三态变化', content: '物质有固态液态气态三种状态，会相互转化。冰融化成水是熔化，水变水蒸气是汽化，水蒸气变水是液化，水变冰是凝固。还有升华和凝华直接在固气间转化。这些变化伴随吸热放热，云雨雪就是水的三态变化。' },
    { category: '科学知识', title: '浮力', content: '浸在液体或气体中的物体会受到向上的浮力。阿基米德原理指出浮力等于物体排开液体的重量。物体密度小于液体就漂浮，大于就下沉。轮船用钢铁做但做成空心所以能浮。潜水艇靠改变自身重量上浮下沉。' },
    { category: '科学知识', title: '杠杆原理', content: '杠杆是可以绕固定点转动的硬棒。杠杆有支点动力阻力。动力乘动力臂等于阻力乘阻力臂是杠杆原理。杠杆分省力杠杆费距离如撬棍，费力杠杆省距离如镊子，等臂杠杆如天平。阿基米德说给他支点能撬动地球。' },
    { category: '科学知识', title: '大气压', content: '大气压是空气重量产生的压强。大气压无处不在。马德堡半球实验证明大气压很大。标准大气压约一百零一千帕，能支持七十六厘米高水银柱。大气压随高度增加而减小。吸盘吸饮料都利用大气压。' },
    { category: '科学知识', title: '摩擦力', content: '两个接触的物体相对运动时产生的阻碍力叫摩擦力。摩擦力有利有弊。走路靠摩擦力，刹车也靠摩擦力，这是有益的。机器运转摩擦生热磨损是有害的，要加润滑油减小。增大摩擦可增大压力或使表面粗糙。' },
    { category: '科学知识', title: '惯性', content: '惯性是物体保持原来运动状态的性质。一切物体都有惯性。车突然停下人会前倾就是惯性。系安全带能减小惯性伤害。质量越大惯性越大，所以大卡车刹车比小车难。惯性是牛顿第一定律的内容。' },
    { category: '科学知识', title: '彩虹', content: '雨后天空中常出现七彩彩虹。阳光由七种颜色组成：红橙黄绿青蓝紫。阳光照射空中的小水滴，发生折射和反射，不同颜色光偏折不同就分散成七色光，形成彩虹。彩虹总是出现在太阳的对面。' },
    { category: '科学知识', title: '雷电', content: '雷电是云层中电荷放电产生的。云中冰晶摩擦产生电荷，电荷积累到一定程度就放电形成闪电。闪电温度极高使空气急剧膨胀产生雷声。光速比声速快所以先看到闪电后听到雷声。雷雨时不要在树下避雨。' },
    { category: '科学知识', title: '温室效应', content: '温室效应是大气中二氧化碳等气体吸收地面辐射的热量，使地球温度升高的现象。适度的温室效应使地球温暖适合生命。但人类排放过多二氧化碳加剧温室效应导致全球变暖，冰川融化海平面上升气候异常。' },
    { category: '科学知识', title: '臭氧层', content: '臭氧层是大气平流层中的臭氧聚集层，能吸收大部分太阳紫外线保护地球生物。氟利昂等物质会破坏臭氧层形成臭氧空洞。紫外线过多会伤害皮肤眼睛导致疾病。保护臭氧层要减少使用破坏臭氧的物质。' },
    { category: '科学知识', title: '黑洞', content: '黑洞是宇宙中引力极强的天体，连光都无法逃脱。黑洞由大质量恒星耗尽燃料后坍缩形成。黑洞看不见只能通过它对周围物质的影响来观测。黑洞中心是奇点密度无限大。霍金对黑洞理论有重要贡献。' },
    { category: '科学知识', title: '银河系', content: '银河系是太阳所在的星系，是个旋涡星系。银河系有数千亿颗恒星，太阳只是其中普通一颗。银河系呈盘状中间厚边缘薄，直径约十万光年。晴朗夜空看到的银河是银河系的一部分。太阳在银河系一旋臂上。' },
    { category: '科学知识', title: '光年', content: '光年是天文学中常用的距离单位，是光在真空中一年走过的距离，约九点四六万亿公里。用光年是因为天体距离太远用公里数字太大不方便。离太阳最近的恒星比邻星约四点二光年。我们看到的星光是多年前发出的。' },
    { category: '科学知识', title: '火山地震带', content: '火山和地震多分布在板块交界处。环太平洋火山地震带是最活跃的地带，集中了大部分火山地震。地中海喜马拉雅地震带也很活跃。板块碰撞挤压释放能量引起地震，岩浆沿裂隙喷出形成火山。' },
    { category: '科学知识', title: '生态系统', content: '生态系统是生物和环境组成的整体。生态系统中有生产者植物消费者动物分解者微生物。能量沿食物链流动，物质循环利用。生态系统有一定自我调节能力，但破坏超过限度就会失衡。保护生态要维护平衡。' },
    { category: '科学知识', title: '食物链', content: '食物链是生物之间吃与被吃的关系。如草被兔吃兔被狼吃。食物链从生产者植物开始，到顶级消费者结束。能量沿食物链传递逐级递减，所以顶级消费者数量最少。食物链交织成食物网，维护生态平衡。' },
    { category: '科学知识', title: '微生物', content: '微生物是肉眼看不见的微小生物，包括细菌病毒真菌等。微生物无处不在。有的有益如肠道菌帮助消化酵母菌发酵，有的有害如致病菌病毒使人得病。微生物在自然界物质循环中起重要作用分解动植物遗体。' },
    { category: '科学知识', title: '疫苗', content: '疫苗是用减毒或灭活的病原体制成的生物制品。打疫苗后身体产生抗体获得免疫力，就能预防相应疾病。天花就是靠疫苗消灭的。疫苗是人类对抗传染病的重要武器，要按时接种疫苗保护健康。' },
    { category: '科学知识', title: '基因', content: '基因是DNA上有遗传功能的片段，决定生物的性状如眼睛颜色血型等。基因通过复制把性状遗传给后代。父母各提供一半基因给孩子，所以孩子像父母。基因突变可能产生新性状是进化的基础。' },
    { category: '科学知识', title: '血液', content: '血液在血管中流动运送物质。血液由血浆和血细胞组成。红细胞运氧气，白细胞免疫，血小板止血。血型有A型B型AB型O型。输血要同型输血。心脏像泵推动血液在全身循环，给细胞送氧气营养带走废物。' },
    { category: '科学知识', title: '神经系统', content: '神经系统由脑脊髓和神经组成，是人体的指挥中心。脑分大脑小脑脑干，大脑管思维和感觉，小脑管平衡，脑干管呼吸心跳。神经传递信号速度很快。脊髓是神经的通道，反射活动通过脊髓完成。' },
    // ---- 文学常识 ----
    { category: '文学常识', title: '唐诗', content: '唐诗是中国古典诗歌的高峰。唐代诗人众多作品丰富，李白杜甫白居易最著名。李白被称为诗仙，风格豪放飘逸；杜甫被称为诗圣，风格沉郁顿挫；白居易被称为诗魔，诗通俗易懂。唐诗是中华文化的瑰宝。' },
    { category: '文学常识', title: '李白', content: '李白字太白号青莲居士，是唐代最伟大的浪漫主义诗人，被誉为诗仙。他性格豪放喜欢饮酒游历。代表作有静夜思望庐山瀑布将进酒等。他的诗想象丰富气势磅礴，充分体现了盛唐精神，深受后人喜爱。' },
    { category: '文学常识', title: '杜甫', content: '杜甫字子美号少陵野老，是唐代伟大的现实主义诗人，被誉为诗圣。他的诗反映社会现实和人民疾苦，被称为诗史。代表作有三吏三别春望茅屋为秋风所破歌等。杜甫忧国忧民，与李白并称李杜。' },
    { category: '文学常识', title: '白居易', content: '白居易字乐天号香山居士，是唐代著名诗人。他主张文章合为时而著歌诗合为事而作。代表作有长恨歌琵琶行赋得古原草送别等。他的诗语言通俗据说老妪能解，流传很广，被称为诗魔。' },
    { category: '文学常识', title: '宋词', content: '宋词是宋代文学的代表，是配乐歌唱的诗体。词有词牌名规定格式。宋词分婉约派和豪放派。婉约派代表柳永李清照，词风细腻柔美。豪放派代表苏轼辛弃疾，词风雄浑豪迈。宋词与唐诗并称双绝。' },
    { category: '文学常识', title: '苏轼', content: '苏轼字子瞻号东坡居士，北宋大文学家书画家。他是豪放派词的代表，诗词文书画都精通。代表作有念奴娇赤壁怀古水调歌头题西林壁等。他性格豁达屡遭贬谪仍乐观，是中国文人的典范。' },
    { category: '文学常识', title: '李清照', content: '李清照号易安居士，宋代女词人，是婉约派代表。前期词写少女少妇生活清新活泼，后期词写国破家亡之痛凄凉悲切。代表作有如梦令声声慢等。她被誉为千古第一才女，在词坛有重要地位。' },
    { category: '文学常识', title: '四大名著', content: '中国四大古典名著是三国演义水浒传西游记红楼梦。三国演义罗贯中作写三国历史，水浒传施耐庵作写农民起义，西游记吴承恩作写神话故事，红楼梦曹雪芹作写家族兴衰。四大名著是中华文学经典。' },
    { category: '文学常识', title: '三国演义', content: '三国演义是元末明初罗贯中所作的长篇历史小说，描写东汉末年到西晋初年的风云变幻。塑造了诸葛亮关羽曹操等众多鲜明人物。小说尊刘贬曹，反映了忠义思想。三国演义是历史演义小说的开山之作。' },
    { category: '文学常识', title: '水浒传', content: '水浒传是元末明初施耐庵所作的长篇小说，描写北宋末年宋江等一百零八位好汉聚义梁山泊的故事。塑造了武松林冲鲁智深等英雄形象，反映了官逼民反的主题。水浒传是中国英雄传奇小说的代表作。' },
    { category: '文学常识', title: '西游记', content: '西游记是明代吴承恩所作的神魔小说，描写唐僧师徒四人去西天取经的故事。孙悟空猪八戒沙僧保护唐僧历经九九八十一难终于取得真经。小说想象奇特人物生动，是中国浪漫主义文学的高峰。' },
    { category: '文学常识', title: '红楼梦', content: '红楼梦是清代曹雪芹所作的长篇小说，是中国古典小说的最高成就。小说以贾宝玉林黛玉薛宝钗的爱情婚姻悲剧为主线，描写贾府由盛到衰。红楼梦人物众多描写细腻思想深刻，是中国封建社会的百科全书。' },
    { category: '文学常识', title: '论语', content: '论语是记录孔子及其弟子言行的语录体散文集，由孔子弟子整理。论语共二十篇，内容涉及修身治国学习等。有朋自远方来不亦乐乎，三人行必有我师等名句都出自论语。论语是儒家经典，影响深远。' },
    { category: '文学常识', title: '史记', content: '史记是西汉司马迁所著的纪传体通史，记载了从黄帝到汉武帝约三千年的历史。史记分本纪世家列传书表五部分。史记既是史学巨著又是文学名著，人物描写生动。鲁迅誉为史家之绝唱无韵之离骚。' },
    { category: '文学常识', title: '离骚', content: '离骚是战国楚国诗人屈原的长篇政治抒情诗，是中国浪漫主义文学的源头。离骚表达了屈原忧国忧民的爱国情怀和不与世俗同流的高洁品格。路漫漫其修远兮吾将上下而求索是其中名句。屈原是爱国诗人。' },
    { category: '文学常识', title: '诗经', content: '诗经是中国最早的诗歌总集，收录西周到春秋诗歌三百零五篇，又称诗三百。诗经分风雅颂三部分，风是民歌最有价值。诗经多四言句，常用赋比兴手法。关关雎鸠在河之洲就出自诗经。诗经是现实主义源头。' },
    { category: '文学常识', title: '楚辞', content: '楚辞是战国时期楚国诗歌体裁，以屈原作品为代表。楚辞运用楚地方言语调和神话，句式灵活多用兮字，富有浪漫色彩。屈原的离骚是楚辞代表作。楚辞与诗经并称风骚，是中国诗歌的两大源头。' },
    { category: '文学常识', title: '唐宋八大家', content: '唐宋八大家是唐宋两代八位散文大家的合称：唐代韩愈柳宗元，宋代欧阳修苏洵苏轼苏辙王安石曾巩。他们倡导古文运动，反对骈文提倡散文。韩愈是古文运动领袖，他们的散文成就极高影响后世。' },
    { category: '文学常识', title: '寓言', content: '寓言是用比喻故事说明道理的文学体裁，篇幅短小寓意深刻。中国著名寓言有揠苗助长守株待兔刻舟求剑等，多出自先秦诸子。希腊有伊索寓言如龟兔赛跑狼来了。寓言通过故事教育人，浅显易懂又发人深省。' },
    { category: '文学常识', title: '童话', content: '童话是富有幻想色彩的儿童文学体裁，通过想象和夸张塑造形象。丹麦安徒生是童话大师，代表作有卖火柴的小女孩丑小鸭海的女儿等。德国格林童话也很有名如白雪公主灰姑娘。童话培养孩子想象力和美好品格。' },
    { category: '文学常识', title: '神话', content: '神话是远古人类对自然现象的解释和想象的故事。中国神话有盘古开天女娲补天后羿射日嫦娥奔月等，反映先民征服自然的愿望。希腊神话有宙斯雅典娜等众神。神话是文学的源头充满浪漫想象。' },
    { category: '文学常识', title: '王维', content: '王维字摩诘，唐代著名诗人画家，被称为诗佛。他擅长山水田园诗，诗中有画画中有诗。代表作有鹿柴山居秋暝九月九日忆山东兄弟等。王维晚年信佛，诗中常带禅意，与孟浩然并称王孟。' },
    { category: '文学常识', title: '辛弃疾', content: '辛弃疾字幼安号稼轩，南宋豪放派词人。他既是词人又是爱国将领，一生力主抗金收复失地。代表作有破阵子青玉案菩萨蛮等。他的词慷慨悲壮充满爱国热情，与苏轼并称苏辛，是豪放词的代表。' },
    { category: '文学常识', title: '陆游', content: '陆游字务观号放翁，南宋伟大的爱国诗人。他一生渴望收复中原，留下近万首诗。代表作有示儿秋夜将晓出篱门迎凉有感十一月四日风雨大作等。他临终还嘱告王师北定中原日家祭无忘告乃翁，爱国之心感人。' },
    { category: '文学常识', title: '孟浩然', content: '孟浩然唐代诗人，是山水田园诗派代表，与王维并称王孟。他一生未做官，隐居山林。代表作有春晓过故人庄宿建德江等。他的诗清淡自然写景如画，春眠不觉晓处处闻啼鸟是千古名句，妇孺皆知。' },
    { category: '文学常识', title: '韩愈', content: '韩愈字退之，唐代文学家思想家，是古文运动的倡导者，唐宋八大家之首。他反对形式华丽的骈文，提倡内容充实的散文。代表作有师说马说等。师说中提出师者所以传道授业解惑也，影响深远。' },
    { category: '文学常识', title: '柳宗元', content: '柳宗元字子厚，唐代文学家，唐宋八大家之一，与韩愈并称韩柳。他参与政治改革失败被贬，写下永州八记等山水游记。他还写了许多寓言如黔之驴捕蛇者说，借事说理深刻。柳宗元散文成就很高。' },
    { category: '文学常识', title: '欧阳修', content: '欧阳修字永叔号醉翁，北宋文学家史学家，唐宋八大家之一。他是北宋诗文革新运动的领袖，提携了苏轼等人。代表作有醉翁亭记卖油翁等。醉翁之意不在酒在乎山水之间也是名句。欧阳修文风平易自然。' },
    { category: '文学常识', title: '王安石', content: '王安石字介甫号半山，北宋政治家文学家，唐宋八大家之一。他推行王安石变法图强。文学上诗文明快有力，代表作有伤仲永登飞来峰泊船瓜洲等。春风又绿江南岸明月何时照还就是泊船瓜洲中的名句。' },
    { category: '文学常识', title: '曹雪芹', content: '曹雪芹名霑字梦阮，清代小说家，红楼梦作者。他出身贵族后家道中落，饱尝世态炎凉，在贫困中呕心沥血写红楼梦。红楼梦以其博大精深成为不朽名著。可惜曹雪芹未写完全书就去世，后四十回由高鹗续写。' },
    { category: '文学常识', title: '蒲松龄', content: '蒲松龄字留仙号柳泉居士，清代文学家。他屡试不第，在乡间教书，收集民间故事写成聊斋志异。聊斋志异借花妖狐魅的故事揭露社会黑暗，想象奇特文笔优美。郭沫若评他写鬼写妖高人一等。' },
    { category: '文学常识', title: '乐府诗', content: '乐府诗是汉代乐府机关收集的诗歌。乐府诗多反映社会现实，形式自由。代表作有陌上桑长歌行等。长歌行中少壮不努力老大徒伤悲是劝人珍惜时间的名句。乐府诗对后世诗歌发展有重要影响。' },
    { category: '文学常识', title: '三字经', content: '三字经相传为南宋王应麟所作，是古代蒙学读物。三字一句朗朗上口，内容涵盖历史伦理天文地理等。人之初性本善是开篇名句。三字经与百家姓千字文并称三百千，是古代儿童启蒙必读书，影响深远。' },
    { category: '文学常识', title: '百家姓', content: '百家姓是古代蒙学读物，收集常见姓氏编成四言韵文。赵钱孙李开篇，因为宋代皇帝姓赵所以赵排第一。百家姓便于儿童识字和了解姓氏。中国姓氏源远流长，许多姓氏都有有趣来源，是中华文化的一部分。' },
    { category: '文学常识', title: '千字文', content: '千字文是南朝周兴嗣编写的蒙学读物，由一千个不重复的汉字组成四言韵文。天地玄黄宇宙洪荒是开篇。千字文内容丰富包括天文地理历史伦理等。相传周兴嗣一夜编成头发都白了，可见用心之苦。' },
    { category: '文学常识', title: '成语', content: '成语是人们长期习用的固定词组，多由四个字组成。成语多来源于神话寓言历史故事和古诗文名句。如画蛇添足来自寓言，破釜沉舟来自历史故事。成语简洁精辟富有表现力，是汉语的精华，用好成语能提高表达水平。' },
    { category: '文学常识', title: '对联', content: '对联又称对子，是由上下两联组成的对偶语句。对联要求字数相等词性相对平仄相调。春联是过年贴的对联。对联讲究对仗工整意境优美。对联常用于节日庆典名胜古迹，是中华特有的文学形式。' },
    { category: '文学常识', title: '伊索寓言', content: '伊索寓言是古希腊寓言集，相传为奴隶伊索所作。故事多以动物为主人公，简短生动寓意深刻。著名的有龟兔赛跑狼来了农夫与蛇乌鸦喝水等。伊索寓言通过小故事讲大道理，是世界文学瑰宝，深受孩子喜爱。' },
    // ---- 艺术文化 ----
    { category: '艺术文化', title: '书法', content: '书法是中国特有的艺术，用毛笔书写汉字。书法有篆书隶书楷书行书草书等字体。王羲之是书圣，他的兰亭序被誉为天下第一行书。书法讲究笔法结构和神韵，既能写字又能修身养性，是中华文化的瑰宝。' },
    { category: '艺术文化', title: '王羲之', content: '王羲之字逸少，东晋大书法家，被尊为书圣。他博采众长自成一家，擅长楷行草书。代表作兰亭序被誉为天下第一行书。传说他练字洗笔把池水都染黑了，可见用功之深。他的书法影响中国书法一千多年。' },
    { category: '艺术文化', title: '国画', content: '国画是中国传统绘画，用毛笔墨彩在宣纸上作画。国画分山水花鸟人物等科。国画讲究意境和笔墨，重神似不重形似。著名画家有顾恺之吴道子齐白石徐悲鸿等。齐白石画虾徐悲鸿画马都十分传神。' },
    { category: '艺术文化', title: '齐白石', content: '齐白石是近现代国画大师。他出身贫寒自学成才，擅画花鸟虫鱼。他画的虾最为著名，寥寥数笔就把虾的透明灵动表现得栩栩如生。齐白石主张作画妙在似与不似之间。他九十多岁仍坚持作画，艺术生命很长。' },
    { category: '艺术文化', title: '徐悲鸿', content: '徐悲鸿是现代著名画家美术教育家。他擅长画马，笔下的奔马气势磅礴神骏非凡，激励人心。他主张改良中国画，融中西画法。代表作有奔马图愚公移山等。徐悲鸿曾任中央美院院长，培养了许多美术人才。' },
    { category: '艺术文化', title: '京剧', content: '京剧是中国国粹，有近二百年历史。京剧分生旦净丑四个行当，生是男角旦是女角净是花脸丑是丑角。京剧表演讲究唱念做打，脸谱用颜色表现人物性格。京剧是综合性艺术，被列为世界非物质文化遗产。' },
    { category: '艺术文化', title: '梅兰芳', content: '梅兰芳是京剧艺术大师，擅长旦角。他创立了梅派艺术，代表作有贵妃醉酒霸王别姬天女散花等。梅兰芳扮相美唱腔美表演美。抗战时他蓄须明志拒绝为日寇演出，气节高尚。梅兰芳把京剧传播到世界。' },
    { category: '艺术文化', title: '古琴', content: '古琴是中国最古老的弹拨乐器之一，有三千多年历史。古琴有七根弦所以又叫七弦琴。古琴音色清幽高雅，是文人雅士修身养性的乐器。高山流水就是古琴名曲，讲伯牙子期知音的故事。古琴是世界非物质文化遗产。' },
    { category: '艺术文化', title: '二胡', content: '二胡是民族拉弦乐器，只有两根弦却表现力丰富。二胡音色柔美深沉善于抒情。阿炳的二泉映月是最著名的二胡曲，曲调哀婉动人。二胡可独奏可伴奏，是民族乐队的重要乐器，深受人们喜爱。' },
    { category: '艺术文化', title: '剪纸', content: '剪纸是中国民间艺术，用剪刀或刻刀在纸上剪刻图案。剪纸多用于节日装饰，窗花喜字最常见。剪纸题材有花鸟鱼虫人物故事等。北方剪纸粗犷豪放，南方剪纸细腻秀美。剪纸是世界非物质文化遗产。' },
    { category: '艺术文化', title: '皮影戏', content: '皮影戏是用兽皮剪成人物形象，在灯光照射下通过白色幕布表演的戏曲。皮影戏在民间流传很广，人物关节灵活能做各种动作。配以唱腔音乐讲述故事，生动有趣。皮影戏是世界非物质文化遗产，是古老的艺术。' },
    { category: '艺术文化', title: '陶瓷', content: '陶瓷是陶器和瓷器的总称。陶器用黏土烧制温度较低质地粗糙，瓷器用瓷土烧制温度高质地细腻。中国是瓷器故乡，景德镇是瓷都。唐三彩宋代五大名窑青花瓷都很有名。陶瓷是实用与艺术的结合，享誉世界。' },
    { category: '艺术文化', title: '青花瓷', content: '青花瓷是白底蓝花的瓷器，是景德镇名产。用含钴的颜料在瓷胎上画花纹，上釉烧成后呈现美丽蓝色。青花瓷始于唐代盛于明清，是中国瓷器代表。元青花鬼谷子下山图罐拍出天价。青花瓷清新淡雅深受喜爱。' },
    { category: '艺术文化', title: '敦煌莫高窟', content: '敦煌莫高窟在甘肃敦煌，是世界著名佛教艺术宝库。莫高窟始建于前秦，历经千年开凿，现有洞窟七百多个。窟内有精美壁画和彩塑，壁画总面积四万五千多平方米。飞天是敦煌艺术的标志。莫高窟是世界文化遗产。' },
    { category: '艺术文化', title: '兵马俑', content: '兵马俑是秦始皇陵的陪葬坑，在陕西西安。1974年发现，出土数千个真人大小的陶俑陶马。兵马俑排列成阵气势恢宏，每个陶俑面目表情各异栩栩如生。兵马俑被誉为世界第八大奇迹，展示了秦朝强大。' },
    { category: '艺术文化', title: '少林功夫', content: '少林功夫是少林寺僧人长期创造的武术体系，在河南嵩山少林寺传承。少林功夫包括拳术器械等多种套路，刚健有力。少林功夫是禅武合一，既强身又修心。少林寺有天下功夫出少林的美誉，享誉海内外。' },
    { category: '艺术文化', title: '民族乐器', content: '中国民族乐器丰富多样。吹管乐器有笛子箫唢呐，拉弦乐器有二胡板胡，弹拨乐器有古筝琵琶古琴，打击乐器有锣鼓。古筝曲渔舟唱晚琵琶曲十面埋伏都很著名。民族乐器音色独特，是中华音乐文化的瑰宝。' },
    { category: '艺术文化', title: '古筝', content: '古筝是民族弹拨乐器，有两千多年历史。古筝有二十一根弦，音色清脆悦耳表现力丰富。古筝既能演奏古典曲目如渔舟唱晚高山流水，也能演奏现代乐曲。古筝优雅动听，学习古筝能培养气质，深受人们喜爱。' },
    { category: '艺术文化', title: '茶文化', content: '中国是茶的故乡，茶文化源远流长。茶叶分绿茶红茶乌龙茶白茶黑茶黄茶等。绿茶不发酵如龙井，红茶全发酵如祁门红。喝茶能提神助消化。茶圣陆羽写茶经是世界上最早的茶书。茶道讲究和敬清寂，是中华文化的体现。' },
    // ---- 科技发明 ----
    { category: '科技发明', title: '造纸术', content: '造纸术是中国四大发明之一。东汉蔡伦改进造纸术，用树皮麻头破布鱼网造出便宜好用的纸，人称蔡侯纸。造纸术传到世界，取代了昂贵的丝绸和笨重的竹简，促进了文化传播，对人类文明贡献巨大。' },
    { category: '科技发明', title: '印刷术', content: '印刷术是中国四大发明之一。雕版印刷在唐代已很发达。北宋毕昇发明活字印刷术，用胶泥刻字烧硬排成版印刷，比雕版省时省料。印刷术使书籍大量复制成为可能，极大促进了知识传播和文化发展。' },
    { category: '科技发明', title: '火药', content: '火药是中国四大发明之一。古代炼丹家在炼丹时偶然发明了火药。唐末火药开始用于军事，宋代出现火药武器。火药传入欧洲后改变了战争方式，也用于开矿修路。火药的发明改变了世界历史进程。' },
    { category: '科技发明', title: '指南针', content: '指南针是中国四大发明之一。战国时发明司南用天然磁石制成。宋代用人工磁化制成指南针用于航海。指南针使航海不再迷路，促进了远洋航行。郑和下西洋哥伦布发现新大陆都依靠指南针指引方向。' },
    { category: '科技发明', title: '蔡伦', content: '蔡伦是东汉宦官，他改进了造纸术。他用树皮麻头破布旧鱼网等便宜材料造纸，造出的纸质地轻薄便于书写成本低，人称蔡侯纸。蔡伦的改进使纸得以普及，取代了竹简和缣帛，他因此被载入史册。' },
    { category: '科技发明', title: '毕昇', content: '毕昇是北宋平民发明家，他发明了活字印刷术。毕昇用胶泥刻字烧硬成字模，排版时把字模排进铁框刷墨印刷，印完拆下字模下次再用。活字印刷比雕版印刷灵活省料效率高，是印刷史的重大革命。' },
    { category: '科技发明', title: '张衡', content: '张衡是东汉科学家文学家。他制造了测定地震方向的候风地动仪，是世界上最早的地震仪。他还制造了演示天象的水运浑天仪，提出浑天说。张衡在数学文学上也有成就，被誉为中国古代最伟大的科学家之一。' },
    { category: '科技发明', title: '地动仪', content: '地动仪是东汉张衡发明的测定地震的仪器。地动仪外形像酒樽，四周有八条龙含着铜球，每条龙下方有蟾蜍张口承接。某方向发生地震，对应龙嘴张开铜球落入蟾蜍口中，就能知道地震方向。地动仪比欧洲早一千多年。' },
    { category: '科技发明', title: '祖冲之', content: '祖冲之是南北朝伟大数学家天文学家。他把圆周率精确到小数点后七位，即3.1415926到3.1415927之间，这一纪录保持近千年。他还编制大明历，测定一回归年365.2428天。祖冲之是世界级的科学家。' },
    { category: '科技发明', title: '圆周率', content: '圆周率是圆周长与直径的比值，用希腊字母π表示。π是无限不循环小数约3.14159。中国南北朝祖冲之把π算到小数点后七位领先世界千年。现在用计算机已算到万亿位。π在数学物理工程中广泛应用。' },
    { category: '科技发明', title: '李时珍', content: '李时珍是明代医学家药学家。他用二十七年实地考察遍尝百草，写成药物学巨著本草纲目。本草纲目记载药物一千八百多种方剂一万多个，插图精美。本草纲目被译成多国文字，被誉为东方药学巨典。' },
    { category: '科技发明', title: '本草纲目', content: '本草纲目是明代李时珍所著的药物学巨著。全书五十二卷记载药物一千八百九十二种方剂一万一千多个，附图一千多幅。本草纲目纠正了前人错误，系统总结了药物知识。它是中医药学的经典，被译成多国文字。' },
    { category: '科技发明', title: '沈括', content: '沈括是北宋科学家，他的梦溪笔谈被誉为中国科学史上的里程碑。沈括在数学天文地理地质等多方面有贡献，他发现地磁偏角比欧洲早四百多年，还研究石油命名。沈括博学多才，是中国古代杰出的科学家。' },
    { category: '科技发明', title: '都江堰', content: '都江堰是战国时期秦国李冰父子修建的水利工程，在四川岷江上。都江堰由鱼嘴飞沙堰宝瓶口组成，巧妙地分水排沙灌溉，使成都平原成为天府之国。都江堰两千多年仍在使用，是世界水利史上的奇迹。' },
    { category: '科技发明', title: '赵州桥', content: '赵州桥在河北赵县，由隋朝工匠李春设计建造。赵州桥是单孔石拱桥，跨度大无桥墩，大拱两端各有两个小拱减轻重量利于泄洪。赵州桥已一千四百多年仍坚固使用，是世界现存最早的敞肩石拱桥，展现了古人智慧。' },
    { category: '科技发明', title: '蒸汽机', content: '蒸汽机是英国瓦特改进发明的动力机器。蒸汽机利用蒸汽压力推动活塞运动，把热能转成机械能。蒸汽机推动了工业革命，使机器取代人力畜力，工厂大量出现。蒸汽机是人类动力革命的关键发明。' },
    { category: '科技发明', title: '电灯', content: '电灯是美国爱迪生发明的。爱迪生试验上千种材料，最终用碳化竹丝做灯丝发明了实用白炽灯，能亮上千小时。电灯取代了蜡烛油灯，使人类告别黑暗。爱迪生一生发明众多被誉为发明大王，他说明天需要百分之一的灵感。' },
    { category: '科技发明', title: '飞机', content: '飞机是美国莱特兄弟发明的。1903年莱特兄弟制造的飞机试飞成功，飞行十二秒五十九米，这是人类首次驾驶动力飞机飞行。飞机实现了人类飞翔的梦想，如今飞机已成为重要交通工具，连接世界各地。' },
    { category: '科技发明', title: '计算机', content: '计算机是20世纪最伟大的发明之一。1946年第一台电子计算机诞生。计算机经历了电子管晶体管集成电路到大规模集成电路的发展，体积越来越小速度越来越快。计算机和互联网改变了人们的生活和工作方式。' },
    { category: '中国历史', title: '玄奘西行', content: '唐朝高僧玄奘为求取佛经真义，从长安出发西行前往天竺即印度。他历时十七年行程数万里，带回了大量佛经。玄奘口述的西域见闻被整理成大唐西域记。玄奘西行促进了中外文化交流，西游记就是以他为原型创作的。' },
    { category: '世界地理', title: '喀斯特地貌', content: '喀斯特地貌是石灰岩被水溶蚀形成的地貌，以斯洛文尼亚喀斯特高原命名。中国桂林山水就是典型的喀斯特地貌，奇峰林立溶洞众多。石灰岩含碳酸钙，被含二氧化碳的水慢慢溶解，形成石林溶洞地下河等奇特景观。' },
    { category: '世界地理', title: '厄尔尼诺', content: '厄尔尼诺是太平洋赤道附近海水异常升温的现象，通常在圣诞节前后出现所以叫圣婴。厄尔尼诺会引起全球气候异常，有的地方暴雨洪涝有的地方干旱。它影响渔业农业，是重要的气候现象，科学家正努力预测它。' },
    { category: '科学知识', title: '重力', content: '重力是地球对物体的吸引力，方向竖直向下。重力使物体有重量，苹果落地水往低处流都是重力作用。重力大小和质量成正比。重力随高度增加而减小。月球重力是地球六分之一，所以在月球上人能跳得很高。' },
    { category: '科学知识', title: '反射', content: '反射是光碰到物体表面返回来的现象。光滑表面反射好如镜子，粗糙表面反射分散叫漫反射。我们能看到物体是因为物体反射的光进入眼睛。月亮本身不发光，我们看到的月光是月亮反射的太阳光。反射分镜面反射和漫反射。' },
    { category: '文学常识', title: '诸子百家', content: '诸子百家是春秋战国时期各种学派的统称。主要有儒家孔子孟子、道家老子庄子、法家韩非子、墨家墨子等。各家提出不同治国主张，互相辩论形成百家争鸣局面。诸子百家思想是中华文化的源头，影响深远，儒家影响最大。' },
    { category: '文学常识', title: '元曲', content: '元曲是元代文学的代表，包括散曲和杂剧。杂剧是戏曲，关汉卿白朴马致远郑光祖被称为元曲四大家。关汉卿的窦娥冤是最著名的杂剧。元曲语言通俗生动反映社会现实，与唐诗宋词并称中国文学三大高峰。' },
    { category: '艺术文化', title: '围棋', content: '围棋是中国传统棋类，有四千多年历史。围棋棋盘纵横各十九路，黑白两色棋子相互围攻。围棋变化无穷能锻炼思维培养大局观。传说尧帝为教育儿子发明围棋。围棋现已传播世界，是智力运动的重要组成部分。' },
    { category: '科技发明', title: '算盘', content: '算盘是中国古代的计算工具，被誉为最古老的计算机。算盘由框梁档珠组成，用算珠表示数字进行计算。算盘熟练者计算速度很快。明代程大位推广珠算，珠算口诀便于记忆。算盘和珠算是中华智慧的结晶，至今仍有使用。' },
    //ENC_END
  ]
};
